        public bool ExportToMarkdown(string filePath)
        {
            try
            {
                string fullText = PieceTable.GetText();
                string[] paras = fullText.Replace("\r\n", "\n").Split('\n');
                StringBuilder sb = new StringBuilder();
                int charOffset = 0;

                for (int p = 0; p < paras.Length; p++)
                {
                    string para = paras[p];
                    if (para.Trim() == "[--- PAGE BREAK ---]" || para.Contains("TRANG TRẮNG MỚI"))
                    {
                        sb.AppendLine();
                        sb.AppendLine("---");
                        sb.AppendLine();
                        charOffset += para.Length + 1;
                        continue;
                    }

                    if (para.Trim().StartsWith("|"))
                    {
                        sb.AppendLine(para);
                        charOffset += para.Length + 1;
                        continue;
                    }

                    if (string.IsNullOrWhiteSpace(para))
                    {
                        sb.AppendLine();
                        charOffset += para.Length + 1;
                        continue;
                    }

                    // Detect Heading
                    FormattedRun firstRun = GetFormatAt(charOffset);
                    string prefix = "";
                    if (firstRun != null && firstRun.Bold)
                    {
                        if (firstRun.FontSize >= 16f) prefix = "# ";
                        else if (firstRun.FontSize >= 14f) prefix = "## ";
                        else if (firstRun.FontSize >= 12.5f) prefix = "### ";
                    }

                    sb.Append(prefix);
                    int cur = 0;
                    while (cur < para.Length)
                    {
                        FormattedRun fmt = GetFormatAt(charOffset + cur);
                        int runLen = 1;
                        while (cur + runLen < para.Length && GetFormatAt(charOffset + cur + runLen) == fmt)
                        {
                            runLen++;
                        }

                        string runTxt = para.Substring(cur, runLen);
                        bool isHeading = !string.IsNullOrEmpty(prefix);

                        if (!isHeading && fmt != null && fmt.Bold && fmt.Italic) runTxt = $"***{runTxt}***";
                        else if (!isHeading && fmt != null && fmt.Bold) runTxt = $"**{runTxt}**";
                        else if (!isHeading && fmt != null && fmt.Italic) runTxt = $"*{runTxt}*";
                        else if (fmt != null && fmt.Strike) runTxt = $"~~{runTxt}~~";

                        sb.Append(runTxt);
                        cur += runLen;
                    }
                    sb.AppendLine();
                    charOffset += para.Length + 1;
                }

                File.WriteAllText(filePath, sb.ToString(), Encoding.UTF8);
                return true;
            }
            catch (Exception ex)
            {
                Console.WriteLine("WriterView.ExportToMarkdown error: " + ex.Message);
                return false;
            }
        }

        public bool ExportToHtml(string filepath)
        {
            try
            {
                string fullText = PieceTable.GetText();
                string[] paras = fullText.Replace("\r\n", "\n").Split('\n');
                StringBuilder htmlSb = new StringBuilder();
                string title = System.Net.WebUtility.HtmlEncode(Path.GetFileNameWithoutExtension(filepath));
                htmlSb.AppendLine("<!DOCTYPE html>");
                htmlSb.AppendLine("<html><head><meta charset=\"utf-8\">");
                htmlSb.AppendLine($"<title>{title}</title>");
                htmlSb.AppendLine("<style>");
                htmlSb.AppendLine("  body { background: #f1f5f9; font-family: 'Times New Roman', serif; margin: 0; padding: 40px 20px; }");
                htmlSb.AppendLine("  .doc-container { background: #ffffff; max-width: 816px; margin: 0 auto; padding: 72px; box-shadow: 0 4px 20px rgba(0,0,0,0.08); border-radius: 4px; box-sizing: border-box; }");
                htmlSb.AppendLine("  p { margin: 0 0 10pt 0; line-height: 1.45; font-size: 12pt; color: #1e293b; }");
                htmlSb.AppendLine("  .page-break { border: 0; border-top: 1px dashed #cbd5e1; margin: 30px 0; }");
                htmlSb.AppendLine("  table { width: 100%; border-collapse: collapse; margin: 16px 0; font-size: 11pt; }");
                htmlSb.AppendLine("  th, td { border: 1px solid #cbd5e1; padding: 8px 12px; text-align: left; }");
                htmlSb.AppendLine("  th { background-color: #f8fafc; font-weight: bold; }");
                htmlSb.AppendLine("</style>");
                htmlSb.AppendLine("</head><body>");
                htmlSb.AppendLine("<div class=\"doc-container\">");

                int charOffset = 0;
                for (int pIdx = 0; pIdx < paras.Length; pIdx++)
                {
                    string p = paras[pIdx];
                    if (p.Trim() == "[--- PAGE BREAK ---]" || p.Contains("TRANG TRẮNG MỚI"))
                    {
                        htmlSb.AppendLine("<hr class=\"page-break\" />");
                        charOffset += p.Length + 1;
                        continue;
                    }

                    if (p.Trim().StartsWith("|"))
                    {
                        List<string> tableLines = new List<string>();
                        int tblLen = 0;
                        while (pIdx < paras.Length && !string.IsNullOrWhiteSpace(paras[pIdx]) && paras[pIdx].Trim().StartsWith("|"))
                        {
                            tableLines.Add(paras[pIdx]);
                            tblLen += paras[pIdx].Length + 1;
                            pIdx++;
                        }
                        pIdx--;
                        WriteHtmlTable(htmlSb, tableLines);
                        charOffset += tblLen;
                        continue;
                    }

                    if (string.IsNullOrWhiteSpace(p))
                    {
                        htmlSb.AppendLine("<p>&nbsp;</p>");
                        charOffset += p.Length + 1;
                        continue;
                    }

                    int pAlign = 0;
                    if (ParagraphAlignments != null && ParagraphAlignments.ContainsKey(charOffset))
                    {
                        pAlign = ParagraphAlignments[charOffset];
                    }
                    string alignStyle = pAlign == 1 ? "text-align: center;" : (pAlign == 2 ? "text-align: right;" : (pAlign == 3 ? "text-align: justify;" : "text-align: left;"));

                    htmlSb.Append($"<p style=\"{alignStyle}\">");
                    int cur = 0;
                    while (cur < p.Length)
                    {
                        FormattedRun fmt = GetFormatAt(charOffset + cur);
                        int runLen = 1;
                        while (cur + runLen < p.Length && GetFormatAt(charOffset + cur + runLen) == fmt)
                        {
                            runLen++;
                        }

                        string runTxt = System.Net.WebUtility.HtmlEncode(p.Substring(cur, runLen));
                        StringBuilder styleSb = new StringBuilder();
                        if (fmt != null)
                        {
                            if (!string.IsNullOrEmpty(fmt.FontName) && fmt.FontName != "Times New Roman") styleSb.Append($"font-family: '{fmt.FontName}'; ");
                            if (fmt.FontSize > 0 && Math.Abs(fmt.FontSize - 12f) > 0.5f) styleSb.Append($"font-size: {fmt.FontSize:0.#}pt; ");
                            if (fmt.Color != Color.Empty && fmt.Color != Color.Transparent && fmt.Color != Color.Black)
                            {
                                styleSb.Append($"color: #{fmt.Color.R:X2}{fmt.Color.G:X2}{fmt.Color.B:X2}; ");
                            }
                            if (fmt.Highlight != Color.Empty && fmt.Highlight != Color.Transparent)
                            {
                                styleSb.Append($"background-color: #{fmt.Highlight.R:X2}{fmt.Highlight.G:X2}{fmt.Highlight.B:X2}; ");
                            }
                        }

                        if (fmt != null && fmt.Bold) runTxt = $"<b>{runTxt}</b>";
                        if (fmt != null && fmt.Italic) runTxt = $"<i>{runTxt}</i>";
                        if (fmt != null && fmt.Underline) runTxt = $"<u>{runTxt}</u>";
                        if (fmt != null && fmt.Strike) runTxt = $"<s>{runTxt}</s>";

                        if (styleSb.Length > 0)
                        {
                            htmlSb.Append($"<span style=\"{styleSb.ToString().Trim()}\">{runTxt}</span>");
                        }
                        else
                        {
                            htmlSb.Append(runTxt);
                        }

                        cur += runLen;
                    }
                    htmlSb.AppendLine("</p>");
                    charOffset += p.Length + 1;
                }

                htmlSb.AppendLine("</div>");
                htmlSb.AppendLine("</body></html>");
                File.WriteAllText(filepath, htmlSb.ToString(), Encoding.UTF8);
                return true;
            }
            catch (Exception ex)
            {
                Console.WriteLine("WriterView.ExportToHtml error: " + ex.Message);
                return false;
            }
        }

        private static void WriteHtmlTable(StringBuilder htmlSb, List<string> tableLines)
        {
            htmlSb.AppendLine("<table>");
            bool isFirst = true;
            foreach (var line in tableLines)
            {
                string tr = line.Trim();
                if (tr.Length < 2 || !tr.StartsWith("|")) continue;
                string stripped = tr.Replace("|", "").Replace("-", "").Replace(":", "").Trim();
                if (string.IsNullOrEmpty(stripped)) continue;

                string[] parts = tr.Split('|');
                htmlSb.AppendLine("  <tr>");
                for (int i = 1; i < parts.Length - 1; i++)
                {
                    string cell = System.Net.WebUtility.HtmlEncode(parts[i].Trim());
                    if (isFirst) htmlSb.AppendLine($"    <th>{cell}</th>");
                    else htmlSb.AppendLine($"    <td>{cell}</td>");
                }
                htmlSb.AppendLine("  </tr>");
                isFirst = false;
            }
            htmlSb.AppendLine("</table>");
        }

        public bool ExportToImages(string filePath, RibbonBar ribbon, bool allPages = true, bool isJpeg = false, IEnumerable<int> pageIndices = null)
        {
            try
            {
                string tempPdf = Path.Combine(Path.GetTempPath(), "GenOffice_Export_" + Guid.NewGuid().ToString("N") + ".pdf");
                if (!ExportToPdf(tempPdf, ribbon)) return false;

                var pdfDoc = ZenQOffice.Format.PdfHandler.LoadPdf(tempPdf);
                if (pdfDoc == null || pdfDoc.Pages.Count == 0) return false;

                var imgFormat = isJpeg ? System.Drawing.Imaging.ImageFormat.Jpeg : System.Drawing.Imaging.ImageFormat.Png;
                string ext = isJpeg ? ".jpg" : ".png";

                List<int> targetIndices = new List<int>();
                if (pageIndices != null)
                {
                    foreach (int p in pageIndices)
                    {
                        if (p >= 0 && p < pdfDoc.Pages.Count && !targetIndices.Contains(p))
                            targetIndices.Add(p);
                    }
                }
                else if (!allPages)
                {
                    int targetPage = Math.Max(0, Math.Min(pdfDoc.Pages.Count - 1, CurrentActivePage - 1));
                    targetIndices.Add(targetPage);
                }
                else
                {
                    for (int i = 0; i < pdfDoc.Pages.Count; i++)
                        targetIndices.Add(i);
                }

                if (targetIndices.Count == 0) return false;

                if (targetIndices.Count == 1)
                {
                    using (Bitmap bmp = ZenQOffice.Core.PdfConverterEngine.RenderPageBitmap(pdfDoc, targetIndices[0], 150f))
                    {
                        bmp.Save(filePath, imgFormat);
                    }
                }
                else
                {
                    string folder = Path.GetDirectoryName(filePath);
                    string baseName = Path.GetFileNameWithoutExtension(filePath);
                    for (int k = 0; k < targetIndices.Count; k++)
                    {
                        int i = targetIndices[k];
                        string outPath = Path.Combine(folder, $"{baseName}_Trang_{i + 1}{ext}");
                        using (Bitmap bmp = ZenQOffice.Core.PdfConverterEngine.RenderPageBitmap(pdfDoc, i, 150f))
                        {
                            bmp.Save(outPath, imgFormat);
                        }
                    }
                }

                try { File.Delete(tempPdf); } catch { }
                return true;
            }
            catch (Exception ex)
            {
                Console.WriteLine("WriterView.ExportToImages error: " + ex.Message);
                return false;
            }
        }

        public List<int> GetSelectedOrCurrentParagraphStarts()
        {
            List<int> result = new List<int>();
            string fullText = PieceTable.GetText();
            if (string.IsNullOrEmpty(fullText))
            {
                result.Add(0);
                return result;
            }

            int selMin = Math.Min(SelectionStart, SelectionEnd);
            int selMax = Math.Max(SelectionStart, SelectionEnd);
            bool hasSelection = (selMin != selMax);

            int curPStart = 0;
            string[] paras = fullText.Split('\n');
            for (int p = 0; p < paras.Length; p++)
            {
                int pEnd = curPStart + paras[p].Length; // end of paragraph text

                if (hasSelection)
                {
                    // Paragraph overlaps if selection intersects [curPStart, pEnd]
                    // If paragraph is non-empty: strictly overlaps if selMax > curPStart && selMin < pEnd
                    // If selection covers the newline at the end: selMax > curPStart && selMin <= pEnd
                    bool overlaps = (paras[p].Length > 0)
                        ? (selMax > curPStart && selMin < pEnd)
                        : (selMax > curPStart && selMin <= curPStart);

                    // Special case: if user selected across lines including the whole line
                    if (!overlaps && selMin <= curPStart && selMax >= pEnd && paras[p].Length > 0)
                    {
                        overlaps = true;
                    }

                    if (overlaps)
                    {
                        result.Add(curPStart);
                    }
                }
                else
                {
                    // Caret is inside this paragraph
                    if (p == paras.Length - 1)
                    {
                        if (CursorPosition >= curPStart)
                        {
                            result.Add(curPStart);
                        }
                    }
                    else
                    {
                        // Inside paragraph text (before newline)
                        if (CursorPosition >= curPStart && CursorPosition <= pEnd)
                        {
                            result.Add(curPStart);
                        }
                    }
                }

                curPStart = pEnd + 1;
            }

            if (result.Count == 0 && paras.Length > 0)
            {
                result.Add(0);
            }
            return result;
        }

        public void ApplyThemeToDocument(WriterThemeItem theme, RibbonBar ribbon)
        {
            if (theme == null || ribbon == null) return;
            SaveUndoState();

            ribbon.ActiveTheme = theme.Name;
            ribbon.ThemeFontHeading = theme.HeadingFont;
            ribbon.ThemeFontBody = theme.BodyFont;
            ribbon.ThemeColorPalette = theme.Palette;
            ribbon.SelectedFont = theme.BodyFont;
            ribbon.CurrentFontColor = Color.Black;

            Color accent = (theme.Palette != null && theme.Palette.Length > 0) ? theme.Palette[0] : Color.FromArgb(43, 87, 154);
            ribbon.PageBorderColor = accent;

            string fullText = PieceTable.GetText();
            int selMin = Math.Min(SelectionStart, SelectionEnd);
            int selMax = Math.Max(SelectionStart, SelectionEnd);
            bool hasSelection = (selMin != selMax);
            bool isSelectAll = (hasSelection && selMin == 0 && selMax >= fullText.Length && fullText.Length > 0);

            if (isSelectAll)
            {
                for (int r = 0; r < FormattedRuns.Count; r++)
                {
                    var run = FormattedRuns[r];
                    if (run.FontSize >= 14.0f || run.Bold)
                    {
                        run.FontName = theme.HeadingFont;
                        if (run.Color != Color.Transparent && run.Color != Color.Black)
                        {
                            run.Color = accent;
                        }
                    }
                    else
                    {
                        run.FontName = theme.BodyFont;
                    }
                }
                TypingFont = theme.BodyFont;
            }
            else if (hasSelection)
            {
                ApplyFormatToRange(selMin, selMax - selMin, theme.BodyFont, -1, null, null, null, null, null, null);
            }
            else
            {
                var targetPStarts = GetSelectedOrCurrentParagraphStarts();
                string[] paras = fullText.Split('\n');
                int curP = 0;
                for (int i = 0; i < paras.Length; i++)
                {
                    int pEnd = curP + paras[i].Length;
                    if (targetPStarts.Contains(curP))
                    {
                        ApplyFormatToRange(curP, paras[i].Length, theme.BodyFont, -1, null, null, null, null, null, null);
                    }
                    curP = pEnd + 1;
                }
            }
        }

        public void ApplyStyleSetToDocument(int styleSetIndex, RibbonBar ribbon)
        {
            if (ribbon == null) return;
            SaveUndoState();
            ribbon.ActiveStyleSetIndex = styleSetIndex;

            Color accent = (ribbon.ThemeColorPalette != null && ribbon.ThemeColorPalette.Length > 0)
                ? ribbon.ThemeColorPalette[0]
                : Color.FromArgb(43, 87, 154);

            string hFont = ribbon.ThemeFontHeading ?? "Calibri Light";
            string bFont = ribbon.ThemeFontBody ?? "Calibri";
            float ls = 1.15f;
            float beforePt = 0f;
            float afterPt = 8f;

            switch (styleSetIndex)
            {
                case 0: // Mặc định Word (Default Blue)
                    hFont = "Calibri Light"; bFont = "Calibri";
                    ls = 1.15f; beforePt = 0f; afterPt = 8f;
                    break;
                case 1: // Hiện đại / Tối giản (Modern Minimalist)
                    hFont = "Segoe UI Semibold"; bFont = "Segoe UI";
                    ls = 1.25f; beforePt = 2f; afterPt = 10f;
                    accent = Color.FromArgb(31, 41, 55);
                    break;
                case 2: // Thân mật (Casual)
                    hFont = "Segoe UI"; bFont = "Segoe UI";
                    ls = 1.20f; beforePt = 0f; afterPt = 6f;
                    accent = Color.FromArgb(37, 99, 235);
                    break;
                case 3: // Trang nhã (Elegant)
                    hFont = "Georgia"; bFont = "Garamond";
                    ls = 1.15f; beforePt = 0f; afterPt = 6f;
                    accent = Color.FromArgb(120, 53, 15);
                    break;
                case 4: // Đậm nét (Bold Modern)
                    hFont = "Arial"; bFont = "Arial";
                    ls = 1.20f; beforePt = 4f; afterPt = 8f;
                    accent = Color.Black;
                    break;
                case 5: // Đóng khung (Framed)
                    hFont = "Cambria"; bFont = "Cambria";
                    ls = 1.15f; beforePt = 2f; afterPt = 6f;
                    accent = Color.FromArgb(30, 41, 59);
                    break;
                case 6: // Đánh số (Numbered Classic)
                    hFont = "Calibri"; bFont = "Calibri";
                    ls = 1.15f; beforePt = 0f; afterPt = 6f;
                    accent = Color.FromArgb(29, 78, 216);
                    break;
                case 7: // Căn giữa (Centered)
                    hFont = "Aptos Display"; bFont = "Aptos";
                    ls = 1.20f; beforePt = 3f; afterPt = 8f;
                    accent = Color.FromArgb(13, 148, 136);
                    break;
                case 8: // Thanh viền (Teal Accent)
                    hFont = "Trebuchet MS"; bFont = "Segoe UI";
                    ls = 1.20f; beforePt = 2f; afterPt = 8f;
                    accent = Color.FromArgb(5, 150, 105);
                    break;
                case 9: // Đường đôi (Dual Lines)
                    hFont = "Calibri"; bFont = "Calibri";
                    ls = 1.15f; beforePt = 2f; afterPt = 8f;
                    accent = Color.FromArgb(21, 128, 61);
                    break;
                case 10: // Trang trọng (Executive)
                    hFont = "Times New Roman"; bFont = "Times New Roman";
                    ls = 1.25f; beforePt = 4f; afterPt = 8f;
                    accent = Color.FromArgb(131, 24, 67);
                    break;
            }

            string fullText = PieceTable.GetText();
            int selMin = Math.Min(SelectionStart, SelectionEnd);
            int selMax = Math.Max(SelectionStart, SelectionEnd);
            bool hasSelection = (selMin != selMax);
            bool isSelectAll = (hasSelection && selMin == 0 && selMax >= fullText.Length && fullText.Length > 0);

            var targetPStarts = GetSelectedOrCurrentParagraphStarts();

            if (isSelectAll)
            {
                ribbon.LineSpacingFactor = ls;
                ribbon.ParagraphSpacingBefore = beforePt;
                ribbon.ParagraphSpacingAfter = afterPt;

                ParagraphLineSpacings.Clear();
                ParagraphSpacingsBefore.Clear();
                ParagraphSpacingsAfter.Clear();

                for (int r = 0; r < FormattedRuns.Count; r++)
                {
                    var run = FormattedRuns[r];
                    if (run.FontSize >= 14.0f || run.Bold)
                    {
                        run.FontName = hFont;
                        if (run.Color != Color.Transparent && run.Color != Color.Black)
                        {
                            run.Color = accent;
                        }
                    }
                    else
                    {
                        run.FontName = bFont;
                    }
                }
                TypingFont = bFont;
            }
            else
            {
                foreach (int pStart in targetPStarts)
                {
                    ParagraphLineSpacings[pStart] = ls;
                    ParagraphSpacingsBefore[pStart] = beforePt;
                    ParagraphSpacingsAfter[pStart] = afterPt;
                }

                if (hasSelection)
                {
                    ApplyFormatToRange(selMin, selMax - selMin, bFont, -1, null, null, null, null, null, null);
                }
                else
                {
                    string[] paras = fullText.Split('\n');
                    int curP = 0;
                    for (int i = 0; i < paras.Length; i++)
                    {
                        int pEnd = curP + paras[i].Length;
                        if (targetPStarts.Contains(curP))
                        {
                            ApplyFormatToRange(curP, paras[i].Length, bFont, -1, null, null, null, null, null, null);
                        }
                        curP = pEnd + 1;
                    }
                }
            }
        }

