        }

        public struct LineSlot
        {
            public float StartX;
            public float Width;
            public float LineY;
            public float LineHeight;
            public int PageIndex;
        }

        private static readonly Dictionary<string, float> _fontLineSpacingRatios = new Dictionary<string, float>(StringComparer.OrdinalIgnoreCase);

        public static float GetFontLineSpacingRatio(string fontName)
        {
            if (string.IsNullOrEmpty(fontName)) fontName = "Times New Roman";
            float ratio;
            if (_fontLineSpacingRatios.TryGetValue(fontName, out ratio)) return ratio;

            try
            {
                using (var ff = new FontFamily(fontName))
                {
                    int em = ff.GetEmHeight(FontStyle.Regular);
                    if (em > 0)
                    {
                        int ascent = ff.GetCellAscent(FontStyle.Regular);
                        int descent = ff.GetCellDescent(FontStyle.Regular);
                        ratio = (ascent + descent) / (float)em;
                        if (ratio >= 1.0f && ratio <= 1.5f)
                        {
                            _fontLineSpacingRatios[fontName] = ratio;
                            return ratio;
                        }
                    }
                }
            }
            catch { }

            ratio = 1.1074f; // Standard Word fallback for Times New Roman / ECMA-376
            _fontLineSpacingRatios[fontName] = ratio;
            return ratio;
        }

        private List<LineSlot> GetLineSlotsForY(ref float currentY, float lineH, int textX, int maxTextW, int startPageY, ref int currentPage, int pageH, int bottomMarginY, int topMarginY = -1, RibbonBar ribbon = null)
        {
            if (topMarginY < 0) topMarginY = bottomMarginY;
            List<LineSlot> slots = new List<LineSlot>();

            // 1. Top and Bottom (WrapMode == 4): Nhảy hoàn toàn xuống dưới đáy của đối tượng
            bool jumped = true;
            while (jumped)
            {
                jumped = false;
                foreach (var sh in DocumentShapes)
                {
                    if (sh.WrapMode == 4 && !sh.LastBounds.IsEmpty)
                    {
                        if (currentY + lineH > sh.LastBounds.Top - 2 && currentY < sh.LastBounds.Bottom + 2)
                        {
                            currentY = sh.LastBounds.Bottom + (int)(10 * ZoomLevel);
                            jumped = true;
                            break;
                        }
                    }
                }
                foreach (var ch in DocumentCharts)
                {
                    if (ch.WrapMode == 4 && !ch.LastBounds.IsEmpty)
                    {
                        if (currentY + lineH > ch.LastBounds.Top - 2 && currentY < ch.LastBounds.Bottom + 2)
                        {
                            currentY = ch.LastBounds.Bottom + (int)(10 * ZoomLevel);
                            jumped = true;
                            break;
                        }
                    }
                }
                foreach (var kvp in TableFloatingBounds)
                {
                    int tIdx = kvp.Key;
                    int tWrap = TableWrapModes.ContainsKey(tIdx) ? TableWrapModes[tIdx] : 1;
                    if (tWrap == 4)
                    {
                        Rectangle tb = kvp.Value;
                        if (!tb.IsEmpty && currentY + lineH > tb.Top - 2 && currentY < tb.Bottom + 2)
                        {
                            currentY = tb.Bottom + (int)(10 * ZoomLevel);
                            jumped = true;
                            break;
                        }
                    }
                }
            }

            float baseH_inches = (ribbon != null && ribbon.PaperHeightInches > 0) ? ribbon.PaperHeightInches : 11.69f;
            if (ribbon != null && ribbon.IsLandscape)
            {
                float bW = (ribbon.PaperWidthInches > 0) ? ribbon.PaperWidthInches : 8.27f;
                baseH_inches = Math.Min(bW, baseH_inches);
            }
            float logicalPageH = baseH_inches * 96f;
            float logicalBottomMargin = (ribbon != null ? ribbon.GetEffectiveBottomMarginInches() : 1.0f) * 96f;
            float logicalTopMargin = (ribbon != null ? ribbon.GetEffectiveTopMarginInches() : 1.0f) * 96f;

            float pageBottomY = startPageY + currentPage * (pageH + 30) + (logicalPageH - logicalBottomMargin) * ZoomLevel;

            if (currentY + lineH > pageBottomY + 0.5f * ZoomLevel)
            {
                currentPage++;
                float newPageTopY = logicalTopMargin * ZoomLevel;
                currentY = startPageY + currentPage * (pageH + 30) + newPageTopY;
            }

            // 2. Square (1), Tight (2), Through (3): Tính toán các khe trống Trái & Phải
            Rectangle sideObstacle = Rectangle.Empty;
            int gap = (int)(10 * ZoomLevel);

            foreach (var sh in DocumentShapes)
            {
                if ((sh.WrapMode == 1 || sh.WrapMode == 2 || sh.WrapMode == 3) && !sh.LastBounds.IsEmpty)
                {
                    if (currentY + lineH > sh.LastBounds.Top - 2 && currentY < sh.LastBounds.Bottom + 2)
                    {
                        sideObstacle = sh.LastBounds;
                        break;
                    }
                }
            }
            if (sideObstacle.IsEmpty)
            {
                foreach (var ch in DocumentCharts)
                {
                    if ((ch.WrapMode == 1 || ch.WrapMode == 2 || ch.WrapMode == 3) && !ch.LastBounds.IsEmpty)
                    {
                        if (currentY + lineH > ch.LastBounds.Top - 2 && currentY < ch.LastBounds.Bottom + 2)
                        {
                            sideObstacle = ch.LastBounds;
                            break;
                        }
                    }
                }
            }
            if (sideObstacle.IsEmpty)
            {
                foreach (var kvp in TableFloatingBounds)
                {
                    int tIdx = kvp.Key;
                    int tWrap = TableWrapModes.ContainsKey(tIdx) ? TableWrapModes[tIdx] : 1;
                    if (tWrap == 1 || tWrap == 2 || tWrap == 3)
                    {
                        Rectangle tb = kvp.Value;
                        if (!tb.IsEmpty && currentY + lineH > tb.Top - 2 && currentY < tb.Bottom + 2)
                        {
                            sideObstacle = tb;
                            break;
                        }
                    }
                }
            }

            if (sideObstacle.IsEmpty)
            {
                slots.Add(new LineSlot { StartX = textX, Width = maxTextW, LineY = currentY, LineHeight = lineH, PageIndex = currentPage });
                return slots;
            }

            int minUsable = (int)(45 * ZoomLevel);
            int leftW = sideObstacle.Left - textX - gap;
            int rightStart = sideObstacle.Right + gap;
            int rightW = (textX + maxTextW) - rightStart;

            if (leftW >= minUsable)
            {
                slots.Add(new LineSlot { StartX = textX, Width = leftW, LineY = currentY, LineHeight = lineH, PageIndex = currentPage });
            }
            if (rightW >= minUsable)
            {
                slots.Add(new LineSlot { StartX = rightStart, Width = rightW, LineY = currentY, LineHeight = lineH, PageIndex = currentPage });
            }

            if (slots.Count == 0)
            {
                currentY = sideObstacle.Bottom + gap;
                float pageBottomY2 = startPageY + currentPage * (pageH + 30) + (logicalPageH - logicalBottomMargin) * ZoomLevel;
                if (currentY + lineH > pageBottomY2 + 0.5f * ZoomLevel)
                {
                    currentPage++;
                    float newPageTopY = logicalTopMargin * ZoomLevel;
                    currentY = startPageY + currentPage * (pageH + 30) + newPageTopY;
                }
                slots.Add(new LineSlot { StartX = textX, Width = maxTextW, LineY = currentY, LineHeight = lineH, PageIndex = currentPage });
            }

            return slots;
        }

        class ParaLayoutCache
        {
            public string Text;
            public float Zoom;
            public int MaxW;
            public int TextX;
            public float CurrentYOffset;
            public int CurrentPage;
            public List<WrapLineInfo> Lines;
            public float FinalYOffset;
            public int FinalPage;
        }
        private Dictionary<int, ParaLayoutCache> _paraLayoutCache = new Dictionary<int, ParaLayoutCache>();
        private int _lastLayoutTextVersion = -1;
        private int _lastLayoutRunsHash = 0;
        private float _lastLayoutZoom = 0;
        private int _lastLayoutMaxW = 0;
        private int _lastLayoutTextX = -1;
        private int _lastLayoutPageX = -1;
        private int _lastLayoutViewMode = -1;
        private string[] _cachedParagraphs = null;
        private int _cachedParagraphsVersion = -1;
        private int _lastShapesScannedVersion = -1;

        public void InvalidateLayoutAndTextCache()
        {
            _cachedParagraphs = null;
            _cachedParagraphsVersion = -1;
            _lastLayoutTextVersion = -1;
            _lastLayoutRunsHash = -1;
            _lastLayoutZoom = -1f;
            _lastLayoutMaxW = -1;
            _lastLayoutTextX = -1;
            _lastLayoutPageX = -1;
            _lastLayoutViewMode = -1;
            _lastShapesScannedVersion = -1;
            if (_paraLayoutCache != null) _paraLayoutCache.Clear();
            DocShapeObject.ClearTagParseCache();
            ClearCellLineCache();
            if (_wordMeasureCache != null) _wordMeasureCache.Clear();
        }

        private List<WrapLineInfo> LayoutParagraphLines(string para, int paraStartIndex, ref float currentY, ref int currentPage, int startPageY, int pageH, int marginY, int bottomMarginY, int textX, int maxTextW, D2DGraphics g, RibbonBar ribbon)
        {
            float pBefore = (ParagraphSpacingsBefore.ContainsKey(paraStartIndex)) ? ParagraphSpacingsBefore[paraStartIndex] : (ribbon != null ? ribbon.ParagraphSpacingBefore : 0f);
            if (pBefore > 0)
            {
                currentY += pBefore * ZoomLevel;
            }

            float pLineSpacing = (ParagraphLineSpacings.ContainsKey(paraStartIndex)) ? ParagraphLineSpacings[paraStartIndex] : (ribbon != null ? ribbon.LineSpacingFactor : 1.15f);
            float pAfter = (ParagraphSpacingsAfter.ContainsKey(paraStartIndex)) ? ParagraphSpacingsAfter[paraStartIndex] : (ribbon != null ? ribbon.ParagraphSpacingAfter : 0f);

            float pFirstLine = GetFirstLineIndent(paraStartIndex);
            float pHanging = GetHangingIndent(paraStartIndex);
            float pLeft = GetLeftIndent(paraStartIndex);
            float pRight = GetRightIndent(paraStartIndex);

            float yOffset = currentY - startPageY;
            ParaLayoutCache cache = null;
            if (_paraLayoutCache.TryGetValue(paraStartIndex, out cache))
            {
                if (cache.Text == para && cache.Zoom == ZoomLevel && cache.MaxW == maxTextW && cache.TextX == textX && Math.Abs(cache.CurrentYOffset - yOffset) < 0.05f)
                {
                    currentY = startPageY + cache.FinalYOffset;
                    currentPage = cache.FinalPage;
                    List<WrapLineInfo> cachedResult = new List<WrapLineInfo>(cache.Lines.Count);
                    foreach (var l in cache.Lines)
                    {
                        var cl = l;
                        cl.LineY = startPageY + l.LineY;
                        cachedResult.Add(cl);
                    }
                    return cachedResult;
                }
            }

            int startCurrentPage = currentPage;
            List<WrapLineInfo> result = new List<WrapLineInfo>();
            if (string.IsNullOrEmpty(para))
            {
                float pFontSize = TypingFontSize;
                if (FormattedRuns != null && FormattedRuns.Count > 0)
                {
                    for (int ri = 0; ri < FormattedRuns.Count; ri++)
                    {
                        if (FormattedRuns[ri].StartIndex <= paraStartIndex && FormattedRuns[ri].StartIndex + FormattedRuns[ri].Length >= paraStartIndex)
                        {
                            if (FormattedRuns[ri].FontSize > 0) { pFontSize = FormattedRuns[ri].FontSize; break; }
                        }
                    }
                }
                float fontRatio = GetFontLineSpacingRatio(TypingFont);
                float logicalLH = Math.Max(12.0f, pFontSize * 1.333333f * fontRatio) * pLineSpacing;
                float lH = logicalLH * ZoomLevel;
                float indentScale = 1.333333f;
                float baseW_inches = (ribbon != null && ribbon.PaperWidthInches > 0) ? ribbon.PaperWidthInches : 8.27f;
                float baseH_inches = (ribbon != null && ribbon.PaperHeightInches > 0) ? ribbon.PaperHeightInches : 11.69f;
                if (ribbon != null && ribbon.IsLandscape)
                {
                    baseW_inches = Math.Max(baseW_inches, baseH_inches);
                }
                else
                {
                    baseW_inches = Math.Min(baseW_inches, baseH_inches);
                }
                float basePageW = baseW_inches * 96f;
                float baseLeftM = (ribbon != null ? ribbon.GetEffectiveLeftMarginInches() : 1.0f) * 96f;
                float baseRightM = (ribbon != null ? ribbon.GetEffectiveRightMarginInches() : 1.0f) * 96f;
                float baseMaxTextW = (basePageW - baseLeftM - baseRightM);
                float logicalIndent = (pLeft + pFirstLine + pRight) * indentScale;
                float logicalMaxW = Math.Max(30f, baseMaxTextW - logicalIndent);
                int effMaxW = (int)Math.Round(logicalMaxW * ZoomLevel);
                int effStartX = textX + (int)Math.Round((pLeft + pFirstLine) * indentScale * ZoomLevel);
                var slots = GetLineSlotsForY(ref currentY, lH, effStartX, effMaxW, startPageY, ref currentPage, pageH, bottomMarginY, marginY, ribbon);
                var slot = slots[0];

                result.Add(new WrapLineInfo
                {
                    Text = "",
                    StartIndex = paraStartIndex,
                    Length = 0,
                    StartX = slot.StartX,
                    Width = slot.Width,
                    LineY = slot.LineY,
                    LineHeight = lH,
                    MaxFontSize = TypingFontSize,
                    IsLastInPara = true,
                    MeasuredWidth = 0f
                });
                currentY += lH;
                if (pAfter > 0)
                {
                    currentY += pAfter * ZoomLevel;
                }
                
                _paraLayoutCache[paraStartIndex] = new ParaLayoutCache {
                    Text = para, Zoom = ZoomLevel, MaxW = maxTextW, TextX = textX,
                    CurrentYOffset = yOffset, CurrentPage = startCurrentPage,
                    FinalYOffset = currentY - startPageY, FinalPage = currentPage,
                    Lines = result.ConvertAll(l => { var cl = l; cl.LineY -= startPageY; return cl; })
                };
                return result;
            }

            DropCapInfo dcInfo = null;
            float dcIndentW = 0f;
            if (ParagraphDropCaps.TryGetValue(paraStartIndex, out dcInfo) && dcInfo != null && dcInfo.Lines > 1 && !string.IsNullOrEmpty(para))
            {
                char dcChar = para[0];
                float baseFS = TypingFontSize;
                if (FormattedRuns != null && FormattedRuns.Count > 0)
                {
                    for (int ri = 0; ri < FormattedRuns.Count; ri++)
                    {
                        if (FormattedRuns[ri].StartIndex <= paraStartIndex && FormattedRuns[ri].StartIndex + FormattedRuns[ri].Length >= paraStartIndex)
                        {
                            if (FormattedRuns[ri].FontSize > 0) { baseFS = FormattedRuns[ri].FontSize; break; }
                        }
                    }
                }
                float dcFS = baseFS * (dcInfo.Lines - 0.2f);
                dcIndentW = MeasureSubstringLogicalWidth(g, dcChar.ToString(), paraStartIndex, 0, 1) * (dcFS / Math.Max(1f, baseFS)) + 8f;
            }

            // 1. Fast tokenization into word tokens with exact character offsets
            List<string> tokens = new List<string>();
            List<int> tokenStarts = new List<int>();
            int pPos = (dcInfo != null && para.Length > 0) ? 1 : 0;
            while (pPos < para.Length)
            {
                int tStart = pPos;
                bool isTag = false;
                if (pPos + 8 <= para.Length && para[pPos] == '!' && para[pPos+1] == '[')
                {
                    string pfx = para.Substring(pPos, 8);
                    if (pfx == "![IMAGE:" || pfx == "![SHAPE:")
                    {
                        int endIdx = para.IndexOf(']', pPos);
                        if (endIdx > pPos)
                        {
                            pPos = endIdx + 1;
                            tokens.Add(para.Substring(tStart, pPos - tStart));
                            tokenStarts.Add(paraStartIndex + tStart);
                            isTag = true;
                        }
                    }
                }
                if (isTag) continue;

                while (pPos < para.Length && para[pPos] != ' ' && para[pPos] != '\t' && para[pPos] != '\u00A0' && !char.IsWhiteSpace(para[pPos]))
                {
                    if (pPos + 8 <= para.Length && para[pPos] == '!' && para[pPos+1] == '[')
                    {
                        string pfx = para.Substring(pPos, 8);
                        if (pfx == "![IMAGE:" || pfx == "![SHAPE:") break;
                    }
                    pPos++;
                }
                while (pPos < para.Length && (para[pPos] == ' ' || para[pPos] == '\t' || para[pPos] == '\u00A0' || char.IsWhiteSpace(para[pPos])))
                {
                    pPos++;
                }
                if (pPos == tStart) pPos++;
                tokens.Add(para.Substring(tStart, pPos - tStart));
                tokenStarts.Add(paraStartIndex + tStart);
            }

            float[] tokenLogicalWidths = new float[tokens.Count];
            float[] tokenMaxFontSizes = new float[tokens.Count];
            for (int ti = 0; ti < tokens.Count; ti++)
            {
                tokenLogicalWidths[ti] = MeasureSubstringLogicalWidth(g, tokens[ti], tokenStarts[ti], 0, tokens[ti].Length);
                FormattedRun fr = GetFormatAt(tokenStarts[ti]);
                tokenMaxFontSizes[ti] = fr.FontSize;
            }

            int tokenIdx = 0;
            while (tokenIdx < tokens.Count)
            {
                // First line uses (pLeft + pFirstLine), following lines use (pLeft + pHanging)
                float indentScale = 1.333333f;
                float baseW_inches = (ribbon != null && ribbon.PaperWidthInches > 0) ? ribbon.PaperWidthInches : 8.27f;
                float baseH_inches = (ribbon != null && ribbon.PaperHeightInches > 0) ? ribbon.PaperHeightInches : 11.69f;
                if (ribbon != null && ribbon.IsLandscape)
                {
                    baseW_inches = Math.Max(baseW_inches, baseH_inches);
                }
                else
                {
                    baseW_inches = Math.Min(baseW_inches, baseH_inches);
                }
                float basePageW = baseW_inches * 96f;
                float baseLeftM = (ribbon != null ? ribbon.GetEffectiveLeftMarginInches() : 1.0f) * 96f;
                float baseRightM = (ribbon != null ? ribbon.GetEffectiveRightMarginInches() : 1.0f) * 96f;
                float baseMaxTextW = (basePageW - baseLeftM - baseRightM);
                float logicalIndent = (result.Count == 0) ? (pLeft + pFirstLine + pRight) * indentScale : (pLeft + pHanging + pRight) * indentScale;
                float logicalMaxW = Math.Max(30f, baseMaxTextW - logicalIndent);

                // Indent lines that wrap alongside the Drop Cap
                if (dcInfo != null && !dcInfo.InMargin && result.Count < dcInfo.Lines)
                {
                    logicalMaxW = Math.Max(30f, logicalMaxW - dcIndentW);
                }

                int effMaxW = (int)Math.Round(logicalMaxW * ZoomLevel);
                float logicalStartX = (result.Count == 0) ? (pLeft + pFirstLine) * indentScale : (pLeft + pHanging) * indentScale;
                if (dcInfo != null && !dcInfo.InMargin && result.Count < dcInfo.Lines) logicalStartX += dcIndentW;
                int effStartX = textX + (int)Math.Round(logicalStartX * ZoomLevel);

                // Step 1: Scan which tokens ACTUALLY fit on this line!
                int startTok = tokenIdx;
                int endTok = tokenIdx;
                float logicalCurW = 0f;
                float lineMaxFS = 11.0f;
                float lineMaxShapeH = 0f;

                while (endTok < tokens.Count)
                {
                    string tok = tokens[endTok];
                    float logicalTokW = tokenLogicalWidths[endTok];

                    if (logicalCurW + logicalTokW > logicalMaxW && endTok > startTok)
                    {
                        bool effHyphen = (ribbon != null && ribbon.IsHyphenationEnabled) || IsHyphenationEnabled;
                        if (effHyphen && tok.Length >= 6 && !tok.StartsWith("![") && !tok.Contains(" "))
                        {
                            float remainW = logicalMaxW - logicalCurW;
                            int bestSplit = -1;
                            float bestSplitW = 0f;
                            for (int sLen = tok.Length - 2; sLen >= 3; sLen--)
                            {
                                string headPart = tok.Substring(0, sLen) + "-";
                                float headW = MeasureSubstringLogicalWidth(g, headPart, tokenStarts[endTok], 0, headPart.Length);
                                if (headW <= remainW)
                                {
                                    bestSplit = sLen;
                                    bestSplitW = headW;
                                    break;
                                }
                            }
                            if (bestSplit >= 3)
                            {
                                string headTok = tok.Substring(0, bestSplit) + "-";
                                string tailTok = tok.Substring(bestSplit);
                                tokens[endTok] = headTok;
                                tokenLogicalWidths[endTok] = bestSplitW;
                                logicalCurW += bestSplitW;
                                endTok++;
                                tokens.Insert(endTok, tailTok);
                                tokenStarts.Insert(endTok, tokenStarts[endTok - 1] + bestSplit);
                                var newW = new float[tokens.Count];
                                var newFS = new float[tokens.Count];
                                for (int k = 0; k < endTok; k++) { newW[k] = tokenLogicalWidths[k]; newFS[k] = tokenMaxFontSizes[k]; }
                                newW[endTok] = MeasureSubstringLogicalWidth(g, tailTok, tokenStarts[endTok], 0, tailTok.Length);
                                newFS[endTok] = tokenMaxFontSizes[endTok - 1];
                                for (int k = endTok + 1; k < tokens.Count; k++) { newW[k] = tokenLogicalWidths[k - 1]; newFS[k] = tokenMaxFontSizes[k - 1]; }
                                tokenLogicalWidths = newW;
                                tokenMaxFontSizes = newFS;
                                break;
                            }
                        }
                        break; // Does not fit on this line; wrap to next line!
                    }

                    logicalCurW += logicalTokW;

                    // Track max font size and shape height for tokens on THIS line ONLY!
                    if (tokenMaxFontSizes[endTok] > lineMaxFS) lineMaxFS = tokenMaxFontSizes[endTok];

                    if (tok.StartsWith("![IMAGE:") || tok.StartsWith("![SHAPE:"))
                    {
                        string shapeId = "", shapeType = "", imgPath = "";
                        int tX, tY, tW, tH, tWrap, tPage, tStyle, tYRel;
                        DocShapeObject.ParseShapeTag(tok, out shapeId, out shapeType, out imgPath, out tX, out tY, out tW, out tH, out tWrap, out tPage, out tStyle, out tYRel);
                        if (tWrap == 0)
                        {
                            DocShapeObject shp = GetOrCreateDocShape(string.IsNullOrEmpty(shapeId) ? "Temp" : shapeId, shapeType);
                            if (shp == ActiveShape && DragShapeHandleIndex >= 0)
                            {
                                lineMaxShapeH = Math.Max(lineMaxShapeH, (float)Math.Max(15, shp.BaseHeight + shp.HeightDelta) * ZoomLevel);
                            }
                            else if (tH > 0) lineMaxShapeH = Math.Max(lineMaxShapeH, (float)tH * ZoomLevel);
                            else {
                                lineMaxShapeH = Math.Max(lineMaxShapeH, (float)Math.Max(15, shp.BaseHeight + shp.HeightDelta) * ZoomLevel);
                            }
                        }
                    }

                    endTok++;
                }

                if (endTok == startTok)
                {
                    string tok = tokens[startTok];
                    if (tok.StartsWith("![IMAGE:") || tok.StartsWith("![SHAPE:") || tok.Length <= 1)
                    {
                        endTok = startTok + 1;
                    }
                    else
                    {
                        int fitChars = 1;
                        float accumulatedW = 0f;
                        for (int c = 1; c < tok.Length; c++)
                        {
                            string sub = tok.Substring(0, c);
                            float w = MeasureSubstringLogicalWidth(g, sub, tokenStarts[startTok], 0, sub.Length);
                            if (w <= logicalMaxW)
                            {
                                fitChars = c;
                                accumulatedW = w;
                            }
                            else
                            {
                                break;
                            }
                        }

                        string headTok = tok.Substring(0, fitChars);
                        string tailTok = tok.Substring(fitChars);
                        tokens[startTok] = headTok;
                        tokenLogicalWidths[startTok] = accumulatedW > 0 ? accumulatedW : MeasureSubstringLogicalWidth(g, headTok, tokenStarts[startTok], 0, headTok.Length);

                        tokens.Insert(startTok + 1, tailTok);
                        tokenStarts.Insert(startTok + 1, tokenStarts[startTok] + fitChars);

                        var newW = new float[tokens.Count];
                        var newFS = new float[tokens.Count];
                        for (int k = 0; k <= startTok; k++) { newW[k] = tokenLogicalWidths[k]; newFS[k] = tokenMaxFontSizes[k]; }
                        newW[startTok + 1] = MeasureSubstringLogicalWidth(g, tailTok, tokenStarts[startTok + 1], 0, tailTok.Length);
                        newFS[startTok + 1] = tokenMaxFontSizes[startTok];
                        for (int k = startTok + 2; k < tokens.Count; k++) { newW[k] = tokenLogicalWidths[k - 1]; newFS[k] = tokenMaxFontSizes[k - 1]; }
                        tokenLogicalWidths = newW;
                        tokenMaxFontSizes = newFS;

                        endTok = startTok + 1;
                    }
                }

                // Step 2: Calculate line height strictly from the tokens that are ON THIS LINE!
                float fontRatio = GetFontLineSpacingRatio(TypingFont);
                float logicalLH = Math.Max(Math.Max(13.5f, lineMaxFS * 1.333333f * fontRatio) * pLineSpacing, 
                                    lineMaxShapeH > 0 ? (lineMaxShapeH / Math.Max(0.01f, ZoomLevel) + 4) : 0);
                float lH = logicalLH * ZoomLevel;

                // Step 3: Check pagination and floating obstacles for this line height
                var slots = GetLineSlotsForY(ref currentY, lH, effStartX, effMaxW, startPageY, ref currentPage, pageH, bottomMarginY, marginY, ribbon);

                // Step 4: Populate line(s) into slots
                foreach (var slot in slots)
                {
                    if (tokenIdx >= endTok) break;

                    int currentLineCharStart = tokenStarts[tokenIdx];
                    StringBuilder lineSb = new StringBuilder();
                    float slotLogicalCurW = 0;
                    int firstInSlot = tokenIdx;
                    float slotMaxFS = 11.0f;
                    float slotLogicalSlotW = (slot.Width >= effMaxW - 5) ? logicalMaxW : (slot.Width / Math.Max(0.01f, ZoomLevel));

                    while (tokenIdx < endTok)
                    {
                        string tok = tokens[tokenIdx];
                        float logicalTokW = tokenLogicalWidths[tokenIdx];

                        if (slotLogicalCurW + logicalTokW > slotLogicalSlotW && tokenIdx > firstInSlot)
                        {
                            break; // Slot is full (e.g. side obstacle)
                        }

                        lineSb.Append(tok);
                        slotLogicalCurW += logicalTokW;

                        if (tokenMaxFontSizes[tokenIdx] > slotMaxFS) slotMaxFS = tokenMaxFontSizes[tokenIdx];

                        tokenIdx++;
                    }

                    string lineText = lineSb.ToString();
                    bool isLast = (tokenIdx >= tokens.Count);

                    result.Add(new WrapLineInfo
                    {
                        Text = lineText,
                        StartIndex = currentLineCharStart,
                        Length = lineText.Length,
                        StartX = slot.StartX,
                        Width = slot.Width,
                        LineY = slot.LineY,
                        LineHeight = lH,
                        MaxFontSize = Math.Max(slotMaxFS, lineMaxFS),
                        IsLastInPara = isLast,
                        MeasuredWidth = (float)Math.Round(slotLogicalCurW * ZoomLevel)
                    });
                }

                currentY += lH;
            }

            if (pAfter > 0)
            {
                currentY += pAfter * ZoomLevel;
            }

            _paraLayoutCache[paraStartIndex] = new ParaLayoutCache {
                Text = para, Zoom = ZoomLevel, MaxW = maxTextW, TextX = textX,
                CurrentYOffset = yOffset, CurrentPage = startCurrentPage,
                FinalYOffset = currentY - startPageY, FinalPage = currentPage,
                Lines = result.ConvertAll(l => { var cl = l; cl.LineY -= startPageY; return cl; })
            };

            return result;
        }

        private List<WrappedLine> WrapParagraph(string para, Graphics g, int maxWidth, int paraStartIndex)
        {
            List<WrappedLine> lines = new List<WrappedLine>();
            if (string.IsNullOrEmpty(para))
            {
                lines.Add(new WrappedLine { Text = "", StartIndex = paraStartIndex, Length = 0, IsLastInPara = true, MaxFontSize = TypingFontSize });
                return lines;
            }

            string[] words = para.Split(' ');
            string currentLine = "";
            int currentLineStart = paraStartIndex;
            float maxFS = 11.0f;

            for (int i = 0; i < words.Length; i++)
            {
                string word = words[i];
                int wordStart = currentLineStart + (string.IsNullOrEmpty(currentLine) ? 0 : currentLine.Length + 1);
                FormattedRun wordFormat = GetFormatAt(wordStart);
                maxFS = Math.Max(maxFS, wordFormat.FontSize);

                FontStyle style = FontStyle.Regular;
                if (wordFormat.Bold) style |= FontStyle.Bold;
                if (wordFormat.Italic) style |= FontStyle.Italic;

                using (Font wordFont = new Font(wordFormat.FontName, wordFormat.FontSize * ZoomLevel, style))
                {
                    string testLine = string.IsNullOrEmpty(currentLine) ? word : currentLine + " " + word;
                    SizeF size = g.MeasureString(testLine, wordFont, Point.Empty, StringFormat.GenericTypographic);

                    if (size.Width > maxWidth && !string.IsNullOrEmpty(currentLine))
                    {
                        lines.Add(new WrappedLine { Text = currentLine, StartIndex = currentLineStart, Length = currentLine.Length, IsLastInPara = false, MaxFontSize = maxFS });
                        currentLineStart += currentLine.Length + 1;
                        currentLine = word;
                        maxFS = wordFormat.FontSize;
                    }
                    else
                    {
                        currentLine = testLine;
                    }
                }
            }

            if (!string.IsNullOrEmpty(currentLine))
            {
                lines.Add(new WrappedLine { Text = currentLine, StartIndex = currentLineStart, Length = currentLine.Length, IsLastInPara = true, MaxFontSize = maxFS });
            }

            return lines;
        }

        public void Copy()
        {
            if (ActiveShape != null)
            {
                Image imgToCopy = ActiveShape.CachedImage;
                if (imgToCopy == null && !string.IsNullOrEmpty(ActiveShape.ImagePath) && System.IO.File.Exists(ActiveShape.ImagePath))
                {
                    try { imgToCopy = Image.FromFile(ActiveShape.ImagePath); } catch { }
                }
                if (imgToCopy == null && (ActiveShape.ShapeType == "SmartArt" || !string.IsNullOrEmpty(ActiveShape.SmartArtType)))
                {
                    try
                    {
                        int rw = Math.Max(120, ActiveShape.BaseWidth + ActiveShape.WidthDelta);
                        int rh = Math.Max(80, ActiveShape.BaseHeight + ActiveShape.HeightDelta);
                        imgToCopy = SmartArtRenderer.RenderToBitmap(ActiveShape, rw, rh, 2.0f);
                    }
                    catch { }
                }
                else if (imgToCopy == null && ActiveShape.ShapeType != "Image")
                {
                    try
                    {
                        int rw = Math.Max(80, ActiveShape.BaseWidth + ActiveShape.WidthDelta);
                        int rh = Math.Max(60, ActiveShape.BaseHeight + ActiveShape.HeightDelta);
                        imgToCopy = SmartArtRenderer.RenderShapeToBitmap(ActiveShape, rw, rh, 2.0f);
                    }
                    catch { }
                }

                if (imgToCopy != null)
                {
                    try
                    {
                        using (Bitmap copyBmp = new Bitmap(imgToCopy))
                        {
                            Clipboard.SetImage(copyBmp);
                        }
                        return;
                    }
                    catch { }
                }
                else if (!string.IsNullOrEmpty(ActiveShape.TextContent))
                {
                    try { Clipboard.SetText(ActiveShape.TextContent); return; } catch { }
                }
            }

            if (SelectedColumnTableIndex >= 0 && SelectedColumnIndex >= 0 && TableCharRanges.ContainsKey(SelectedColumnTableIndex))
            {
                int tblIdx = SelectedColumnTableIndex;
                int minCol = Math.Min(SelectedColumnIndex, SelectedColumnEndIndex);
                int maxCol = Math.Max(SelectedColumnIndex, SelectedColumnEndIndex);
                int tblStart = TableCharRanges[tblIdx][0];
                int tblLen = TableCharRanges[tblIdx][1];
                string fullText = PieceTable.GetText();
                if (tblStart >= 0 && tblStart + tblLen <= fullText.Length)
                {
                    string tableText = fullText.Substring(tblStart, tblLen);
                    string[] lines = tableText.Split('\n');
                    List<string> rowTexts = new List<string>();
                    for (int i = 0; i < lines.Length; i++)
                    {
                        string l = lines[i];
                        if (!string.IsNullOrWhiteSpace(l) && l.Trim().StartsWith("|") && !l.Contains("---") && !l.Contains("==="))
                        {
                            string[] cells = l.Split('|');
                            List<string> colCells = new List<string>();
                            for (int c = 1; c < cells.Length - 1; c++)
                            {
                                int colIdx = c - 1;
                                if (colIdx >= minCol && colIdx <= maxCol)
                                {
                                    colCells.Add(cells[c].Trim());
                                }
                            }
                            if (colCells.Count > 0)
                            {
                                rowTexts.Add(string.Join("\t", colCells.ToArray()));
                            }
                        }
                    }
                    if (rowTexts.Count > 0)
                    {
                        Clipboard.SetText(string.Join("\r\n", rowTexts.ToArray()));
                        return;
                    }
                }
            }

            if (SelectionStart != SelectionEnd)
            {
                int min = Math.Min(SelectionStart, SelectionEnd);
                int len = Math.Abs(SelectionEnd - SelectionStart);
                string full = PieceTable.GetText();
                if (min >= 0 && min + len <= full.Length)
                {
                    string sub = full.Substring(min, len);
                    Clipboard.SetText(sub);
                }
            }
        }

        public void Cut()
        {
            if (ActiveShape != null)
            {
                Copy();
                DeleteActiveShape();
                return;
            }

            if (SelectedColumnTableIndex >= 0 && SelectedColumnIndex >= 0)
            {
                Copy();
                ClearSelectedColumnsText();
                return;
            }

            if (SelectionStart != SelectionEnd)
            {
                Copy();
                DeleteSelection();
            }
        }

        public void DeleteSelectedColumns()
        {
            if (SelectedColumnTableIndex < 0 || SelectedColumnIndex < 0) return;
            int tblIdx = SelectedColumnTableIndex;
            int minCol = Math.Min(SelectedColumnIndex, SelectedColumnEndIndex);
            int maxCol = Math.Max(SelectedColumnIndex, SelectedColumnEndIndex);
            SelectedColumnTableIndex = -1;
            SelectedColumnIndex = -1;
            SelectedColumnEndIndex = -1;
            for (int c = maxCol; c >= minCol; c--)
            {
                DeleteTableColumn(tblIdx, c);
            }
        }

        public void ClearSelectedColumnsText()
        {
            if (SelectedColumnTableIndex < 0 || SelectedColumnIndex < 0) return;
            int tblIdx = SelectedColumnTableIndex;
            int minCol = Math.Min(SelectedColumnIndex, SelectedColumnEndIndex);
            int maxCol = Math.Max(SelectedColumnIndex, SelectedColumnEndIndex);
            if (!TableCharRanges.ContainsKey(tblIdx)) return;
            int tblStart = TableCharRanges[tblIdx][0];
            int tblLen = TableCharRanges[tblIdx][1];
            string fullText = PieceTable.GetText();
            if (tblStart < 0 || tblStart + tblLen > fullText.Length) return;

            string tableText = fullText.Substring(tblStart, tblLen);
            string[] lines = tableText.Split('\n');
            List<string> newLines = new List<string>();

            for (int i = 0; i < lines.Length; i++)
            {
                string l = lines[i];
                if (!string.IsNullOrWhiteSpace(l) && l.Trim().StartsWith("|") && !l.Contains("---") && !l.Contains("==="))
                {
                    string[] cells = l.Split('|');
                    for (int c = 1; c < cells.Length - 1; c++)
                    {
                        int colIdx = c - 1;
                        if (colIdx >= minCol && colIdx <= maxCol)
                        {
                            cells[c] = "   ";
                        }
                    }
                    newLines.Add(string.Join("|", cells));
                }
                else
                {
                    newLines.Add(l);
                }
            }

            string newTableText = string.Join("\n", newLines.ToArray());
            string newDocText = fullText.Substring(0, tblStart) + newTableText + fullText.Substring(tblStart + tblLen);
            SaveUndoState();
            PieceTable.SetInitialText(newDocText);
        }

        public void GetPageLayoutMetrics(int canvasW, RibbonBar ribbon, out int pageX, out int pageW, out int pageH, out int marginX, out int rightMarginX, out int marginY)
        {
            float baseW = (ribbon != null && ribbon.PaperWidthInches > 0) ? ribbon.PaperWidthInches : 8.27f;
            float baseH = (ribbon != null && ribbon.PaperHeightInches > 0) ? ribbon.PaperHeightInches : 11.69f;
            if (ribbon != null && ribbon.IsLandscape)
            {
                float tmpW = Math.Max(baseW, baseH);
                float tmpH = Math.Min(baseW, baseH);
                baseW = tmpW;
                baseH = tmpH;
            }
            else
            {
                float tmpW = Math.Min(baseW, baseH);
                float tmpH = Math.Max(baseW, baseH);
                baseW = tmpW;
                baseH = tmpH;
            }
            int stdW = (int)Math.Round(baseW * 96f);
            int stdH = (int)Math.Round(baseH * 96f);
            if (ViewMode == 2) { stdW = Math.Max(700, (int)((canvasW - 80) / Math.Max(0.2f, ZoomLevel))); } // Web mode

            pageW = (int)Math.Round(stdW * ZoomLevel);
            pageH = (int)Math.Round(stdH * ZoomLevel);

            float leftMarginInches = ribbon != null ? ribbon.GetEffectiveLeftMarginInches() : 1.0f;
            float rightMarginInches = ribbon != null ? ribbon.GetEffectiveRightMarginInches() : 1.0f;
            float topMarginInches = ribbon != null ? ribbon.GetEffectiveTopMarginInches() : 1.0f;

            marginX = (int)Math.Round(leftMarginInches * 96 * ZoomLevel);
            rightMarginX = (int)Math.Round(rightMarginInches * 96 * ZoomLevel);
            marginY = (int)Math.Round(topMarginInches * 96 * ZoomLevel);

            int navOffset = ShowNavigationPane ? 280 : 0;
            int selPaneOffset = ShowSelectionPane ? 260 : 0;
            int effectiveCanvasW = canvasW - navOffset - selPaneOffset;

            if (ViewMode == 0)
            {
                pageX = Math.Max(70, (canvasW - pageW) / 2);
            }
            else if (pageW + 80 <= effectiveCanvasW)
            {
                pageX = navOffset + (effectiveCanvasW - pageW) / 2;
                if (ScrollX != 0f) { ScrollX = 0f; TargetScrollX = 0f; SmoothScrollX = 0f; }
            }
            else
            {
                int maxScrollX = Math.Max(0, (pageW + 80) - effectiveCanvasW);
                if (ScrollX > maxScrollX) { ScrollX = maxScrollX; TargetScrollX = maxScrollX; SmoothScrollX = maxScrollX; }
                pageX = navOffset + 40 - (int)Math.Round(ScrollX);
            }
        }

        public void DrawInteractiveRuler(D2DGraphics g, int pageX, int pageW, int marginX, int rightMarginX, int canvasW, int canvasH, RibbonBar ribbon)
        {
            int rulerH = 24;
            int rulerY = 156; // Fixed directly below Ribbon (Y: 156..180), pinned at top, NOT moving with ScrollY!
            int curPStart = GetCurrentParagraphStart();

            // Note: Horizontal ruler renders strictly over the document page (pageX..pageX+pageW)
            // and the tab selector at (navOffset+2), leaving the workspace background and Navigation Pane completely unobstructed!

            // 1. Tab Selector Button on the Far Left Corner (Ô vuông chọn kiểu Tab Stop)
            int navOffset = ShowNavigationPane ? 280 : 0;
            int tabBtnW = 22;
            int tabBtnX = navOffset + 2;
            RulerTabSelectorRect = new Rectangle(tabBtnX, rulerY, tabBtnW, rulerH);

            using (SolidBrush btnBg = new SolidBrush(Color.FromArgb(248, 250, 252)))
            {
                g.FillRectangle(btnBg, RulerTabSelectorRect);
            }
            using (Pen borderPen = new Pen(Color.FromArgb(190, 198, 210)))
            {
                g.DrawRectangle(borderPen, RulerTabSelectorRect);
            }

            // Draw Active Tab Stop Symbol inside the Tab Selector Button
            DrawTabGlyph(g, tabBtnX + tabBtnW / 2, rulerY + rulerH / 2, ActiveTabStopSelector, Color.FromArgb(30, 41, 59), 1.8f);

            // Clip horizontal ruler body so it never overlaps the Tab button or Navigation Pane/Selection Pane
            int rClipX = navOffset + tabBtnW + 4;
            int rClipW = Math.Max(0, canvasW - rClipX - (ShowSelectionPane ? 260 : 0));
            GraphicsState rulerClipState = g.Save();
            g.SetClip(new Rectangle(rClipX, rulerY, rClipW, rulerH));

            // 2. Base Ruler Panel (Mặt thước ngang)
            Rectangle fullRulerRect = new Rectangle(pageX, rulerY, pageW, rulerH);
            int bodyW = pageW - marginX - rightMarginX;

            // 2.1. Left Margin Grey Zone
            using (SolidBrush greyBrush = new SolidBrush(Color.FromArgb(226, 230, 237)))
            {
                g.FillRectangle(greyBrush, pageX, rulerY, marginX, rulerH);
            }

            // 2.2. Middle Editable White Zone
            using (SolidBrush whiteBrush = new SolidBrush(Color.White))
            {
                g.FillRectangle(whiteBrush, pageX + marginX, rulerY, bodyW, rulerH);
            }

            // 2.3. Right Margin Grey Zone
            using (SolidBrush greyBrush = new SolidBrush(Color.FromArgb(226, 230, 237)))
            {
                g.FillRectangle(greyBrush, pageX + pageW - rightMarginX, rulerY, rightMarginX, rulerH);
            }

            // Border lines for Ruler
            using (Pen rBorderPen = new Pen(Color.FromArgb(195, 202, 214)))
            {
                g.DrawRectangle(rBorderPen, fullRulerRect);
                g.DrawLine(rBorderPen, pageX + marginX, rulerY, pageX + marginX, rulerY + rulerH);
                g.DrawLine(rBorderPen, pageX + pageW - rightMarginX, rulerY, pageX + pageW - rightMarginX, rulerY + rulerH);
            }

            // 3. Tick Marks & Numbers (Centimeters / Inches)
            using (Font numFont = new Font("Segoe UI", 7.0f, FontStyle.Regular))
            using (SolidBrush numBrush = new SolidBrush(Color.FromArgb(70, 80, 95)))
            using (Pen tickPen = new Pen(Color.FromArgb(135, 145, 160)))
            using (Pen minorTickPen = new Pen(Color.FromArgb(185, 192, 202)))
            {
                if (CurrentRulerUnit == RulerUnit.Centimeters)
                {
                    // 1 cm = pageW / 21.0f (since A4 width = 21.0 cm)
                    float pxPerCm = pageW / 21.0f;

                    // Positive numbers starting from 0 at left margin
                    int cmIndex = 1;
                    float curX = pageX + marginX + pxPerCm;
                    while (curX < pageX + pageW - 6)
                    {
                        // Minor ticks every 2mm
                        for (int sub = 1; sub <= 4; sub++)
                        {
                            float subX = curX - pxPerCm + sub * (pxPerCm / 5.0f);
                            if (subX >= pageX + marginX && subX < pageX + pageW)
                            {
                                int subH = (sub == 2 || sub == 3) ? 5 : 3;
                                g.DrawLine(minorTickPen, subX, rulerY + rulerH, subX, rulerY + rulerH - subH);
                            }
                        }

                        // Half-cm tick
                        float halfX = curX - pxPerCm * 0.5f;
                        if (halfX >= pageX + marginX && halfX < pageX + pageW)
                        {
                            g.DrawLine(tickPen, halfX, rulerY + rulerH, halfX, rulerY + rulerH - 6);
                        }

                        // Major cm tick
                        g.DrawLine(tickPen, curX, rulerY + rulerH, curX, rulerY + rulerH - 9);

                        // Number label
                        string numStr = cmIndex.ToString();
                        SizeF sz = g.MeasureString(numStr, numFont);
                        g.DrawString(numStr, numFont, numBrush, curX - sz.Width / 2f, rulerY + 3);

                        cmIndex++;
                        curX += pxPerCm;
                    }

                    // Negative ticks on left margin grey area
                    int negCm = 1;
                    float negX = pageX + marginX - pxPerCm;
                    while (negX > pageX + 6)
                    {
                        // Minor ticks
                        for (int sub = 1; sub <= 4; sub++)
                        {
                            float subX = negX + sub * (pxPerCm / 5.0f);
                            if (subX >= pageX && subX < pageX + marginX)
                            {
                                g.DrawLine(minorTickPen, subX, rulerY + rulerH, subX, rulerY + rulerH - 3);
                            }
                        }
                        g.DrawLine(tickPen, negX, rulerY + rulerH, negX, rulerY + rulerH - 8);
                        string numStr = negCm.ToString();
                        SizeF sz = g.MeasureString(numStr, numFont);
                        g.DrawString(numStr, numFont, numBrush, negX - sz.Width / 2f, rulerY + 3);

                        negCm++;
                        negX -= pxPerCm;
                    }
                }
                else
                {
                    // Inches Mode (A4 width = 8.27 inches)
                    float pxPerInch = pageW / 8.27f;
                    int inIndex = 1;
                    float curX = pageX + marginX + pxPerInch;
                    while (curX < pageX + pageW - 6)
                    {
                        // 1/4 inch ticks
                        for (int sub = 1; sub <= 3; sub++)
                        {
                            float subX = curX - pxPerInch + sub * (pxPerInch / 4.0f);
                            int subH = (sub == 2) ? 6 : 4;
                            g.DrawLine(minorTickPen, subX, rulerY + rulerH, subX, rulerY + rulerH - subH);
                        }
                        g.DrawLine(tickPen, curX, rulerY + rulerH, curX, rulerY + rulerH - 9);
                        string numStr = inIndex.ToString();
                        SizeF sz = g.MeasureString(numStr, numFont);
                        g.DrawString(numStr, numFont, numBrush, curX - sz.Width / 2f, rulerY + 3);
                        inIndex++;
                        curX += pxPerInch;
                    }
                }
            }

            // 4. Tab Stops Glyphs on the Ruler
            TabStopHitRects.Clear();
            var tabStops = GetTabStops(curPStart);
            if (tabStops != null)
            {
                for (int i = 0; i < tabStops.Count; i++)
                {
                    var ts = tabStops[i];
                    int tsX = pageX + marginX + (int)(ts.PositionPt * ZoomLevel);
                    Rectangle tsRect = new Rectangle(tsX - 5, rulerY + rulerH - 12, 10, 12);
                    TabStopHitRects.Add(tsRect);
                    DrawTabGlyph(g, tsX, rulerY + rulerH - 6, ts.Type, Color.FromArgb(15, 23, 42), 1.8f);
                }
            }

            // 5. The 4 Geometric Indentation Markers (4 Mấu Kéo Đoạn Văn)
            float pFirstLine = GetFirstLineIndent(curPStart) * ZoomLevel;
            float pHanging = GetHangingIndent(curPStart) * ZoomLevel;
            float pLeft = GetLeftIndent(curPStart) * ZoomLevel;
            float pRight = GetRightIndent(curPStart) * ZoomLevel;

            int leftBaseX = pageX + marginX + (int)pLeft;
            int flX = leftBaseX + (int)pFirstLine;
            int hgX = leftBaseX + (int)pHanging;
            int rX = pageX + pageW - rightMarginX - (int)pRight;

            // (1) ▼ First Line Indent (Mấu tam giác chúc xuống ở đỉnh trên bên trái)
            FirstLineIndentHitRect = new Rectangle(flX - 6, rulerY, 12, 10);
            PointF[] flTri = new PointF[]
            {
                new PointF(flX - 5f, rulerY + 1),
                new PointF(flX + 5f, rulerY + 1),
                new PointF(flX, rulerY + 9)
            };
            using (SolidBrush mBrush = new SolidBrush(Color.FromArgb(90, 100, 115)))
            using (Pen mPen = new Pen(Color.FromArgb(35, 45, 60), 1.2f))
            {
                g.FillPolygon(mBrush, flTri);
                g.DrawPolygon(mPen, flTri);
            }

            // (2) ▲ Hanging Indent (Mấu tam giác chúc lên ở giữa bên trái)
            HangingIndentHitRect = new Rectangle(hgX - 6, rulerY + 9, 12, 9);
            PointF[] hgTri = new PointF[]
            {
                new PointF(hgX, rulerY + 9),
                new PointF(hgX - 5f, rulerY + 17),
                new PointF(hgX + 5f, rulerY + 17)
            };
            using (SolidBrush mBrush = new SolidBrush(Color.FromArgb(90, 100, 115)))
            using (Pen mPen = new Pen(Color.FromArgb(35, 45, 60), 1.2f))
            {
                g.FillPolygon(mBrush, hgTri);
                g.DrawPolygon(mPen, hgTri);
            }

            // (3) ■ Left Indent (Khối hình chữ nhật ở đáy bên trái)
            LeftIndentHitRect = new Rectangle(hgX - 5, rulerY + 17, 10, 6);
            using (SolidBrush mBrush = new SolidBrush(Color.FromArgb(90, 100, 115)))
            using (Pen mPen = new Pen(Color.FromArgb(35, 45, 60), 1.2f))
            {
                g.FillRectangle(mBrush, LeftIndentHitRect);
                g.DrawRectangle(mPen, LeftIndentHitRect);
            }

            // (4) ▲ Right Indent (Mấu tam giác chúc lên bên phải)
            RightIndentHitRect = new Rectangle(rX - 6, rulerY + 8, 12, 15);
            PointF[] rTri = new PointF[]
            {
                new PointF(rX, rulerY + 8),
                new PointF(rX - 5f, rulerY + 22),
                new PointF(rX + 5f, rulerY + 22)
            };
            using (SolidBrush mBrush = new SolidBrush(Color.FromArgb(90, 100, 115)))
            using (Pen mPen = new Pen(Color.FromArgb(35, 45, 60), 1.2f))
            {
                g.FillPolygon(mBrush, rTri);
                g.DrawPolygon(mPen, rTri);
            }

            // 6. Vertical Alignment Guide Line while Dragging
            if (RulerGuideLineX >= 0)
            {
                using (Pen guidePen = new Pen(Color.FromArgb(180, 0, 120, 215), 1.0f) { DashStyle = DashStyle.Dash })
                {
                    g.DrawLine(guidePen, RulerGuideLineX, rulerY + rulerH, RulerGuideLineX, canvasH - 30);
                }
            }
            g.Restore(rulerClipState);
        }

        private void DrawTabGlyph(D2DGraphics g, float cx, float cy, TabStopType type, Color col, float penWidth)
        {
            using (Pen p = new Pen(col, penWidth))
            using (SolidBrush b = new SolidBrush(col))
            {
                switch (type)
                {
                    case TabStopType.Left: // L shape: vertical bar at cx, bottom foot extends right to cx + 5
                        g.DrawLine(p, cx, cy - 5, cx, cy + 3);
                        g.DrawLine(p, cx, cy + 3, cx + 5, cy + 3);
                        break;
                    case TabStopType.Center: // Inverted T (⊥): horizontal bar cx - 4 to cx + 4, vertical stem at cx
                        g.DrawLine(p, cx - 4, cy + 3, cx + 4, cy + 3);
                        g.DrawLine(p, cx, cy + 3, cx, cy - 5);
                        break;
                    case TabStopType.Right: // Reverse L (⅃): vertical bar at cx, bottom foot extends left to cx - 5
                        g.DrawLine(p, cx, cy - 5, cx, cy + 3);
                        g.DrawLine(p, cx, cy + 3, cx - 5, cy + 3);
                        break;
                    case TabStopType.Decimal: // Inverted T with dot (⊥·)
                        g.DrawLine(p, cx - 4, cy + 3, cx + 3, cy + 3);
                        g.DrawLine(p, cx, cy + 3, cx, cy - 5);
                        g.FillEllipse(b, cx + 4.5f, cy + 1.5f, 2.5f, 2.5f);
                        break;
                    case TabStopType.Bar: // Vertical bar (│)
                        g.DrawLine(p, cx, cy - 5, cx, cy + 5);
                        break;
                }
            }
        }

        public void DrawVerticalRuler(D2DGraphics g, int pageX, int pageW, int pageH, int marginY, int bottomMarginY, int canvasW, int canvasH, RibbonBar ribbon)
        {
            int navOffset = ShowNavigationPane ? 280 : 0;
            int vRulerW = 22;
            int vRulerX = navOffset + 2;
            int topY = (ribbon != null && ribbon.ShowRuler ? 180 : 156);
            int bottomY = canvasH - 26;
            int vRulerH = bottomY - topY;
            if (vRulerH <= 20) return;

            VerticalRulerBounds = new Rectangle(vRulerX, topY, vRulerW, vRulerH);

            var oldClip = g.Clip;
            g.SetClip(new Rectangle(vRulerX, topY, vRulerW + 1, vRulerH));

            // Neutral ruler background behind scrolled pages
            using (SolidBrush bgBrush = new SolidBrush(Color.FromArgb(240, 242, 245)))
            {
                g.FillRectangle(bgBrush, vRulerX, topY, vRulerW, vRulerH);
            }

            int startPageY = (ribbon != null && ribbon.ShowRuler ? 190 : 165) - ScrollY;

            float paperHeightCm = (ribbon != null && ribbon.PaperHeightInches > 0) ? (ribbon.PaperHeightInches * 2.54f) : 29.7f;
            float paperHeightInches = (ribbon != null && ribbon.PaperHeightInches > 0) ? ribbon.PaperHeightInches : 11.69f;
            if (ribbon != null && ribbon.IsLandscape)
            {
                paperHeightCm = 21.0f;
                paperHeightInches = 8.27f;
            }

            float pxPerCm = pageH / paperHeightCm;
            float pxPerInch = pageH / paperHeightInches;

            using (SolidBrush greyBrush = new SolidBrush(Color.FromArgb(220, 224, 230)))
            using (SolidBrush whiteBrush = new SolidBrush(Color.White))
            using (Pen sepPen = new Pen(Color.FromArgb(180, 190, 205), 1.0f))
            using (Font numFont = new Font("Segoe UI", 6.8f, FontStyle.Regular))
            using (SolidBrush numBrush = new SolidBrush(Color.FromArgb(70, 80, 95)))
            using (Pen tickPen = new Pen(Color.FromArgb(135, 145, 160)))
            using (Pen minorTickPen = new Pen(Color.FromArgb(185, 192, 202)))
            {
                int pageCount = Math.Max(1, CalculatedPageCount);
                for (int pg = 0; pg < pageCount; pg++)
                {
                    int pTop = startPageY + pg * (pageH + 30);
                    int pBottom = pTop + pageH;
                    int bTop = pTop + marginY;
                    int bBottom = pBottom - bottomMarginY;

                    if (pBottom < topY || pTop > bottomY) continue;

                    // 1. Top margin grey zone
                    g.FillRectangle(greyBrush, vRulerX, pTop, vRulerW, marginY);

                    // 2. Body white zone
                    g.FillRectangle(whiteBrush, vRulerX, bTop, vRulerW, bBottom - bTop);

                    // 3. Bottom margin grey zone
                    g.FillRectangle(greyBrush, vRulerX, bBottom, vRulerW, bottomMarginY);

                    // 4. Margin divider lines
                    g.DrawLine(sepPen, vRulerX, bTop, vRulerX + vRulerW, bTop);
                    g.DrawLine(sepPen, vRulerX, bBottom, vRulerX + vRulerW, bBottom);

                    // 5. Ticks & Numbers
                    if (CurrentRulerUnit == RulerUnit.Centimeters)
                    {
                        // Positive numbers descending from bTop into body
                        int cmIndex = 1;
                        float curY = bTop + pxPerCm;
                        while (curY < bBottom + bottomMarginY - 4)
                        {
                            for (int sub = 1; sub <= 4; sub++)
                            {
                                float subY = curY - pxPerCm + sub * (pxPerCm / 5.0f);
                                if (subY >= pTop && subY < pBottom)
                                {
                                    int subW = (sub == 2 || sub == 3) ? 4 : 2;
                                    g.DrawLine(minorTickPen, vRulerX + vRulerW - 1, subY, vRulerX + vRulerW - 1 - subW, subY);
                                }
                            }

                            float halfY = curY - pxPerCm * 0.5f;
                            if (halfY >= pTop && halfY < pBottom)
                            {
                                g.DrawLine(tickPen, vRulerX + vRulerW - 1, halfY, vRulerX + vRulerW - 1 - 5, halfY);
                            }

                            if (curY >= pTop && curY < pBottom)
                            {
                                g.DrawLine(tickPen, vRulerX + vRulerW - 1, curY, vRulerX + vRulerW - 1 - 7, curY);

                                string numStr = cmIndex.ToString();
                                SizeF sz = g.MeasureString(numStr, numFont);
                                g.DrawString(numStr, numFont, numBrush, vRulerX + (vRulerW - sz.Width) / 2f - 1f, curY - sz.Height / 2f);
                            }

                            cmIndex++;
                            curY += pxPerCm;
                        }

                        // Negative numbers ascending into top margin
                        int negCm = 1;
                        float negY = bTop - pxPerCm;
                        while (negY > pTop + 4)
                        {
                            for (int sub = 1; sub <= 4; sub++)
                            {
                                float subY = negY + sub * (pxPerCm / 5.0f);
                                if (subY >= pTop && subY < bTop)
                                {
                                    g.DrawLine(minorTickPen, vRulerX + vRulerW - 1, subY, vRulerX + vRulerW - 1 - 2, subY);
                                }
                            }
                            g.DrawLine(tickPen, vRulerX + vRulerW - 1, negY, vRulerX + vRulerW - 1 - 6, negY);
                            string numStr = negCm.ToString();
                            SizeF sz = g.MeasureString(numStr, numFont);
                            g.DrawString(numStr, numFont, numBrush, vRulerX + (vRulerW - sz.Width) / 2f - 1f, negY - sz.Height / 2f);

                            negCm++;
                            negY -= pxPerCm;
                        }
                    }
                    else
                    {
                        // Inches Mode
                        int inIndex = 1;
                        float curY = bTop + pxPerInch;
                        while (curY < bBottom + bottomMarginY - 4)
                        {
                            for (int sub = 1; sub <= 3; sub++)
                            {
                                float subY = curY - pxPerInch + sub * (pxPerInch / 4.0f);
                                if (subY >= pTop && subY < pBottom)
                                {
                                    int subW = (sub == 2) ? 5 : 3;
                                    g.DrawLine(minorTickPen, vRulerX + vRulerW - 1, subY, vRulerX + vRulerW - 1 - subW, subY);
                                }
                            }

                            float halfY = curY - pxPerInch * 0.5f;
                            if (halfY >= pTop && halfY < pBottom)
                            {
                                g.DrawLine(tickPen, vRulerX + vRulerW - 1, halfY, vRulerX + vRulerW - 1 - 5, halfY);
                            }

                            if (curY >= pTop && curY < pBottom)
                            {
                                g.DrawLine(tickPen, vRulerX + vRulerW - 1, curY, vRulerX + vRulerW - 1 - 7, curY);
                                string numStr = inIndex.ToString();
                                SizeF sz = g.MeasureString(numStr, numFont);
                                g.DrawString(numStr, numFont, numBrush, vRulerX + (vRulerW - sz.Width) / 2f - 1f, curY - sz.Height / 2f);
                            }

                            inIndex++;
                            curY += pxPerInch;
                        }
                    }
                }
            }

            g.Clip = oldClip;

            // Outer border around the vertical ruler
            using (Pen borderPen = new Pen(Color.FromArgb(190, 198, 210)))
            {
                g.DrawLine(borderPen, vRulerX, topY, vRulerX, bottomY);
                g.DrawLine(borderPen, vRulerX + vRulerW, topY, vRulerX + vRulerW, bottomY);
                g.DrawLine(borderPen, vRulerX, bottomY, vRulerX + vRulerW, bottomY);
            }

            // Horizontal Alignment Guide Line while Dragging Vertical Ruler Margin
            if (RulerGuideLineY >= 0)
            {
                using (Pen guidePen = new Pen(Color.FromArgb(180, 0, 120, 215), 1.0f) { DashStyle = DashStyle.Dash })
                {
                    g.DrawLine(guidePen, vRulerX + vRulerW, RulerGuideLineY, canvasW - 20, RulerGuideLineY);
                }
            }
        }

        public void Paste()
        {
            try
            {
                if (Clipboard.ContainsImage())
                {
                    Image clipImg = Clipboard.GetImage();
                    if (clipImg != null)
                    {
                        InsertImage(clipImg);
                        return;
                    }
                }

                if (Clipboard.ContainsFileDropList())
                {
                    var files = Clipboard.GetFileDropList();
                    if (files != null && files.Count > 0)
                    {
                        bool pastedAny = false;
                        for (int i = 0; i < files.Count; i++)
                        {
                            string f = files[i];
                            if (!string.IsNullOrEmpty(f) && System.IO.File.Exists(f))
                            {
                                string ext = System.IO.Path.GetExtension(f).ToLowerInvariant();
                                if (ext == ".png" || ext == ".jpg" || ext == ".jpeg" || ext == ".bmp" || 
                                    ext == ".gif" || ext == ".webp" || ext == ".ico" || ext == ".tiff" || ext == ".tif")
                                {
                                    InsertImage(f);
                                    pastedAny = true;
                                }
                            }
                        }
                        if (pastedAny) return;
                    }
                }

                if (Clipboard.ContainsText())
                {
                    string clip = Clipboard.GetText();
                    InsertText(clip);
                }
            }
            catch { }
        }

        private void DeleteSelection()
        {
            if (SelectionStart != SelectionEnd)
            {
                int min = Math.Min(SelectionStart, SelectionEnd);
                int len = Math.Abs(SelectionEnd - SelectionStart);
                if (TrackChanges)
                {
                    string delText = PieceTable != null ? PieceTable.GetSubstring(min, len) : "";
                    var rev = RecordChange(RevisionType.Deletion, min, len, delText);
                    ApplyFormatToRange(min, len, null, 0, null, null, null, true, rev.Color, null);
                    CursorPosition = min + len;
                    SelectionStart = CursorPosition;
                    SelectionEnd = CursorPosition;
                }
                else
                {
                    PieceTable.Remove(min, len);
                    AdjustFormattedRunsOnDelete(min, len);
                    ShiftRevisionsOnDelete(min, len);
                    CursorPosition = min;
                    SelectionStart = min;
                    SelectionEnd = min;
                }
            }
        }

        public void Draw(Graphics g, int width, int height, RibbonBar ribbon)
        {
            using (D2DGraphics d2d = new D2DGraphics(g, width, height))
            {
                Draw(d2d, width, height, ribbon);
            }
        }

        public void Draw(D2DGraphics g, int width, int height, RibbonBar ribbon)
        {
            g.SmoothingMode = SmoothingMode.HighQuality;
            g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;

            int canvasW = width;
            LastViewWidth = width;
            LastViewHeight = height;

            // 1. Workspace Background
            Color wsBg = Color.FromArgb(229, 229, 229);
            if (ViewMode == 0) wsBg = Color.FromArgb(37, 37, 37); // MS Word Dark Reading Mode Background (#252525)
            else if (ViewMode == 2) wsBg = Color.FromArgb(240, 240, 240); // Web mode clean bg

            int wsH = Math.Max(0, height - 155 - 26);
            using (SolidBrush bgBrush = new SolidBrush(wsBg))
            {
                g.FillRectangle(bgBrush, 0, 155, canvasW, wsH);
            }

            int docContentTop = (ribbon != null && ribbon.ShowRuler) ? 181 : 155;
            int maxScrollX = GetMaxScrollX(width);
            int docContentH = Math.Max(0, height - docContentTop - 26 - (maxScrollX > 0 ? 12 : 0));
            GraphicsState docClipState = g.Save();
            g.SetClip(new Rectangle(0, docContentTop, width, docContentH));

            // 2. Compute Paper Bounds based on ViewMode (Read, Print, Web)
            int pageX, pageW, pageH, marginX, rightMarginX, marginY;
            GetPageLayoutMetrics(canvasW, ribbon, out pageX, out pageW, out pageH, out marginX, out rightMarginX, out marginY);
            float bottomMarginInches = ribbon != null ? ribbon.GetEffectiveBottomMarginInches() : 1.0f;
            int bottomMarginY = (int)Math.Round(bottomMarginInches * 96 * ZoomLevel);

            if (CurrentHeaderPreset != HeaderFooterPreset.None || IsEditingHeaderFooter || !string.IsNullOrEmpty(HeaderText))
            {
                if (CurrentHeaderPreset != HeaderFooterPreset.Banded || HeaderBannerYOffset <= 10)
                {
                    marginY = Math.Max(marginY, (int)(44 * ZoomLevel));
                }
            }
            int maxTextW = pageW - marginX - rightMarginX;
            int startPageY;
            if (ViewMode == 0)
            {
                ScrollX = 0f;
                SmoothScrollX = 0f;
                TargetScrollX = 0f;
                int effH = height > 0 ? height : (LastViewHeight > 0 ? LastViewHeight : 800);
                int availableH = effH - 155 - 26;
                int padY = Math.Max(16, (availableH - pageH) / 2);
                startPageY = 155 + padY - ScrollY;
            }
            else
            {
                startPageY = (ribbon != null && ribbon.ShowRuler ? 190 : 165) - ScrollY;
            }
            int textX = pageX + marginX;
            CurrentRenderTextX = textX;
            
            int currentTextVersion = PieceTable.Version;
            int runsHash = FormattedRuns.Count;
            if (FormattedRuns.Count > 0) runsHash ^= FormattedRuns[0].FontSize.GetHashCode() ^ FormattedRuns[FormattedRuns.Count - 1].Length;
            
            bool layoutDirty = (currentTextVersion != _lastLayoutTextVersion || runsHash != _lastLayoutRunsHash || ZoomLevel != _lastLayoutZoom || maxTextW != _lastLayoutMaxW || textX != _lastLayoutTextX || pageX != _lastLayoutPageX || ViewMode != _lastLayoutViewMode || IsDraggingShape || DragShapeHandleIndex >= 0 || IsDraggingChart || DragChartHandleIndex >= 0 || IsDraggingMove);
            if (layoutDirty)
            {
                _paraLayoutCache.Clear();
                DocShapeObject.ClearTagParseCache();
                ClearCellLineCache();
                _wordMeasureCache.Clear();
                if (ZoomLevel != _lastLayoutZoom || maxTextW != _lastLayoutMaxW || ViewMode != _lastLayoutViewMode)
                {
                    // Zoom or page width changed: force table column/row recalculation at new scale
                    TableColWidths.Clear();
                    TableRowHeights.Clear();
                }
                _lastLayoutTextVersion = currentTextVersion;
                _lastLayoutRunsHash = runsHash;
                _lastLayoutZoom = ZoomLevel;
                _lastLayoutMaxW = maxTextW;
                _lastLayoutTextX = textX;
                _lastLayoutPageX = pageX;
                _lastLayoutViewMode = ViewMode;
            }

            float currentY = startPageY + marginY;

            if (_cachedParagraphs == null || currentTextVersion != _cachedParagraphsVersion)
            {
                string fullText = PieceTable.GetText();
                _cachedParagraphs = fullText.Split('\n');
                _cachedParagraphsVersion = currentTextVersion;
            }
            string[] paragraphs = _cachedParagraphs;
            int paraStartIndex = 0;

            int cursorX = textX;
            int cursorY = (int)Math.Round(currentY);
            int cursorH = (int)(20 * ZoomLevel);
            int currentPage = 0;

            int selMin = Math.Min(SelectionStart, SelectionEnd);
            int selMax = Math.Max(SelectionStart, SelectionEnd);
            bool hasSelection = (selMin != selMax);

            MoveHandleRects.Clear();
            ResizeHandleRects.Clear();
            TableBoundsList.Clear();
            DocParagraphGaps.Clear();
            InsertButtonHits.Clear();
            RenderedLines.Clear();
            TableCharRanges.Clear();
            TableCellHits.Clear();
            TableWrapBtnHits.Clear();
            int currentTableCount = 0;

            // Pre-populate TableFloatingBounds for Wrap Around tables so earlier paragraphs wrap around them
            foreach (var kvp in TableWrapModes)
            {
                if (kvp.Value == 1)
                {
                    int t = kvp.Key;
                    if (TablePageX.ContainsKey(t) && TablePageY.ContainsKey(t))
                    {
                        int fTx = pageX + (int)(TablePageX[t] * ZoomLevel);
                        int fTy = startPageY + (int)(TablePageY[t] * ZoomLevel);
                        int fTw = 0;
                        if (TableColWidths.ContainsKey(t))
                        {
                            foreach (var cw in TableColWidths[t]) fTw += cw;
                        }
                        if (fTw <= 0) fTw = maxTextW;
                        int fTh = 0;
                        if (TableRowHeights.ContainsKey(t))
                        {
                            foreach (var rh in TableRowHeights[t]) fTh += rh;
                        }
                        if (fTh <= 0) fTh = (int)(60 * ZoomLevel);
                        TableFloatingBounds[t] = new Rectangle(fTx, fTy, fTw, fTh);
                    }
                }
            }

            // Single-Pass High Performance Engine: Calculate necessary pages including floating shapes/charts!
            int maxNeededPages = 1;
            foreach (var sh in DocumentShapes)
            {
                if (sh.Visible && sh.PageNumber + 1 > maxNeededPages) maxNeededPages = sh.PageNumber + 1;
            }
            foreach (var ch in DocumentCharts)
            {
                if (ch.Visible && ch.PageNumber + 1 > maxNeededPages) maxNeededPages = ch.PageNumber + 1;
            }
            int pageCount = Math.Max(maxNeededPages, CalculatedPageCount);
            TotalPageCount = pageCount;
            if (ViewMode == 0)
            {
                ReadModePageIndex = Math.Max(0, Math.Min(pageCount - 1, ReadModePageIndex));
                CurrentActivePage = ReadModePageIndex + 1;
            }
            else
            {
                CurrentActivePage = Math.Max(1, Math.Min(pageCount, (int)((ScrollY + (height / 2)) / (pageH + 30)) + 1));
            }
            CalculatedPageCount = pageCount;
            if (ViewMode == 0)
            {
                // MS Word Read Mode (📖): Render Centered Book Page
                DrawPageCanvas(g, pageX, startPageY, pageW, pageH, ribbon, ReadModePageIndex + 1, pageCount);

                // Draw Semi-Transparent Page Navigation Arrow Buttons (◀ and ▶)
                int arrowY = 155 + (height - 183) / 2;
                
                // Left Arrow (◀)
                Rectangle leftBtn = new Rectangle(20, arrowY - 25, 45, 45);
                bool canPrev = (ReadModePageIndex > 0);
                using (SolidBrush circleBg = new SolidBrush(canPrev ? Color.FromArgb(70, 255, 255, 255) : Color.FromArgb(20, 255, 255, 255)))
                {
                    g.FillEllipse(circleBg, leftBtn);
                }
                using (Pen circlePen = new Pen(canPrev ? Color.FromArgb(180, 255, 255, 255) : Color.FromArgb(40, 255, 255, 255), 1.2f))
                {
                    g.DrawEllipse(circlePen, leftBtn);
                }
                using (Font arrowFont = new Font("Segoe UI Symbol", 13.0f, FontStyle.Bold))
                using (SolidBrush arrowBrush = new SolidBrush(canPrev ? Color.White : Color.FromArgb(70, 255, 255, 255)))
                {
                    g.DrawString("◀", arrowFont, arrowBrush, leftBtn.X + 11, leftBtn.Y + 10);
                }

                // Right Arrow (▶)
                Rectangle rightBtn = new Rectangle(canvasW - 65, arrowY - 25, 45, 45);
                bool canNext = (ReadModePageIndex < pageCount - 1);
                using (SolidBrush circleBg = new SolidBrush(canNext ? Color.FromArgb(70, 255, 255, 255) : Color.FromArgb(20, 255, 255, 255)))
                {
                    g.FillEllipse(circleBg, rightBtn);
                }
                using (Pen circlePen = new Pen(canNext ? Color.FromArgb(180, 255, 255, 255) : Color.FromArgb(40, 255, 255, 255), 1.2f))
                {
                    g.DrawEllipse(circlePen, rightBtn);
                }
                using (Font arrowFont = new Font("Segoe UI Symbol", 13.0f, FontStyle.Bold))
                using (SolidBrush arrowBrush = new SolidBrush(canNext ? Color.White : Color.FromArgb(70, 255, 255, 255)))
                {
                    g.DrawString("▶", arrowFont, arrowBrush, rightBtn.X + 13, rightBtn.Y + 10);
                }
            }
            else
            {
                int startPg = Math.Max(0, (150 - startPageY - pageH) / (pageH + 30));
                int endPg = Math.Min(pageCount - 1, (height - startPageY) / (pageH + 30) + 1);
                for (int pg = startPg; pg <= endPg; pg++)
                {
                    int pgY = startPageY + pg * (pageH + 30);
                    DrawPageCanvas(g, pageX, pgY, pageW, pageH, ribbon, pg + 1, pageCount);
                }
            }

            GraphicsState readModeState = null;
            if (ViewMode == 0)
            {
                readModeState = g.Save();
                g.SetClip(new Rectangle(pageX, startPageY, pageW, pageH));
                g.TranslateTransform(0, -ReadModePageIndex * (pageH + 30));
            }

            // Pre-pass: Scan all Shape and Chart tags from paragraphs to register/update DocShapeObject & DocChartObject before text layout!
            if (layoutDirty || _lastShapesScannedVersion != currentTextVersion)
            {
                for (int pScan = 0; pScan < paragraphs.Length; pScan++)
                {
                    string pStr = paragraphs[pScan];
                    if (string.IsNullOrEmpty(pStr) || pStr.IndexOf("![") < 0) continue;

                    int sScanIdx = 0;
                    while (sScanIdx < pStr.Length)
                    {
                        int shIdx = pStr.IndexOf("![SHAPE:", sScanIdx);
                        int imIdx = pStr.IndexOf("![IMAGE:", sScanIdx);
                        int mdIdx = pStr.IndexOf("![IMAGE](", sScanIdx);
                        int tagStart = -1;
                        if (shIdx >= 0) tagStart = shIdx;
                        if (imIdx >= 0 && (tagStart < 0 || imIdx < tagStart)) tagStart = imIdx;
                        if (mdIdx >= 0 && (tagStart < 0 || mdIdx < tagStart)) tagStart = mdIdx;
                        if (tagStart < 0) break;

                        int tagEnd = -1;
                        int nextTag = pStr.IndexOf("![", tagStart + 2);
                        int lineEnd = pStr.IndexOf('\n', tagStart);
                        int limit = pStr.Length;
                        if (nextTag >= 0 && nextTag < limit) limit = nextTag;
                        if (lineEnd >= 0 && lineEnd < limit) limit = lineEnd;
                        tagEnd = pStr.LastIndexOf(']', limit - 1, limit - tagStart);
                        if (tagEnd < 0) tagEnd = pStr.LastIndexOf(')', limit - 1, limit - tagStart);
                        if (tagEnd < 0) tagEnd = pStr.IndexOf(']', tagStart);
                        if (tagEnd < 0) tagEnd = pStr.IndexOf(')', tagStart);
                        if (tagEnd < 0) break;

                        string tagStr = pStr.Substring(tagStart, tagEnd - tagStart + 1);
                        string sId = "", sType = "Rectangle", sPath = "";
                        int tX = -1, tY = -1, tW = -1, tH = -1, tWrap = -1, tPage = -1, tStyle = -1, tYRel = 0;
                        DocShapeObject.ParseShapeTag(tagStr, out sId, out sType, out sPath, out tX, out tY, out tW, out tH, out tWrap, out tPage, out tStyle, out tYRel);
                        if (string.IsNullOrEmpty(sId)) sId = "Shape_" + pScan + "_" + tagStart;
                        DocShapeObject sObj = GetOrCreateDocShape(sId, sType);
                        if (!IsDraggingShape && (sObj != ActiveShape || DragShapeHandleIndex < 0))
                        {
                            if (tX >= 0) sObj.PageX = tX;
                            if (tPage >= 0)
                            {
                                if (tY >= 0) sObj.PageY = tY;
                                sObj.PageNumber = tPage;
                            }
                            if (tW > 0) sObj.BaseWidth = tW;
                            if (tH > 0) sObj.BaseHeight = tH;
                            if (tWrap >= 0) sObj.WrapMode = tWrap;
                            if (!string.IsNullOrEmpty(sPath))
                            {
                                sObj.ImagePath = sPath;
                                if (sObj.CachedImage == null && System.IO.File.Exists(sPath))
                                {
                                    int reqW = tW > 0 ? tW : sObj.BaseWidth;
                                    int reqH = tH > 0 ? tH : sObj.BaseHeight;
                                    sObj.CachedImage = DocShapeObject.LoadOptimizedImage(sPath, reqW, reqH);
                                }
                            }
                        }
                        sScanIdx = tagEnd + 1;
                    }
                }
                _lastShapesScannedVersion = currentTextVersion;
            }

            // Pre-calculate LastBounds for all Floating charts (WrapMode != 0) before text layout!
            foreach (var ch in DocumentCharts)
            {
                if (ch.WrapMode != 0)
                {
                    int cW = Math.Max((int)(200 * ZoomLevel), (int)((ch.BaseWidth + ch.WidthDelta) * ZoomLevel));
                    int cH = Math.Max((int)(120 * ZoomLevel), (int)((ch.BaseHeight + ch.HeightDelta) * ZoomLevel));
                    int pTopY = startPageY + ch.PageNumber * (pageH + 30) + marginY;
                    int cX = pageX + (int)(ch.PageX * ZoomLevel);
                    int cY = pTopY + (int)(ch.PageY * ZoomLevel);
                    ch.LastBounds = new Rectangle(cX, cY, cW, cH);
                }
                else
                {
                    ch.LastBounds = Rectangle.Empty;
                }
            }

            // Pre-calculate LastBounds for all Floating shapes (WrapMode != 0) before text layout!
            foreach (var sh in DocumentShapes)
            {
                if (sh.WrapMode != 0)
                {
                    int sW = Math.Max((int)(20 * ZoomLevel), (int)((sh.BaseWidth + sh.WidthDelta) * ZoomLevel));
                    int sH = Math.Max((int)(15 * ZoomLevel), (int)((sh.BaseHeight + sh.HeightDelta) * ZoomLevel));
                    int pTopY = startPageY + sh.PageNumber * (pageH + 30) + marginY;
                    int sX = pageX + (int)(sh.PageX * ZoomLevel);
                    int sY = pTopY + (int)(sh.PageY * ZoomLevel);
                    sh.LastBounds = new Rectangle(sX, sY, sW, sH);
                }
                else
                {
                    sh.LastBounds = Rectangle.Empty;
                }
            }

            // PASS 1: Render Behind-Text Shapes & Charts (WrapMode == 5) beneath text
            foreach (var sh in DocumentShapes)
            {
                if (sh.WrapMode == 5 && !sh.LastBounds.IsEmpty)
                {
                    if (sh.LastBounds.Bottom >= 150 && sh.LastBounds.Top <= height)
                        ShapeRenderer.DrawShape(g, sh, sh.LastBounds, ribbon, ZoomLevel);
                }
            }
            foreach (var ch in DocumentCharts)
            {
                if (ch.WrapMode == 5 && !ch.LastBounds.IsEmpty)
                {
                    if (ch.LastBounds.Bottom >= 150 && ch.LastBounds.Top <= height)
                        DrawDocumentChart(g, ch, ch.LastBounds.X, ch.LastBounds.Y, ch.LastBounds.Width, ch.LastBounds.Height, ribbon);
                }
            }

            // PASS 1b: Render Highlighters (Tab Vẽ - Bút dạ quang) UNDERNEATH Text & Tables
            if (DocumentInkStrokes != null && DocumentInkStrokes.Count > 0)
            {
                SmoothingMode prevSmoothInk = g.SmoothingMode;
                g.SmoothingMode = SmoothingMode.AntiAlias;
                for (int si = 0; si < DocumentInkStrokes.Count; si++)
                {
                    var stroke = DocumentInkStrokes[si];
                    if (stroke != null && stroke.IsHighlighter && stroke.Points != null && stroke.Points.Count > 0)
                    {
                        int sPageY = startPageY + stroke.PageIndex * (pageH + 30);
                        if (sPageY + pageH >= 150 && sPageY <= height)
                        {
                            DrawInkStroke(g, stroke, pageX, sPageY, ZoomLevel);
                        }
                    }
                }
                g.SmoothingMode = prevSmoothInk;
            }
            if (_currentInkStroke != null && _currentInkStroke.IsHighlighter && _currentInkStroke.Points != null && _currentInkStroke.Points.Count > 0)
            {
                SmoothingMode prevSmoothInk = g.SmoothingMode;
                g.SmoothingMode = SmoothingMode.AntiAlias;
                int sPageY = startPageY + _currentInkStroke.PageIndex * (pageH + 30);
                DrawInkStroke(g, _currentInkStroke, pageX, sPageY, ZoomLevel);
                g.SmoothingMode = prevSmoothInk;
            }

            DocParagraphGaps.Add(new ParagraphGap { ScreenY = (int)Math.Round(currentY), CharIndex = 0, VirtualEntersNeeded = 0 });

            int docLineNumber = 0;
            int lastLinePage = -1;
            int pageLineNumber = 0;

            using (SolidBrush selBrush = new SolidBrush(Color.FromArgb(180, 213, 254)))
            {
                for (int p = 0; p < paragraphs.Length; p++)
                {
                    string para = paragraphs[p];

                    // High-Performance Viewport Virtualization: Skip off-screen cached paragraphs at the very beginning of the loop!
                    ParaLayoutCache pCache = null;
                    float yOffset = currentY - startPageY;
                    if (_paraLayoutCache.TryGetValue(paraStartIndex, out pCache))
                    {
                        if (pCache.Text == para && pCache.Zoom == ZoomLevel && pCache.MaxW == maxTextW && Math.Abs(pCache.CurrentYOffset - yOffset) < 0.05f)
                        {
                            float readModeOffset = (ViewMode == 0) ? (ReadModePageIndex * (pageH + 30)) : 0f;
                            float paraScreenTop = startPageY + pCache.CurrentYOffset - readModeOffset;
                            float paraScreenBottom = startPageY + pCache.FinalYOffset - readModeOffset;
                            bool isOffscreen = (ViewMode == 0)
                                ? (paraScreenBottom < startPageY - 20 || paraScreenTop > startPageY + pageH + 20)
                                : (paraScreenBottom < -100 || paraScreenTop > height + 100);
                            bool containsCursor = (CursorPosition >= paraStartIndex && CursorPosition <= paraStartIndex + para.Length);
                            bool containsSelection = hasSelection && (selMax >= paraStartIndex && selMin <= paraStartIndex + para.Length);

                            if (isOffscreen && !containsCursor && !containsSelection)
                            {
                                currentY = startPageY + pCache.FinalYOffset;
                                currentPage = pCache.FinalPage;
                                paraStartIndex += para.Length + 1;
                                continue;
                            }
                        }
                    }

                    // 1. All Break Handlers (Page & Section Breaks)
                    bool isPotentialBreak = (para.Length > 0 && (para[0] == '[' || para[0] == ' ' || para[0] == '\t'));
                    string pTrim = isPotentialBreak ? para.Trim() : "";
                    if (isPotentialBreak && (pTrim == "[--- PAGE BREAK ---]" || para.Contains("TRANG TRẮNG MỚI")))
                    {
                        int gapMidY = startPageY + currentPage * (pageH + 30) + pageH + 15;
                        if (ShowFormattingMarks && gapMidY >= 140 && gapMidY <= height + 20)
                        {
                            using (Font pFont = new Font("Segoe UI", 8.0f * ZoomLevel, FontStyle.Italic))
                            {
                                SizeF lbSz = g.MeasureString("····························································································· Ngắt trang (Page Break) ·····························································································", pFont);
                                int lbX = pageX + (pageW - (int)lbSz.Width) / 2;
                                g.DrawString("····························································································· Ngắt trang (Page Break) ·····························································································", pFont, Brushes.DimGray, lbX, gapMidY - (int)(lbSz.Height / 2));
                            }
                        }
                        int startCurrentPage = currentPage;
                        currentPage++;
                        currentY = startPageY + currentPage * (pageH + 30) + marginY;
                        
                        _paraLayoutCache[paraStartIndex] = new ParaLayoutCache {
                            Text = para, Zoom = ZoomLevel, MaxW = maxTextW,
                            CurrentYOffset = yOffset, CurrentPage = startCurrentPage,
                            FinalYOffset = currentY - startPageY, FinalPage = currentPage,
                            Lines = new List<WrapLineInfo>()
                        };

                        paraStartIndex += para.Length + 1;
                        continue;
                    }
                    else if (isPotentialBreak && pTrim == "[--- COLUMN BREAK ---]")
                    {
                        if (ShowFormattingMarks && currentY >= 140 && currentY <= height + 20)
                        {
                            using (Font pFont = new Font("Segoe UI", 8.0f * ZoomLevel, FontStyle.Italic))
                            {
                                g.DrawString("············································································· Ngắt cột (Column Break) ·····················································", pFont, Brushes.DimGray, pageX + marginX, currentY);
                            }
                        }
                        int startCurrentPage = currentPage;
                        currentPage++;
                        currentY = startPageY + currentPage * (pageH + 30) + marginY;
                        
                        _paraLayoutCache[paraStartIndex] = new ParaLayoutCache {
                            Text = para, Zoom = ZoomLevel, MaxW = maxTextW,
                            CurrentYOffset = yOffset, CurrentPage = startCurrentPage,
                            FinalYOffset = currentY - startPageY, FinalPage = currentPage,
                            Lines = new List<WrapLineInfo>()
                        };

                        paraStartIndex += para.Length + 1;
                        continue;
                    }
                    else if (isPotentialBreak && pTrim == "[--- TEXT WRAPPING BREAK ---]")
                    {
                        if (ShowFormattingMarks && currentY >= 140 && currentY <= height + 20)
                        {
                            using (Font pFont = new Font("Segoe UI", 8.0f * ZoomLevel, FontStyle.Italic))
                            {
                                g.DrawString("····················································· Ngắt bao quanh đối tượng (Text Wrapping Break) ·····················································", pFont, Brushes.DimGray, pageX + marginX, currentY);
                            }
                        }
                        currentY += (int)(18 * ZoomLevel);
                        foreach (var sh in DocumentShapes)
                        {
                            if (sh != null && sh.PageNumber == currentPage)
                            {
                                int sBot = startPageY + currentPage * (pageH + 30) + sh.PageY + (sh.BaseHeight + sh.HeightDelta);
                                if (sBot > currentY) currentY = sBot + 12;
                            }
                        }
                        paraStartIndex += para.Length + 1;
                        continue;
                    }
                    else if (isPotentialBreak && pTrim == "[--- SECTION BREAK (NEXT PAGE) ---]")
                    {
                        int gapMidY = startPageY + currentPage * (pageH + 30) + pageH + 15;
                        if (ShowFormattingMarks && gapMidY >= 140 && gapMidY <= height + 20)
                        {
                            using (Font pFont = new Font("Segoe UI", 8.0f * ZoomLevel, FontStyle.Italic))
                            {
                                SizeF lbSz = g.MeasureString(":::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: Ngắt phân đoạn (Trang tiếp theo / Next Page) ::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::", pFont);
                                int lbX = pageX + (pageW - (int)lbSz.Width) / 2;
                                g.DrawString(":::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: Ngắt phân đoạn (Trang tiếp theo / Next Page) ::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::", pFont, Brushes.DarkSlateGray, lbX, gapMidY - (int)(lbSz.Height / 2));
                            }
                        }
                        int startCurrentPage = currentPage;
                        currentPage++;
                        currentY = startPageY + currentPage * (pageH + 30) + marginY;
                        
                        _paraLayoutCache[paraStartIndex] = new ParaLayoutCache {
                            Text = para, Zoom = ZoomLevel, MaxW = maxTextW,
                            CurrentYOffset = yOffset, CurrentPage = startCurrentPage,
                            FinalYOffset = currentY - startPageY, FinalPage = currentPage,
                            Lines = new List<WrapLineInfo>()
                        };

                        paraStartIndex += para.Length + 1;
                        continue;
                    }
                    else if (isPotentialBreak && pTrim == "[--- SECTION BREAK (CONTINUOUS) ---]")
                    {
                        if (ShowFormattingMarks && currentY >= 140 && currentY <= height + 20)
                        {
                            using (Font pFont = new Font("Segoe UI", 8.0f * ZoomLevel, FontStyle.Italic))
                            {
                                g.DrawString(":::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: Ngắt phân đoạn (Liên tục / Continuous) ::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::", pFont, Brushes.DarkSlateGray, pageX + marginX, currentY);
                            }
                            currentY += (int)(20 * ZoomLevel);
                        }
                        paraStartIndex += para.Length + 1;
                        continue;
                    }
                    else if (isPotentialBreak && pTrim == "[--- SECTION BREAK (EVEN PAGE) ---]")
                    {
                        int gapMidY = startPageY + currentPage * (pageH + 30) + pageH + 15;
                        if (ShowFormattingMarks && gapMidY >= 140 && gapMidY <= height + 20)
                        {
                            using (Font pFont = new Font("Segoe UI", 8.0f * ZoomLevel, FontStyle.Italic))
                            {
                                SizeF lbSz = g.MeasureString(":::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: Ngắt phân đoạn (Trang chẵn / Even Page) ::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::", pFont);
                                int lbX = pageX + (pageW - (int)lbSz.Width) / 2;
                                g.DrawString(":::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: Ngắt phân đoạn (Trang chẵn / Even Page) ::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::", pFont, Brushes.DarkSlateGray, lbX, gapMidY - (int)(lbSz.Height / 2));
                            }
                        }
                        int startCurrentPage = currentPage;
                        currentPage++;
                        if ((currentPage + 1) % 2 != 0) currentPage++;
                        currentY = startPageY + currentPage * (pageH + 30) + marginY;
                        
                        _paraLayoutCache[paraStartIndex] = new ParaLayoutCache {
                            Text = para, Zoom = ZoomLevel, MaxW = maxTextW,
                            CurrentYOffset = yOffset, CurrentPage = startCurrentPage,
                            FinalYOffset = currentY - startPageY, FinalPage = currentPage,
                            Lines = new List<WrapLineInfo>()
                        };

                        paraStartIndex += para.Length + 1;
                        continue;
                    }
                    else if (isPotentialBreak && pTrim == "[--- SECTION BREAK (ODD PAGE) ---]")
                    {
                        int gapMidY = startPageY + currentPage * (pageH + 30) + pageH + 15;
                        if (ShowFormattingMarks && gapMidY >= 140 && gapMidY <= height + 20)
                        {
                            using (Font pFont = new Font("Segoe UI", 8.0f * ZoomLevel, FontStyle.Italic))
                            {
                                SizeF lbSz = g.MeasureString(":::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: Ngắt phân đoạn (Trang lẻ / Odd Page) ::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::", pFont);
                                int lbX = pageX + (pageW - (int)lbSz.Width) / 2;
                                g.DrawString(":::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: Ngắt phân đoạn (Trang lẻ / Odd Page) ::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::", pFont, Brushes.DarkSlateGray, lbX, gapMidY - (int)(lbSz.Height / 2));
                            }
                        }
                        int startCurrentPage = currentPage;
                        currentPage++;
                        if ((currentPage + 1) % 2 == 0) currentPage++;
                        currentY = startPageY + currentPage * (pageH + 30) + marginY;
                        
                        _paraLayoutCache[paraStartIndex] = new ParaLayoutCache {
                            Text = para, Zoom = ZoomLevel, MaxW = maxTextW,
                            CurrentYOffset = yOffset, CurrentPage = startCurrentPage,
                            FinalYOffset = currentY - startPageY, FinalPage = currentPage,
                            Lines = new List<WrapLineInfo>()
                        };

                        paraStartIndex += para.Length + 1;
                        continue;
                    }

                    if (para.Trim() == "[--- COVER PAGE START ---]" || para.Trim() == "[--- COVER PAGE END ---]")
                    {
                        paraStartIndex += para.Length + 1;
                        continue; // Hide markers
                    }

                    // 2. Real Vector Shape & Image Handler
                    if (para.StartsWith("![SHAPE:") || para.StartsWith("![IMAGE:") || (para.StartsWith("![IMAGE](") && para.EndsWith(")")) || para.Contains("HÌNH KHỐI VECTOR") || para.Contains("HÌNH ÁNH DỰ ÁN"))
                    {
                        string shapeId = "";
                        string shapeType = "Rectangle";
                        string imgPath = "";
                        int tagX = -1, tagY = -1, tagW = -1, tagH = -1, tagWrap = -1, tagPage = -1, tagStyle = -1, tagYRel = 0;

                        DocShapeObject.ParseShapeTag(para, out shapeId, out shapeType, out imgPath, out tagX, out tagY, out tagW, out tagH, out tagWrap, out tagPage, out tagStyle, out tagYRel);

                        if (string.IsNullOrEmpty(shapeId)) shapeId = "Shape_" + p;
                        DocShapeObject shapeObj = GetOrCreateDocShape(shapeId, shapeType);

                        if (!IsDraggingShape && (shapeObj != ActiveShape || DragShapeHandleIndex < 0))
                        {
                            if (tagW > 0) shapeObj.BaseWidth = tagW;
                            if (tagH > 0) shapeObj.BaseHeight = tagH;
                            if (tagWrap >= 0) shapeObj.WrapMode = tagWrap;
                            if (tagStyle >= 0) shapeObj.PictureStylePreset = tagStyle;

                            if (tagWrap == 0)
                            {
                                // Inline: rendered at currentY, no absolute page position needed
                                if (tagX >= 0) shapeObj.PageX = tagX;
                            }
                            else
                            {
                                // Floating: check if tagY is paragraph relative (tagYRel == 1) or absolute (tagYRel == 0)
                                if (!shapeObj.FixPosition)
                                {
                                    if (tagX >= 0 && !shapeObj.PositionCalculated) shapeObj.PageX = tagX;
                                    if (tagY >= 0)
                                    {
                                        if (tagYRel == 1) 
                                        {
                                            if (!shapeObj.PositionCalculated)
                                            {
                                                int pTopY = startPageY + currentPage * (pageH + 30) + marginY;
                                                shapeObj.PageY = (int)((currentY - pTopY) / ZoomLevel) + tagY;
                                                shapeObj.PageNumber = currentPage;
                                                shapeObj.PositionCalculated = true; // Lock position to prevent jitter
                                            }
                                        }
                                        else 
                                        {
                                            if (!shapeObj.PositionCalculated)
                                            {
                                                shapeObj.PageY = tagY;
                                                shapeObj.PageNumber = currentPage;
                                                shapeObj.PositionCalculated = true;
                                            }
                                        }
                                    }
                                    // Anchor to current page (the page where the anchor paragraph appears)
                                    if (!shapeObj.PositionCalculated) shapeObj.PageNumber = currentPage;
                                }
                                // If tagPage is explicitly set (user moved image), override page
                                if (tagPage >= 0 && tagPage != -1) shapeObj.PageNumber = tagPage;
                            }
                        }

                        if (!string.IsNullOrEmpty(imgPath))
                        {
                            shapeObj.ImagePath = imgPath;
                            if (shapeObj.CachedImage == null && !DocShapeObject.MissingImagesCache.Contains(imgPath))
                            {
                                if (System.IO.File.Exists(imgPath))
                                {
                                    int reqW = tagW > 0 ? tagW : shapeObj.BaseWidth;
                                    int reqH = tagH > 0 ? tagH : shapeObj.BaseHeight;
                                    shapeObj.CachedImage = DocShapeObject.LoadOptimizedImage(imgPath, reqW, reqH);
                                    if (shapeObj.CachedImage != null)
                                    {
                                        if (tagW <= 0 && (shapeObj.BaseWidth <= 180 || shapeObj.BaseHeight <= 110))
                                        {
                                            float ratio = (float)shapeObj.CachedImage.Width / Math.Max(1, shapeObj.CachedImage.Height);
                                            if (ratio >= 1.0f)
                                            {
                                                shapeObj.BaseWidth = Math.Min(480, Math.Max(150, shapeObj.CachedImage.Width));
                                                shapeObj.BaseHeight = (int)(shapeObj.BaseWidth / ratio);
                                            }
                                            else
                                            {
                                                shapeObj.BaseHeight = Math.Min(350, Math.Max(150, shapeObj.CachedImage.Height));
                                                shapeObj.BaseWidth = (int)(shapeObj.BaseHeight * ratio);
                                            }
                                        }
                                    }
                                }
                                
                                if (shapeObj.CachedImage == null)
                                {
                                    DocShapeObject.MissingImagesCache.Add(imgPath);
                                }
                            }
                        }

                        int sW = Math.Max((int)(20 * ZoomLevel), (int)((shapeObj.BaseWidth + shapeObj.WidthDelta) * ZoomLevel));
                        int sH = Math.Max((int)(15 * ZoomLevel), (int)((shapeObj.BaseHeight + shapeObj.HeightDelta) * ZoomLevel));

                        if (shapeObj.WrapMode != 0) // Floating shapes
                        {
                            int pTopY = startPageY + shapeObj.PageNumber * (pageH + 30) + marginY;
                            int shapeX = pageX + (int)(shapeObj.PageX * ZoomLevel);
                            int shapeY = pTopY + (int)(shapeObj.PageY * ZoomLevel);
                            shapeObj.LastBounds = new Rectangle(shapeX, shapeY, sW, sH);

                            _paraLayoutCache[paraStartIndex] = new ParaLayoutCache {
                                Text = para, Zoom = ZoomLevel, MaxW = maxTextW,
                                CurrentYOffset = yOffset, CurrentPage = currentPage,
                                FinalYOffset = yOffset, FinalPage = currentPage,
                                Lines = new List<WrapLineInfo>()
                            };

                            paraStartIndex += para.Length + 1;
                            continue;
                        }
                        // For WrapMode == 0 (In-Line), we do nothing here and let it fall through to the text layout engine!
                    }

                    // 4. Real Interactive Multi-Series Chart Handler
                    if (para.StartsWith("![CHART:") || para.Contains("BIỂU ĐỒ DOANH THU") || para.Contains("BIỂU ĐỒ SỐ LIỆU"))
                    {
                        string chartId = "";
                        string chartType = "Column_Clustered";
                        if (para.StartsWith("![CHART:"))
                        {
                            string inner = para.Substring(8).TrimEnd(']', '\r', '\n');
                            string[] parts = inner.Split(':');
                            foreach (var pItem in parts)
                            {
                                if (pItem.StartsWith("ID=")) chartId = pItem.Substring(3);
                                if (pItem.StartsWith("TYPE=")) chartType = pItem.Substring(5);
                            }
                        }
                        if (string.IsNullOrEmpty(chartId)) chartId = "Chart_" + p;
                        DocChartObject chartObj = GetOrCreateChart(chartId, chartType);
                        chartObj.CharIndex = paraStartIndex;

                        int chartW = Math.Max((int)(200 * ZoomLevel), (int)((chartObj.BaseWidth + chartObj.WidthDelta) * ZoomLevel));
                        int chartH = Math.Max((int)(120 * ZoomLevel), (int)((chartObj.BaseHeight + chartObj.HeightDelta) * ZoomLevel));

                        if (chartObj.WrapMode == 0) // Cùng dòng với văn bản (In-Line)
                        {
                            if (currentY + chartH > startPageY + currentPage * (pageH + 30) + pageH - bottomMarginY)
                            {
                                currentPage++;
                                currentY = startPageY + currentPage * (pageH + 30) + marginY;
                            }

                            int chartX = textX + (maxTextW - chartW) / 2;
                            int chartY = (int)Math.Round(currentY);
                            chartObj.LastBounds = new Rectangle(chartX, chartY, chartW, chartH);

                            DrawDocumentChart(g, chartObj, chartX, chartY, chartW, chartH, ribbon);
                            currentY += chartH + (int)(16 * ZoomLevel);
                        }
                        else
                        {
                            int pTopY = startPageY + chartObj.PageNumber * (pageH + 30) + marginY;
                            int chartX = pageX + (int)(chartObj.PageX * ZoomLevel);
                            int chartY = pTopY + (int)(chartObj.PageY * ZoomLevel);
                            chartObj.LastBounds = new Rectangle(chartX, chartY, chartW, chartH);

                            _paraLayoutCache[paraStartIndex] = new ParaLayoutCache {
                                Text = para, Zoom = ZoomLevel, MaxW = maxTextW,
                                CurrentYOffset = yOffset, CurrentPage = currentPage,
                                FinalYOffset = yOffset, FinalPage = currentPage,
                                Lines = new List<WrapLineInfo>()
                            };
                        }

                        paraStartIndex += para.Length + 1;
                        continue;
                    }

                    // 5. Real Callout Note Box Handler
                    if (para.StartsWith("![NOTEBOX:") || para.Contains("KHUNG GHI CHÚ CHÍNH THỨC"))
                    {
                        string noteTxt = para.Contains("![NOTEBOX:") ? para.Substring(10).TrimEnd(']', '\r', '\n') : "Nhập nội dung ghi chú tại đây...";
                        int noteW = maxTextW;
                        int noteH = (int)(60 * ZoomLevel);

                        if (currentY + noteH > startPageY + currentPage * (pageH + 30) + pageH - bottomMarginY)
                        {
                            currentPage++;
                            currentY = startPageY + currentPage * (pageH + 30) + marginY;
                        }

                        using (SolidBrush nBg = new SolidBrush(Color.FromArgb(240, 244, 249)))
                        using (SolidBrush barBrush = new SolidBrush(Color.FromArgb(11, 87, 208)))
                        using (Font nFont = new Font("Segoe UI", 9.5f * ZoomLevel, FontStyle.Regular))
                        using (Font boldFont = new Font("Segoe UI", 9.5f * ZoomLevel, FontStyle.Bold))
                        {
                            g.FillRectangle(nBg, textX, currentY, noteW, noteH);
                            g.FillRectangle(barBrush, textX, currentY, (int)(5 * ZoomLevel), noteH);
                            g.DrawString("💡 GHI CHÚ", boldFont, Brushes.DarkBlue, textX + 15, currentY + 10);
                            
                            StringFormat sf = StringFormat.GenericTypographic;
                            sf.FormatFlags |= StringFormatFlags.MeasureTrailingSpaces;
                            g.DrawString(noteTxt, nFont, Brushes.Black, textX + 15, currentY + 32, sf);

                            if (!hasSelection && CursorPosition >= paraStartIndex && CursorPosition <= paraStartIndex + para.Length)
                            {
                                int relCursor = CursorPosition - paraStartIndex;
                                if (relCursor >= 10 && relCursor <= 10 + noteTxt.Length)
                                {
                                    string beforeCursor = para.Substring(10, relCursor - 10);
                                    float cX = textX + 15 + g.MeasureString(beforeCursor, nFont, Point.Empty, sf).Width;
                                    cursorX = (int)cX;
                                    cursorY = (int)Math.Round(currentY + 32);
                                    cursorH = (int)(nFont.Height);
                                }
                            }
                        }

                        currentY += noteH + (int)(16 * ZoomLevel);
                        paraStartIndex += para.Length + 1;
                        continue;
                    }

                    // 5.5. Real Horizontal Divider Line Handler (Bottom border / hr from Word)
                    if (para.StartsWith("![DIVIDER:") || para.StartsWith("![HR:") || para == "---" || para == "***")
                    {
                        int divW = maxTextW;
                        int divH = (int)(14 * ZoomLevel);
                        if (currentY + divH > startPageY + currentPage * (pageH + 30) + pageH - bottomMarginY)
                        {
                            currentPage++;
                            currentY = startPageY + currentPage * (pageH + 30) + marginY;
                        }

                        Color divColor = Color.FromArgb(27, 54, 93); // #1B365D Navy Blue
                        if (para.Contains("COLOR=#"))
                        {
                            try
                            {
                                int cIdx = para.IndexOf("COLOR=#") + 7;
                                string hex = para.Substring(cIdx, 6);
                                int rC = Convert.ToInt32(hex.Substring(0, 2), 16);
                                int gC = Convert.ToInt32(hex.Substring(2, 2), 16);
                                int bC = Convert.ToInt32(hex.Substring(4, 2), 16);
                                divColor = Color.FromArgb(rC, gC, bC);
                            }
                            catch { }
                        }

                        using (Pen divPen = new Pen(divColor, Math.Max(1.5f, 1.5f * ZoomLevel)))
                        {
                            int lineY = (int)Math.Round(currentY + 6 * ZoomLevel);
                            g.DrawLine(divPen, textX, lineY, textX + divW, lineY);
                        }

                        currentY += divH;
                        paraStartIndex += para.Length + 1;
                        continue;
                    }

                    // Visual MS Word Table Engine: Render '|' lines as real GDI+ tables matching Image 2!
                    if (!string.IsNullOrWhiteSpace(para) && para.Trim().StartsWith("|"))
                    {
                        int inlineYBeforeTable = (int)Math.Round(currentY);
                        List<string> tableLines = new List<string>();
                        int tblParaStart = paraStartIndex;
                        int tblTotalLen = 0;

                        while (p < paragraphs.Length && !string.IsNullOrWhiteSpace(paragraphs[p]) && paragraphs[p].Trim().StartsWith("|"))
                        {
                            tableLines.Add(paragraphs[p]);
                            tblTotalLen += paragraphs[p].Length + 1;
                            p++;
                        }
                        p--; // Adjust for loop increment

                        // Parse clean rows (ignoring divider lines like |---|)
                        List<List<string>> tableRows = new List<List<string>>();
                        foreach (string tLine in tableLines)
                        {
                            if (tLine.Contains("---") || tLine.Contains("===")) continue;
                            string[] rawCells = tLine.Split('|');
                            List<string> rowCells = new List<string>();
                            for (int c = 1; c < rawCells.Length - 1; c++)
                            {
                                rowCells.Add(rawCells[c].Trim());
                            }
                            if (rowCells.Count > 0) tableRows.Add(rowCells);
                        }

                        if (tableRows.Count > 0)
                        {
                            int tblIdx = currentTableCount++;
                            int numRows = tableRows.Count;
                            int numCols = 0;
                            foreach (var r in tableRows) numCols = Math.Max(numCols, r.Count);
                            if (numCols <= 0) numCols = 1;


                            while (DocumentTables.Count <= tblIdx)
                            {
                                DocumentTables.Add(new DocTableObject());
                            }

                            // Initialize or validate per-column widths
                            if (!TableColWidths.ContainsKey(tblIdx) || TableColWidths[tblIdx].Count != numCols)
                            {
                                List<int> defaultW = new List<int>();
                                DocTableObject tObj = (tblIdx < DocumentTables.Count) ? DocumentTables[tblIdx] : null;
                                
                                int effTableW = maxTextW;
                                if (TableCustomSizes.ContainsKey(tblIdx))
                                {
                                    effTableW = (int)(TableCustomSizes[tblIdx].Width * ZoomLevel);
                                }
                                
                                int validCols = 0;
                                int totalPt = 0;
                                if (tObj != null && tObj.Rows.Count > 0 && tObj.Rows[0].Cells.Count == numCols)
                                {
                                    for (int c = 0; c < numCols; c++)
                                    {
                                        int pt = tObj.Rows[0].Cells[c].WidthPt;
                                        if (pt > 0)
                                        {
                                            validCols++;
                                            totalPt += pt;
                                        }
                                    }
                                }

                                if (validCols == numCols && totalPt > 0 && effTableW >= 50)
                                {
                                    if (numCols == 1)
                                    {
                                        int singleW = effTableW;
                                        if (totalPt > 0 && (totalPt + (tObj != null ? tObj.IndentPt : 0)) < (effTableW / (1.333333f * ZoomLevel) * 0.75f) && (tObj == null || tObj.IndentPt == 0))
                                        {
                                            singleW = Math.Min(effTableW, (int)(totalPt * 1.333333f * ZoomLevel));
                                        }
                                        defaultW.Add(singleW);
                                    }
                                    else
                                    {
                                        int totalPx = effTableW;
                                        if (tObj != null && tObj.WidthType == "dxa" && tObj.WidthPt > 0)
                                        {
                                            totalPx = (int)(tObj.WidthPt * 1.333333f * ZoomLevel);
                                        }
                                        else if (totalPt > 0 && (int)(totalPt * 1.333333f * ZoomLevel) > effTableW)
                                        {
                                            totalPx = (int)(totalPt * 1.333333f * ZoomLevel);
                                        }
                                        
                                        int allocatedW = 0;
                                        for (int c = 0; c < numCols; c++)
                                        {
                                            int pt = tObj.Rows[0].Cells[c].WidthPt;
                                            int w = (int)Math.Round((double)pt / totalPt * totalPx);
                                            
                                            if (c == numCols - 1) w = Math.Max((int)(20 * ZoomLevel), totalPx - allocatedW);
                                            w = Math.Max((int)(20 * ZoomLevel), w);
                                            defaultW.Add(w);
                                            allocatedW += w;
                                        }
                                    }
                                }
                                else
                                {
                                    int baseColW = effTableW / numCols;
                                    int allocatedW = 0;
                                    for (int c = 0; c < numCols; c++)
                                    {
                                        int w = (c == numCols - 1) ? Math.Max((int)(20 * ZoomLevel), effTableW - allocatedW) : baseColW;
                                        defaultW.Add(Math.Max((int)(20 * ZoomLevel), w));
                                        allocatedW += w;
                                    }
                                }
                                TableColWidths[tblIdx] = defaultW;
                            }

                            // Initialize or validate per-row heights - auto-size based on cell content
                            if (!TableRowHeights.ContainsKey(tblIdx) || TableRowHeights[tblIdx].Count != numRows)
                            {
                                int minRowH = (int)Math.Max(15f, 17.0f * ZoomLevel);
                                int defaultRowH = (int)(22.0f * ZoomLevel);
                                List<int> rowHList = new List<int>();
                                DocTableObject tObjH = (tblIdx < DocumentTables.Count) ? DocumentTables[tblIdx] : null;
                                for (int r = 0; r < numRows; r++)
                                {
                                    int rowH = defaultRowH;
                                    if (!TableCustomSizes.ContainsKey(tblIdx) && tObjH != null && r < tObjH.Rows.Count)
                                    {
                                        float maxCellH = 0f;
                                        for (int c = 0; c < tObjH.Rows[r].Cells.Count; c++)
                                        {
                                            var cell = tObjH.Rows[r].Cells[c];
                                            int colW = (TableColWidths.ContainsKey(tblIdx) && c < TableColWidths[tblIdx].Count) ? TableColWidths[tblIdx][c] : (maxTextW / numCols);
                                            int padX = (numCols == 1) ? (int)Math.Max(2f, 2.5f * ZoomLevel) : (int)(5 * ZoomLevel);
                                            float availW = Math.Max(20f, colW - padX * 2);

                                            if (cell.Paragraphs != null && cell.Paragraphs.Count > 0)
                                            {
                                                float cellH = (1.5f * ZoomLevel);
                                                for (int pi = 0; pi < cell.Paragraphs.Count; pi++)
                                                {
                                                    var cellPara = cell.Paragraphs[pi];
                                                    if (cellPara.SpacingBeforePt > 0)
                                                    {
                                                        cellH += cellPara.SpacingBeforePt * 1.333333f * ZoomLevel;
                                                    }

                                                    string shpId, shpTp, shpImg, remTxt;
                                                    int tagW, tagH;
                                                    if (TryParseCellShape(cellPara.Text, out shpId, out shpTp, out shpImg, out tagW, out tagH, out remTxt))
                                                    {
                                                        if (!string.IsNullOrEmpty(shpImg))
                                                        {
                                                            float maxW = Math.Max(20f, availW);
                                                            float imgW = (tagW > 0 ? tagW : 240) * ZoomLevel;
                                                            float imgH = (tagH > 0 ? tagH : 180) * ZoomLevel;
                                                            if (imgW > maxW && imgW > 0) { float ratio = maxW / imgW; imgW = maxW; imgH = imgH * ratio; }
                                                            cellH += imgH + 4.0f * ZoomLevel;
                                                        }
                                                    }

                                                    float pSize = (cellPara.FontSize > 0 ? cellPara.FontSize : 11.0f) * ZoomLevel;
                                                    FontStyle pStyle = FontStyle.Regular;
                                                    if (cellPara.Bold) pStyle |= FontStyle.Bold;
                                                    if (cellPara.Italic) pStyle |= FontStyle.Italic;
                                                    Font pFont = GetCachedFont(cellPara.FontName ?? "Times New Roman", pSize, pStyle);
                                                    var pLines = BreakCellTextIntoLines(g, cellPara.Text ?? "", pFont, availW);
                                                    float lineH = pFont.GetHeight(g) * (cellPara.LineSpacing > 0 ? cellPara.LineSpacing : 1.0f);
                                                    if (lineH <= 0) lineH = pSize * 1.35f;
                                                    int effectiveLines = Math.Max(1, pLines.Count);
                                                    cellH += effectiveLines * lineH;
                                                    if (cellPara.SpacingAfterPt > 0)
                                                    {
                                                        cellH += cellPara.SpacingAfterPt * 1.333333f * ZoomLevel;
                                                    }
                                                }
                                                if (cellH > maxCellH) maxCellH = cellH;
                                            }
                                            else if (!string.IsNullOrEmpty(cell.Text))
                                            {
                                                float shpH = 0;
                                                string shpId, shpTp, shpImg, remTxt;
                                                int tagW, tagH;
                                                if (TryParseCellShape(cell.Text, out shpId, out shpTp, out shpImg, out tagW, out tagH, out remTxt))
                                                {
                                                    if (!string.IsNullOrEmpty(shpImg))
                                                    {
                                                        float maxW = Math.Max(20f, availW);
                                                        float imgW = (tagW > 0 ? tagW : 240) * ZoomLevel;
                                                        float imgH = (tagH > 0 ? tagH : 180) * ZoomLevel;
                                                        if (imgW > maxW && imgW > 0) { float ratio = maxW / imgW; imgW = maxW; imgH = imgH * ratio; }
                                                        shpH = imgH + 4.0f * ZoomLevel;
                                                    }
                                                }

                                                float fSize = (cell.FontSize > 0 ? cell.FontSize : 11.0f) * ZoomLevel;
                                                FontStyle fStyle = FontStyle.Regular;
                                                if (cell.Bold) fStyle |= FontStyle.Bold;
                                                if (cell.Italic) fStyle |= FontStyle.Italic;
                                                Font cFont = GetCachedFont(cell.FontName ?? "Times New Roman", fSize, fStyle);
                                                var cLines = BreakCellTextIntoLines(g, cell.Text, cFont, availW);
                                                float lineH = cFont.GetHeight(g);
                                                if (lineH <= 0) lineH = fSize * 1.35f;
                                                int effectiveLines = Math.Max(1, cLines.Count);
                                                float cellH = effectiveLines * lineH + shpH + (2.0f * ZoomLevel);
                                                if (cellH > maxCellH) maxCellH = cellH;
                                            }
                                            else
                                            {
                                                float fSize = (cell.FontSize > 0 ? cell.FontSize : 11.0f) * ZoomLevel;
                                                FontStyle fStyle = FontStyle.Regular;
                                                if (cell.Bold) fStyle |= FontStyle.Bold;
                                                if (cell.Italic) fStyle |= FontStyle.Italic;
                                                Font cFont = GetCachedFont(cell.FontName ?? "Times New Roman", fSize, fStyle);
                                                float lineH = cFont.GetHeight(g);
                                                if (lineH <= 0) lineH = fSize * 1.35f;
                                                float cellH = lineH + (2.0f * ZoomLevel);
                                                if (cellH > maxCellH) maxCellH = cellH;
                                            }
                                        }
                                        if (maxCellH < minRowH) maxCellH = minRowH;
                                        rowH = (int)Math.Ceiling(maxCellH);
                                        if (tObjH.Rows[r].HeightPt > 0)
                                        {
                                            int specifiedH = (int)Math.Round(tObjH.Rows[r].HeightPt * 1.333333f * ZoomLevel);
                                            rowH = Math.Max(rowH, specifiedH);
                                        }
                                    }
                                    else if (TableCustomSizes.ContainsKey(tblIdx))
                                    {
                                        rowH = Math.Max(15, TableCustomSizes[tblIdx].Height / numRows);
                                    }
                                    rowHList.Add(rowH);
                                }
                                TableRowHeights[tblIdx] = rowHList;
                            }

                            int tWrap = TableWrapModes.ContainsKey(tblIdx) ? TableWrapModes[tblIdx] : 0;
                            DocTableObject tObjLayout = (tblIdx < DocumentTables.Count) ? DocumentTables[tblIdx] : null;

                            // Calculate actual total table width
                            int actualTableW = 0;
                            if (TableColWidths.ContainsKey(tblIdx))
                            {
                                foreach (var cw in TableColWidths[tblIdx]) actualTableW += cw;
                            }
                            if (actualTableW <= 0) actualTableW = maxTextW;

                            int tableX = pageX + marginX;
                            if (tWrap == 1 && TablePageX.ContainsKey(tblIdx))
                            {
                                tableX = pageX + (int)(TablePageX[tblIdx] * ZoomLevel);
                            }
                            else if (tObjLayout != null)
                            {
                                if (tObjLayout.Alignment == 1) // Center: expands symmetrically into both margins when wider than maxTextW
                                {
                                    tableX = pageX + marginX + (maxTextW - actualTableW) / 2;
                                }
                                else if (tObjLayout.Alignment == 2) // Right
                                {
                                    tableX = pageX + marginX + (maxTextW - actualTableW);
                                }
                                else if (tObjLayout.IndentPt != 0 && !(numCols == 1 && actualTableW >= maxTextW - 15))
                                {
                                    tableX = pageX + marginX + (int)(tObjLayout.IndentPt * 1.333333f * ZoomLevel);
                                }
                            }
                            int maxPaperRight = pageX + pageW;
                            int maxAvailW = maxPaperRight - tableX;

                            // Calculate column X positions
                            List<int> colXPos = new List<int>();
                            int runX = tableX;
                            for (int c = 0; c < numCols; c++)
                            {
                                colXPos.Add(runX);
                                runX += TableColWidths[tblIdx][c];
                            }
                            int tableW = runX - tableX;

                            // Calculate row Y positions with per-row page overflow splitting
                            int tableY = (tWrap == 1 && TablePageY.ContainsKey(tblIdx)) ? (startPageY + (int)(TablePageY[tblIdx] * ZoomLevel)) : (int)Math.Round(currentY + 2 * ZoomLevel);
                            List<int> rowYPos = new List<int>();
                            int runY = tableY;

                            if (tWrap == 0)
                            {
                                int curPageTopY = startPageY + currentPage * (pageH + 30) + marginY;
                                int curPageBottomY = startPageY + currentPage * (pageH + 30) + pageH - bottomMarginY;

                                // If current inline position cannot even fit the first row + margin, push table to start of next page
                                int firstRowH = (numRows > 0 && TableRowHeights.ContainsKey(tblIdx) && TableRowHeights[tblIdx].Count > 0) ? TableRowHeights[tblIdx][0] : (int)(24 * ZoomLevel);
                                if (runY > curPageTopY + 10 && runY + firstRowH > curPageBottomY)
                                {
                                    currentPage++;
                                    curPageTopY = startPageY + currentPage * (pageH + 30) + marginY;
                                    curPageBottomY = startPageY + currentPage * (pageH + 30) + pageH - bottomMarginY;
                                    tableY = curPageTopY;
                                    runY = curPageTopY;
                                }

                                for (int r = 0; r < numRows; r++)
                                {
                                    int rH = (TableRowHeights.ContainsKey(tblIdx) && r < TableRowHeights[tblIdx].Count) ? TableRowHeights[tblIdx][r] : (int)(24 * ZoomLevel);

                                    // Check if this row would spill over the bottom margin of the current page!
                                    if (runY > curPageTopY + 10 && runY + rH > curPageBottomY)
                                    {
                                        // SPLIT ROW TO NEXT PAGE!
                                        currentPage++;
                                        curPageTopY = startPageY + currentPage * (pageH + 30) + marginY;
                                        curPageBottomY = startPageY + currentPage * (pageH + 30) + pageH - bottomMarginY;
                                        runY = curPageTopY;
                                    }

                                    rowYPos.Add(runY);
                                    runY += rH;
                                }
                            }
                            else
                            {
                                // Floating (Wrap Around)
                                for (int r = 0; r < numRows; r++)
                                {
                                    int rH = (TableRowHeights.ContainsKey(tblIdx) && r < TableRowHeights[tblIdx].Count) ? TableRowHeights[tblIdx][r] : (int)(24 * ZoomLevel);
                                    rowYPos.Add(runY);
                                    runY += rH;
                                }
                            }
                            int tableH = runY - tableY;

                            if (tWrap == 1)
                            {
                                TableFloatingBounds[tblIdx] = new Rectangle(tableX, tableY, tableW, tableH);
                            }
                            else
                            {
                                TableFloatingBounds.Remove(tblIdx);
                            }

                            // Hit-test handles for move/resize (resize handle on right edge)
                            TableBoundsList.Add(new Rectangle(tableX, tableY, tableW, tableH));
                            Rectangle moveHitRect = new Rectangle(tableX - 18, tableY - 18, 16, 16);
                            Rectangle resizeHitRect = new Rectangle(tableX + tableW - 12, tableY + tableH - 12, 24, 24);
                            MoveHandleRects.Add(moveHitRect);
                            ResizeHandleRects.Add(resizeHitRect);

                            // Record char range for snap-on-drop
                            TableCharRanges[tblIdx] = new int[] { tblParaStart, tblTotalLen };

                            bool thisTableDragging = (IsDraggingMove && DragTableIndex == tblIdx);
                            Rectangle handleHitRect = new Rectangle(tableX - 18, tableY - 18, 16, 16);
                            bool mouseInsideTable = (HoveredMousePoint.X >= tableX && HoveredMousePoint.X <= tableX + tableW && HoveredMousePoint.Y >= tableY && HoveredMousePoint.Y <= tableY + tableH);
                            bool mouseOverHandle = handleHitRect.Contains(HoveredMousePoint);
                            bool caretInsideTable = TableCharRanges.ContainsKey(tblIdx) && CursorPosition >= TableCharRanges[tblIdx][0] && CursorPosition <= TableCharRanges[tblIdx][0] + TableCharRanges[tblIdx][1];
                            bool isTableHoveredOrActive = thisTableDragging || (ActiveTableLayoutOptionsIndex == tblIdx) || (SelectedColumnTableIndex == tblIdx) || mouseInsideTable || mouseOverHandle || caretInsideTable;

                            int effTableY = (ViewMode == 0) ? (tableY - ReadModePageIndex * (pageH + 30)) : tableY;
                            bool isTableVisible = (ViewMode == 0)
                                ? (effTableY + tableH >= startPageY - 20 && effTableY <= startPageY + pageH + 20)
                                : (tableY + tableH >= 140 && tableY <= height + 20);
                            if (!isTableVisible && !isTableHoveredOrActive)
                            {
                                if (tWrap == 0)
                                {
                                    currentY = tableY + tableH + (int)(3 * ZoomLevel);
                                    DocParagraphGaps.Add(new ParagraphGap { ScreenY = (int)Math.Round(currentY), CharIndex = tblParaStart + tblTotalLen, VirtualEntersNeeded = 0 });
                                }
                                else
                                {
                                    currentY = inlineYBeforeTable;
                                }
                                paraStartIndex += tblTotalLen;
                                continue;
                            }

                            // Draw Move Handle (✥) ONLY when table is hovered, selected or dragged
                            if (isTableHoveredOrActive)
                            {
                                int mhX = tableX - 18;
                                int mhY = tableY - 18;
                                int mhSize = 16;
                                Rectangle mhRect = new Rectangle(mhX, mhY, mhSize, mhSize);
                                using (SolidBrush handleBg = new SolidBrush(thisTableDragging ? Color.FromArgb(220, 235, 252) : (mouseOverHandle ? Color.FromArgb(230, 240, 250) : Color.FromArgb(248, 249, 250))))
                                using (Pen handlePen = new Pen(mouseOverHandle ? Color.FromArgb(43, 87, 154) : Color.FromArgb(170, 170, 170), 1))
                                {
                                    g.FillRectangle(handleBg, mhRect);
                                    g.DrawRectangle(handlePen, mhRect);

                                    using (Pen arrowPen = new Pen(mouseOverHandle ? Color.FromArgb(43, 87, 154) : Color.FromArgb(90, 90, 90), 1.2f))
                                    {
                                        int cx = mhX + mhSize / 2;
                                        int cy = mhY + mhSize / 2;
                                        g.DrawLine(arrowPen, cx - 4, cy, cx + 4, cy);
                                        g.DrawLine(arrowPen, cx, cy - 4, cx, cy + 4);
                                        g.DrawLine(arrowPen, cx - 4, cy, cx - 2, cy - 2);
                                        g.DrawLine(arrowPen, cx - 4, cy, cx - 2, cy + 2);
                                        g.DrawLine(arrowPen, cx + 4, cy, cx + 2, cy - 2);
                                        g.DrawLine(arrowPen, cx + 4, cy, cx + 2, cy + 2);
                                        g.DrawLine(arrowPen, cx, cy - 4, cx - 2, cy - 2);
                                        g.DrawLine(arrowPen, cx, cy - 4, cx + 2, cy - 2);
                                        g.DrawLine(arrowPen, cx, cy + 4, cx - 2, cy + 2);
                                        g.DrawLine(arrowPen, cx, cy + 4, cx + 2, cy + 2);
                                    }
                                }
                            }

                            // Render MS Word '+' Insert Row and Column Buttons ONLY when hovered precisely at gridline boundaries
                            int hX = HoveredMousePoint.X;
                            int hY = HoveredMousePoint.Y;

                            // Column Insert '+' Buttons at top boundary of columns (Word style)
                            if (hY >= tableY - 8 && hY <= tableY + 12)
                            {
                                for (int c = 0; c < numCols; c++)
                                {
                                    int bX = colXPos[c] + TableColWidths[tblIdx][c];
                                    if (Math.Abs(hX - bX) <= 6)
                                    {
                                        using (Pen guidePen = new Pen(Color.FromArgb(43, 87, 154), 1.5f))
                                        {
                                            g.DrawLine(guidePen, bX, tableY, bX, tableY + tableH);
                                        }

                                        Rectangle colBtnRect = new Rectangle(bX - 8, tableY - 8, 16, 16);
                                        InsertButtonHits.Add(new InsertButtonHit { Rect = colBtnRect, TableIndex = tblIdx, IsRowInsert = false, InsertIndex = c + 1 });

                                        using (SolidBrush circleBg = new SolidBrush(Color.White))
                                        using (Pen circlePen = new Pen(Color.FromArgb(43, 87, 154), 1.2f))
                                        using (Pen plusPen = new Pen(Color.FromArgb(43, 87, 154), 1.4f))
                                        {
                                            g.FillEllipse(circleBg, colBtnRect);
                                            g.DrawEllipse(circlePen, colBtnRect);
                                            g.DrawLine(plusPen, bX - 4, tableY, bX + 4, tableY);
                                            g.DrawLine(plusPen, bX, tableY - 4, bX, tableY + 4);
                                        }
                                        break;
                                    }
                                }
                            }

                            // Row Insert '+' Buttons at left boundary of rows (Word style)
                            if (hX >= tableX - 8 && hX <= tableX + 12)
                            {
                                for (int r = 0; r < numRows; r++)
                                {
                                    int bY = rowYPos[r] + TableRowHeights[tblIdx][r];
                                    if (Math.Abs(hY - bY) <= 6)
                                    {
                                        using (Pen guidePen = new Pen(Color.FromArgb(43, 87, 154), 1.5f))
                                        {
                                            g.DrawLine(guidePen, tableX, bY, tableX + tableW, bY);
                                        }

                                        Rectangle rowBtnRect = new Rectangle(tableX - 8, bY - 8, 16, 16);
                                        InsertButtonHits.Add(new InsertButtonHit { Rect = rowBtnRect, TableIndex = tblIdx, IsRowInsert = true, InsertIndex = r + 1 });

                                        using (SolidBrush circleBg = new SolidBrush(Color.White))
                                        using (Pen circlePen = new Pen(Color.FromArgb(43, 87, 154), 1.2f))
                                        using (Pen plusPen = new Pen(Color.FromArgb(43, 87, 154), 1.4f))
                                        {
                                            g.FillEllipse(circleBg, rowBtnRect);
                                            g.DrawEllipse(circlePen, rowBtnRect);
                                            g.DrawLine(plusPen, tableX - 4, bY, tableX + 4, bY);
                                            g.DrawLine(plusPen, tableX, bY - 4, tableX, bY + 4);
                                        }
                                        break;
                                    }
                                }
                            }

                            // Draw Cells (Modern Word-style table rendering)
                            using (SolidBrush headerBrush = new SolidBrush(thisTableDragging ? Color.FromArgb(180, 255, 255, 255) : Color.White))
                            using (SolidBrush evenCellBrush = new SolidBrush(thisTableDragging ? Color.FromArgb(80, 255, 255, 255) : Color.White))
                            using (SolidBrush oddCellBrush = new SolidBrush(thisTableDragging ? Color.FromArgb(80, 255, 255, 255) : Color.White))
                            using (Pen gridPen = new Pen(thisTableDragging ? Color.FromArgb(120, 0, 0, 0) : Color.Black, 1.0f))
                            using (Font headerFont = new Font("Segoe UI", 10.0f * ZoomLevel, FontStyle.Bold))
                            using (Font cellFont = new Font("Segoe UI", 10.0f * ZoomLevel, FontStyle.Regular))
                            {
                                List<string> cleanDataLines = new List<string>();
                                List<int> cleanLineStarts = new List<int>();
                                int lStart = tblParaStart;
                                foreach (string tLine in tableLines)
                                {
                                    if (!tLine.Contains("---") && !tLine.Contains("==="))
                                    {
                                        cleanDataLines.Add(tLine);
                                        cleanLineStarts.Add(lStart);
                                    }
                                    lStart += tLine.Length + 1;
                                }

                                for (int r = 0; r < numRows; r++)
                                {
                                    string lineStr = (r < cleanDataLines.Count) ? cleanDataLines[r] : "";
                                    int rowLineStart = (r < cleanLineStarts.Count) ? cleanLineStarts[r] : 0;
                                    int cellY = rowYPos[r];
                                    int cellH = TableRowHeights[tblIdx][r];
                                    bool isHeaderRow = (r == 0);

                                    for (int c = 0; c < numCols; c++)
                                    {
                                        int cellX = colXPos[c];
                                        int cellW = TableColWidths[tblIdx][c];
                                        Rectangle cellRect = new Rectangle(cellX, cellY, cellW, cellH);

                                        while (DocumentTables.Count <= tblIdx)
                                        {
                                            DocumentTables.Add(new DocTableObject());
                                        }
                                        DocTableObject tObj = DocumentTables[tblIdx];
                                        while (tObj.Rows.Count <= r)
                                        {
                                            tObj.Rows.Add(new DocTableRow());
                                        }
                                        while (tObj.Rows[r].Cells.Count <= c)
                                        {
                                            tObj.Rows[r].Cells.Add(new DocTableCell());
                                        }
                                        DocTableCell cellData = tObj.Rows[r].Cells[c];

                                        Color bgColor = Color.Transparent;
                                        if (cellData != null && cellData.BackgroundColor != Color.Transparent && cellData.BackgroundColor != Color.Empty)
                                        {
                                            bgColor = cellData.BackgroundColor;
                                        }

                                        // Fill Solid Background
                                        if (thisTableDragging)
                                        {
                                            g.FillRectangle(new SolidBrush(Color.FromArgb(80, 255, 255, 255)), cellRect);
                                        }
                                        else if (bgColor != Color.Transparent)
                                        {
                                            using (SolidBrush bgB = new SolidBrush(bgColor)) g.FillRectangle(bgB, cellRect);
                                        }

                                        // Draw Column Selection Highlight (MS Word table column selection)
                                        bool isColSelected = (SelectedColumnTableIndex == tblIdx &&
                                            c >= Math.Min(SelectedColumnIndex, SelectedColumnEndIndex) &&
                                            c <= Math.Max(SelectedColumnIndex, SelectedColumnEndIndex));
                                        if (isColSelected)
                                        {
                                            using (SolidBrush colSelBrush = new SolidBrush(Color.FromArgb(90, 0, 120, 215)))
                                            {
                                                g.FillRectangle(colSelBrush, cellRect);
                                            }
                                        }

                                        // Draw borders respecting per-cell border settings
                                        bool drawTop = (cellData == null || cellData.HasBorderTop);
                                        bool drawBottom = (cellData == null || cellData.HasBorderBottom);
                                        bool drawLeft = (cellData == null || cellData.HasBorderLeft);
                                        bool drawRight = (cellData == null || cellData.HasBorderRight);

                                        if (drawTop)
                                        {
                                            string bStyle = (cellData != null && !string.IsNullOrEmpty(cellData.BorderTopStyle)) ? cellData.BorderTopStyle : (tObj != null ? (r == 0 ? tObj.BorderTopStyle : tObj.BorderInsideHStyle) : "single");
                                            float bWidth = (cellData != null && cellData.BorderTopWidthPt > 0) ? cellData.BorderTopWidthPt : (tObj != null ? (r == 0 ? tObj.BorderTopWidthPt : tObj.BorderInsideHWidthPt) : 0.5f);
                                            Color bColor = (cellData != null && cellData.BorderTopColor != Color.Empty && cellData.BorderTopColor != Color.Transparent) ? cellData.BorderTopColor : (tObj != null ? (r == 0 ? tObj.BorderTopColor : tObj.BorderInsideHColor) : Color.Black);
                                            if (thisTableDragging) bColor = Color.FromArgb(120, bColor.R, bColor.G, bColor.B);
                                            DrawTableCellBorder(g, cellRect.Left, cellRect.Top, cellRect.Right, cellRect.Top, bStyle, bWidth, bColor, ZoomLevel, true);
                                        }
                                        else if (ShowTableGridlines)
                                        {
                                            using (Pen dotPen = new Pen(Color.FromArgb(170, 195, 215), 1.0f) { DashStyle = DashStyle.Dot })
                                                g.DrawLine(dotPen, cellRect.Left, cellRect.Top, cellRect.Right, cellRect.Top);
                                        }

                                        if (drawBottom)
                                        {
                                            string bStyle = (cellData != null && !string.IsNullOrEmpty(cellData.BorderBottomStyle)) ? cellData.BorderBottomStyle : (tObj != null ? (r == numRows - 1 ? tObj.BorderBottomStyle : tObj.BorderInsideHStyle) : "single");
                                            float bWidth = (cellData != null && cellData.BorderBottomWidthPt > 0) ? cellData.BorderBottomWidthPt : (tObj != null ? (r == numRows - 1 ? tObj.BorderBottomWidthPt : tObj.BorderInsideHWidthPt) : 0.5f);
                                            Color bColor = (cellData != null && cellData.BorderBottomColor != Color.Empty && cellData.BorderBottomColor != Color.Transparent) ? cellData.BorderBottomColor : (tObj != null ? (r == numRows - 1 ? tObj.BorderBottomColor : tObj.BorderInsideHColor) : Color.Black);
                                            if (thisTableDragging) bColor = Color.FromArgb(120, bColor.R, bColor.G, bColor.B);
                                            DrawTableCellBorder(g, cellRect.Left, cellRect.Bottom, cellRect.Right, cellRect.Bottom, bStyle, bWidth, bColor, ZoomLevel, false);
                                        }
                                        else if (ShowTableGridlines)
                                        {
                                            using (Pen dotPen = new Pen(Color.FromArgb(170, 195, 215), 1.0f) { DashStyle = DashStyle.Dot })
                                                g.DrawLine(dotPen, cellRect.Left, cellRect.Bottom, cellRect.Right, cellRect.Bottom);
                                        }

                                        if (drawLeft)
                                        {
                                            string bStyle = (cellData != null && !string.IsNullOrEmpty(cellData.BorderLeftStyle)) ? cellData.BorderLeftStyle : (tObj != null ? (c == 0 ? tObj.BorderLeftStyle : tObj.BorderInsideVStyle) : "single");
                                            float bWidth = (cellData != null && cellData.BorderLeftWidthPt > 0) ? cellData.BorderLeftWidthPt : (tObj != null ? (c == 0 ? tObj.BorderLeftWidthPt : tObj.BorderInsideVWidthPt) : 0.5f);
                                            Color bColor = (cellData != null && cellData.BorderLeftColor != Color.Empty && cellData.BorderLeftColor != Color.Transparent) ? cellData.BorderLeftColor : (tObj != null ? (c == 0 ? tObj.BorderLeftColor : tObj.BorderInsideVColor) : Color.Black);
                                            if (thisTableDragging) bColor = Color.FromArgb(120, bColor.R, bColor.G, bColor.B);
                                            DrawTableCellBorder(g, cellRect.Left, cellRect.Top, cellRect.Left, cellRect.Bottom, bStyle, bWidth, bColor, ZoomLevel, true);
                                        }
                                        else if (ShowTableGridlines)
                                        {
                                            using (Pen dotPen = new Pen(Color.FromArgb(170, 195, 215), 1.0f) { DashStyle = DashStyle.Dot })
                                                g.DrawLine(dotPen, cellRect.Left, cellRect.Top, cellRect.Left, cellRect.Bottom);
                                        }

                                        if (drawRight)
                                        {
                                            string bStyle = (cellData != null && !string.IsNullOrEmpty(cellData.BorderRightStyle)) ? cellData.BorderRightStyle : (tObj != null ? (c == numCols - 1 ? tObj.BorderRightStyle : tObj.BorderInsideVStyle) : "single");
                                            float bWidth = (cellData != null && cellData.BorderRightWidthPt > 0) ? cellData.BorderRightWidthPt : (tObj != null ? (c == numCols - 1 ? tObj.BorderRightWidthPt : tObj.BorderInsideVWidthPt) : 0.5f);
                                            Color bColor = (cellData != null && cellData.BorderRightColor != Color.Empty && cellData.BorderRightColor != Color.Transparent) ? cellData.BorderRightColor : (tObj != null ? (c == numCols - 1 ? tObj.BorderRightColor : tObj.BorderInsideVColor) : Color.Black);
                                            if (thisTableDragging) bColor = Color.FromArgb(120, bColor.R, bColor.G, bColor.B);
                                            DrawTableCellBorder(g, cellRect.Right, cellRect.Top, cellRect.Right, cellRect.Bottom, bStyle, bWidth, bColor, ZoomLevel, false);
                                        }
                                        else if (ShowTableGridlines)
                                        {
                                            using (Pen dotPen = new Pen(Color.FromArgb(170, 195, 215), 1.0f) { DashStyle = DashStyle.Dot })
                                                g.DrawLine(dotPen, cellRect.Right, cellRect.Top, cellRect.Right, cellRect.Bottom);
                                        }

                                        // 1. Calculate live text and cell boundaries in PieceTable
                                        string liveRowTxt = (r < tableRows.Count && c < tableRows[r].Count) ? tableRows[r][c] : "";
                                        string cellTxt;
                                        if (cellData != null)
                                        {
                                            if (!string.IsNullOrEmpty(cellData.Text))
                                            {
                                                string flatDocx = cellData.Text.Replace("\r", " ").Replace("\n", " ");
                                                if (flatDocx != liveRowTxt)
                                                {
                                                    // User edited cell in PieceTable -> sync immediately!
                                                    cellData.Text = liveRowTxt;
                                                }
                                                cellTxt = cellData.Text;
                                            }
                                            else
                                            {
                                                cellData.Text = liveRowTxt;
                                                cellTxt = liveRowTxt;
                                            }
                                        }
                                        else
                                        {
                                            cellTxt = liveRowTxt;
                                        }

                                        // 2. Resolve cell font, colors, and layout rectangles
                                        Brush tBrush = Brushes.Black;
                                        if (cellData != null && cellData.TextColor != Color.Transparent && cellData.TextColor != Color.Empty && cellData.TextColor != Color.Black)
                                        {
                                            tBrush = new SolidBrush(cellData.TextColor);
                                        }
                                        else if (bgColor != Color.Transparent)
                                        {
                                            float luma = bgColor.R * 0.3f + bgColor.G * 0.59f + bgColor.B * 0.11f;
                                            if (luma < 128) tBrush = Brushes.White;
                                        }

                                        string fName = (cellData != null && !string.IsNullOrEmpty(cellData.FontName)) ? cellData.FontName : "Times New Roman";
                                        float fSize = (cellData != null && cellData.FontSize > 0) ? cellData.FontSize : 11.0f;
                                        FontStyle fStyle = FontStyle.Regular;
                                        if (cellData != null && cellData.Bold) fStyle |= FontStyle.Bold;
                                        if (cellData != null && cellData.Italic) fStyle |= FontStyle.Italic;
                                        else if (r == 0 && bgColor != Color.Transparent) fStyle |= FontStyle.Bold;

                                        Font fToUse = GetCachedFont(fName, fSize * ZoomLevel, fStyle);
                                        float padPt = (tObj != null && tObj.CellPaddingPt > 0) ? tObj.CellPaddingPt : 4.0f;
                                        int padX = (numCols == 1) ? (int)Math.Max(2f, 2.5f * ZoomLevel) : (int)Math.Max(2f, padPt * 1.25f * ZoomLevel);
                                        int padY = (int)Math.Max(1f, padPt * 0.75f * ZoomLevel);
                                        RectangleF txtRect = new RectangleF(cellX + padX, cellY + padY, cellW - padX * 2, cellH - padY * 2);

                                        StringAlignment vAlign = StringAlignment.Near;
                                        if (cellData != null && cellData.VerticalAlignment == 1) vAlign = StringAlignment.Center;
                                        else if (cellData != null && cellData.VerticalAlignment == 2) vAlign = StringAlignment.Far;

                                        StringAlignment hAlign = StringAlignment.Near;
                                        int cellAlignToUse = (cellData != null) ? cellData.Alignment : 0;
                                        if (cellAlignToUse == 0 && cellData != null && cellData.Paragraphs != null && cellData.Paragraphs.Count > 0 && cellData.Paragraphs[0].Alignment != 0)
                                        {
                                            cellAlignToUse = cellData.Paragraphs[0].Alignment;
                                        }
                                        if (cellAlignToUse == 1) hAlign = StringAlignment.Center;
                                        else if (cellAlignToUse == 2) hAlign = StringAlignment.Far;
                                        else if (cellAlignToUse == 3) hAlign = StringAlignment.Near;
                                        else if (isHeaderRow && cellTxt.Length <= 8) hAlign = StringAlignment.Center;

                                        // 3. Compute In-Cell Character Boundaries in PieceTable
                                        int cellContentGlobalStart = -1;
                                        int cellContentGlobalLen = 0;
                                        if (lineStr.Contains("|"))
                                        {
                                            int pipeCount = 0;
                                            int p1 = -1;
                                            int p2 = -1;
                                            for (int k = 0; k < lineStr.Length; k++)
                                            {
                                                if (lineStr[k] == '|')
                                                {
                                                    pipeCount++;
                                                    if (pipeCount == c + 1) p1 = k;
                                                    else if (pipeCount == c + 2) { p2 = k; break; }
                                                }
                                            }
                                            if (p1 >= 0)
                                            {
                                                if (p2 < 0) p2 = lineStr.Length;
                                                int rawStart = p1 + 1;
                                                int rawLen = Math.Max(0, p2 - rawStart);
                                                string rawSub = lineStr.Substring(rawStart, rawLen);

                                                int lead = 0;
                                                while (lead < rawSub.Length && rawSub[lead] == ' ') lead++;
                                                int trail = 0;
                                                while (trail < rawSub.Length - lead && rawSub[rawSub.Length - 1 - trail] == ' ') trail++;
                                                int cLen = Math.Max(0, rawSub.Length - lead - trail);

                                                cellContentGlobalStart = rowLineStart + rawStart + lead;
                                                cellContentGlobalLen = cLen;
                                            }
                                        }

                                        // Register TableCellHit for accurate mouse hit detection
                                        if (cellContentGlobalStart >= 0)
                                        {
                                            TableCellHits.Add(new TableCellHit
                                            {
                                                CellRect = cellRect,
                                                TextRect = txtRect,
                                                TableIndex = tblIdx,
                                                RowIndex = r,
                                                ColIndex = c,
                                                CharStartIndex = cellContentGlobalStart,
                                                CharLength = cellContentGlobalLen,
                                                CellText = cellTxt,
                                                CellFont = fToUse,
                                                Alignment = hAlign,
                                                LineAlignment = vAlign
                                            });
                                        }

                                        // 4. Calculate Vertical Alignment Start Y (Top, Center, Bottom)
                                        float cellContentStartY = txtRect.Y;
                                        if (cellData != null && cellData.Paragraphs != null && cellData.Paragraphs.Count > 0)
                                        {
                                            float totalCellContentH = 0;
                                            for (int pi = 0; pi < cellData.Paragraphs.Count; pi++)
                                            {
                                                var cp = cellData.Paragraphs[pi];
                                                if (pi > 0 && cp.SpacingBeforePt > 0) totalCellContentH += cp.SpacingBeforePt * 1.333333f * ZoomLevel;

                                                string shpId, shpTp, shpImg, remTxt;
                                                int tagW, tagH;
                                                if (TryParseCellShape(cp.Text, out shpId, out shpTp, out shpImg, out tagW, out tagH, out remTxt))
                                                {
                                                    if (!string.IsNullOrEmpty(shpImg))
                                                    {
                                                        float maxW = Math.Max(20f, txtRect.Width);
                                                        float imgW = (tagW > 0 ? tagW : 240) * ZoomLevel;
                                                        float imgH = (tagH > 0 ? tagH : 180) * ZoomLevel;
                                                        if (imgW > maxW && imgW > 0) { float ratio = maxW / imgW; imgW = maxW; imgH = imgH * ratio; }
                                                        totalCellContentH += imgH + 4.0f * ZoomLevel;
                                                    }
                                                }

                                                float pSize = (cp.FontSize > 0 ? cp.FontSize : 11.0f) * ZoomLevel;
                                                FontStyle pStyle = FontStyle.Regular;
                                                if (cp.Bold) pStyle |= FontStyle.Bold;
                                                if (cp.Italic) pStyle |= FontStyle.Italic;
                                                Font pFont = GetCachedFont(cp.FontName ?? "Times New Roman", pSize, pStyle);
                                                var pLines = BreakCellTextIntoLines(g, cp.Text ?? "", pFont, txtRect.Width);
                                                float lineH = pFont.GetHeight(g) * (cp.LineSpacing > 0 ? cp.LineSpacing : 1.15f);
                                                if (lineH <= 0) lineH = pSize * 1.35f;
                                                totalCellContentH += pLines.Count * lineH;
                                                if (cp.SpacingAfterPt > 0) totalCellContentH += cp.SpacingAfterPt * 1.333333f * ZoomLevel;
                                            }

                                            if (vAlign == StringAlignment.Center && txtRect.Height > totalCellContentH)
                                            {
                                                cellContentStartY = txtRect.Y + (txtRect.Height - totalCellContentH) / 2.0f;
                                            }
                                            else if (vAlign == StringAlignment.Far && txtRect.Height > totalCellContentH)
                                            {
                                                cellContentStartY = txtRect.Y + (txtRect.Height - totalCellContentH);
                                            }
                                        }
                                        else if (!string.IsNullOrEmpty(cellTxt))
                                        {
                                            float lineH = fToUse.GetHeight(g);
                                            if (vAlign == StringAlignment.Center && txtRect.Height > lineH)
                                                cellContentStartY = txtRect.Y + (txtRect.Height - lineH) / 2.0f;
                                            else if (vAlign == StringAlignment.Far && txtRect.Height > lineH)
                                                cellContentStartY = txtRect.Y + (txtRect.Height - lineH);
                                        }

                                        // 5. Render Cell Text and Selection Highlights (MS Word #C6C6C6)
                                        if (cellData != null && cellData.Paragraphs != null && cellData.Paragraphs.Count > 0)
                                        {
                                            float curParaY = cellContentStartY;
                                            int runningChars = 0;
                                            for (int pi = 0; pi < cellData.Paragraphs.Count; pi++)
                                            {
                                                var cellPara = cellData.Paragraphs[pi];
                                                if (pi > 0 && cellPara.SpacingBeforePt > 0)
                                                {
                                                    curParaY += cellPara.SpacingBeforePt * 1.333333f * ZoomLevel;
                                                }

                                                FontStyle pStyle = FontStyle.Regular;
                                                if (cellPara.Bold) pStyle |= FontStyle.Bold;
                                                if (cellPara.Italic) pStyle |= FontStyle.Italic;

                                                float pSize = (cellPara.FontSize > 0 ? cellPara.FontSize : 11.0f) * ZoomLevel;
                                                Font pFont = GetCachedFont(cellPara.FontName ?? "Times New Roman", pSize, pStyle);
                                                Brush pBrush = tBrush;
                                                if (cellPara.TextColor != Color.Transparent && cellPara.TextColor != Color.Empty && cellPara.TextColor != Color.Black)
                                                {
                                                    pBrush = new SolidBrush(cellPara.TextColor);
                                                }

                                                string shpId, shpTp, shpImg, remTxt;
                                                int tagW, tagH;
                                                bool hasCellShape = TryParseCellShape(cellPara.Text, out shpId, out shpTp, out shpImg, out tagW, out tagH, out remTxt);
                                                if (hasCellShape && !string.IsNullOrEmpty(shpImg))
                                                {
                                                    try
                                                    {
                                                        Image cellImg = DocShapeObject.LoadOptimizedImage(shpImg);
                                                        if (cellImg != null)
                                                        {
                                                            float maxW = Math.Max(20f, txtRect.Width);
                                                            float imgW = (tagW > 0 ? tagW : 240) * ZoomLevel;
                                                            float imgH = (tagH > 0 ? tagH : 180) * ZoomLevel;
                                                            if (imgW > maxW && imgW > 0)
                                                            {
                                                                float ratio = maxW / imgW;
                                                                imgW = maxW;
                                                                imgH = imgH * ratio;
                                                            }
                                                            float imgX = txtRect.X;
                                                            int shpAlign = (cellPara.Alignment != 0) ? cellPara.Alignment : (cellData != null ? cellData.Alignment : 0);
                                                            if (shpAlign == 0)
                                                            {
                                                                if (hAlign == StringAlignment.Center) shpAlign = 1;
                                                                else if (hAlign == StringAlignment.Far) shpAlign = 2;
                                                            }
                                                            if (shpAlign == 1) imgX = txtRect.X + Math.Max(0, (txtRect.Width - imgW) / 2.0f);
                                                            else if (shpAlign == 2) imgX = txtRect.X + Math.Max(0, txtRect.Width - imgW);

                                                            g.DrawImage(cellImg, imgX, curParaY, imgW, imgH);
                                                            curParaY += imgH + 4.0f * ZoomLevel;
                                                        }
                                                    }
                                                    catch { }
                                                }

                                                string txtToRender = hasCellShape ? remTxt : (cellPara.Text ?? "");
                                                if (!string.IsNullOrEmpty(txtToRender))
                                                {
                                                    var pLines = BreakCellTextIntoLines(g, txtToRender, pFont, txtRect.Width);
                                                    float lineH = pFont.GetHeight(g) * (cellPara.LineSpacing > 0 ? cellPara.LineSpacing : 1.15f);
                                                    if (lineH <= 0) lineH = pSize * 1.35f;

                                                    for (int li = 0; li < pLines.Count; li++)
                                                    {
                                                        var line = pLines[li];
                                                        if (string.IsNullOrEmpty(line.Text)) continue;
                                                        bool isLastLine = (li == pLines.Count - 1);
                                                        int align = (cellPara.Alignment != 0) ? cellPara.Alignment : (cellData != null ? cellData.Alignment : 0);
                                                        if (align == 0)
                                                        {
                                                            if (hAlign == StringAlignment.Center) align = 1;
                                                            else if (hAlign == StringAlignment.Far) align = 2;
                                                        }

                                                        float lineX = txtRect.X;
                                                        if (align == 1)
                                                        {
                                                            lineX = txtRect.X + Math.Max(0, (txtRect.Width - line.Width) / 2.0f);
                                                        }
                                                        else if (align == 2)
                                                        {
                                                            lineX = txtRect.X + Math.Max(0, txtRect.Width - line.Width);
                                                        }

                                                        float spaceW = 0;
                                                        bool isJustified = (align == 3 && !isLastLine);
                                                        if (isJustified)
                                                        {
                                                            string tStr = line.Text.TrimEnd();
                                                            string[] words = tStr.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
                                                            int spaceCount = words.Length - 1;
                                                            if (spaceCount > 0)
                                                            {
                                                                float wordsTotalW = 0;
                                                                foreach (var w in words)
                                                                {
                                                                    wordsTotalW += g.MeasureString(w, pFont, Point.Empty, SafeStringFormat).Width;
                                                                }
                                                                float totalSpaceAvail = txtRect.Width - wordsTotalW;
                                                                float sW = totalSpaceAvail / spaceCount;
                                                                if (sW > 0 && sW <= 24.0f * ZoomLevel)
                                                                {
                                                                    spaceW = sW;
                                                                }
                                                            }
                                                        }

                                                        // MS Word In-Cell Text Selection Highlight Box (#C6C6C6)
                                                        if (hasSelection && cellContentGlobalStart >= 0)
                                                        {
                                                            int lineGlobalStart = cellContentGlobalStart + runningChars + line.StartIndex;
                                                            int lineGlobalEnd = lineGlobalStart + line.Length;
                                                            bool lineHasSel = (line.Length > 0 && selMax > lineGlobalStart && selMin < lineGlobalEnd) ||
                                                                              (line.Length == 0 && selMax > lineGlobalStart && selMin <= lineGlobalStart);
                                                            if (lineHasSel)
                                                            {
                                                                int sIdx = (line.Length > 0) ? Math.Max(0, Math.Min(line.Length, selMin - lineGlobalStart)) : 0;
                                                                int eIdx = (line.Length > 0) ? Math.Max(0, Math.Min(line.Length, selMax - lineGlobalStart)) : 0;

                                                                float preW = (sIdx > 0 && line.Length > 0) ? MeasureInCellLinePrefixWidth(g, line.Text, sIdx, pFont, spaceW) : 0f;
                                                                float postW = (eIdx > 0 && line.Length > 0) ? MeasureInCellLinePrefixWidth(g, line.Text, eIdx, pFont, spaceW) : 0f;
                                                                float selW = postW - preW;

                                                                if (selMax > lineGlobalEnd)
                                                                {
                                                                    selW += (float)Math.Round(5.0f * ZoomLevel);
                                                                }

                                                                if (selW < 4.0f * ZoomLevel && (selMax > lineGlobalStart || line.Length == 0))
                                                                {
                                                                    selW = 4.0f * ZoomLevel;
                                                                }

                                                                float selX = (float)Math.Round(lineX + preW);
                                                                float selY = (float)Math.Round(curParaY);
                                                                float selH = (float)Math.Round(lineH);

                                                                SmoothingMode prevSmooth = g.SmoothingMode;
                                                                g.SmoothingMode = SmoothingMode.None;
                                                                using (SolidBrush sBrush = new SolidBrush(Color.FromArgb(198, 198, 198)))
                                                                {
                                                                    g.FillRectangle(sBrush, selX, selY, (float)Math.Round(selW), selH);
                                                                }
                                                                g.SmoothingMode = prevSmooth;
                                                            }
                                                        }

                                                        if (align == 3 && !isLastLine && spaceW > 0)
                                                        {
                                                            string tStr = line.Text.TrimEnd();
                                                            string[] words = tStr.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
                                                            float wx = txtRect.X;
                                                            for (int wi = 0; wi < words.Length; wi++)
                                                            {
                                                                DrawTextOrColorSymbols(g, words[wi], pFont, pBrush, (float)Math.Round(wx), (float)Math.Round(curParaY), ZoomLevel);
                                                                float ww = g.MeasureString(words[wi], pFont, Point.Empty, SafeStringFormat).Width;
                                                                wx += ww + spaceW;
                                                            }
                                                        }
                                                        else
                                                        {
                                                            DrawTextOrColorSymbols(g, line.Text, pFont, pBrush, (float)Math.Round(lineX), (float)Math.Round(curParaY), ZoomLevel);
                                                        }

                                                        curParaY += lineH;
                                                    }
                                                }

                                                if (cellPara.SpacingAfterPt > 0)
                                                {
                                                    curParaY += cellPara.SpacingAfterPt * 1.333333f * ZoomLevel;
                                                }
                                                runningChars += (cellPara.Text != null ? cellPara.Text.Length : 0) + 1;
                                            }
                                        }
                                        else if (!string.IsNullOrEmpty(cellTxt))
                                        {
                                            float textY = cellContentStartY;
                                            string shpId, shpTp, shpImg, remTxt;
                                            int tagW, tagH;
                                            bool hasCellShape = TryParseCellShape(cellTxt, out shpId, out shpTp, out shpImg, out tagW, out tagH, out remTxt);
                                            if (hasCellShape && !string.IsNullOrEmpty(shpImg))
                                            {
                                                try
                                                {
                                                    Image cellImg = DocShapeObject.LoadOptimizedImage(shpImg);
                                                    if (cellImg != null)
                                                    {
                                                        float maxW = Math.Max(20f, txtRect.Width);
                                                        float imgW = (tagW > 0 ? tagW : 240) * ZoomLevel;
                                                        float imgH = (tagH > 0 ? tagH : 180) * ZoomLevel;
                                                        if (imgW > maxW && imgW > 0)
                                                        {
                                                            float ratio = maxW / imgW;
                                                            imgW = maxW;
                                                            imgH = imgH * ratio;
                                                        }
                                                        float imgX = txtRect.X;
                                                        if (hAlign == StringAlignment.Center) imgX = txtRect.X + Math.Max(0, (txtRect.Width - imgW) / 2.0f);
                                                        else if (hAlign == StringAlignment.Far) imgX = txtRect.X + Math.Max(0, txtRect.Width - imgW);

                                                        g.DrawImage(cellImg, imgX, textY, imgW, imgH);
                                                        textY += imgH + 4.0f * ZoomLevel;
                                                    }
                                                }
                                                catch { }
                                            }

                                            string txtToRender = hasCellShape ? remTxt : cellTxt;
                                            if (!string.IsNullOrEmpty(txtToRender))
                                            {
                                                float lineH = fToUse.GetHeight(g);
                                                var pLines = BreakCellTextIntoLines(g, txtToRender, fToUse, txtRect.Width);
                                                for (int li = 0; li < pLines.Count; li++)
                                                {
                                                    var line = pLines[li];
                                                    if (string.IsNullOrEmpty(line.Text)) continue;
                                                    float lineX = txtRect.X;
                                                    if (hAlign == StringAlignment.Center) lineX = txtRect.X + Math.Max(0, (txtRect.Width - line.Width) / 2f);
                                                    else if (hAlign == StringAlignment.Far) lineX = txtRect.X + Math.Max(0, txtRect.Width - line.Width);

                                                    // In-Cell selection for single string cell
                                                    if (hasSelection && cellContentGlobalStart >= 0)
                                                    {
                                                        int lineGlobalStart = cellContentGlobalStart + line.StartIndex;
                                                        int lineGlobalEnd = lineGlobalStart + line.Length;
                                                        if (selMax > lineGlobalStart && selMin < lineGlobalEnd)
                                                        {
                                                            int sIdx = Math.Max(0, Math.Min(line.Length, selMin - lineGlobalStart));
                                                            int eIdx = Math.Max(0, Math.Min(line.Length, selMax - lineGlobalStart));
                                                            float preW = (sIdx > 0) ? g.MeasureString(line.Text.Substring(0, sIdx), fToUse, Point.Empty, SafeStringFormat).Width : 0f;
                                                            float postW = g.MeasureString(line.Text.Substring(0, eIdx), fToUse, Point.Empty, SafeStringFormat).Width;
                                                            float selW = postW - preW;
                                                            if (selMax > lineGlobalEnd) selW += 5.0f * ZoomLevel;

                                                            SmoothingMode prevSmooth = g.SmoothingMode;
                                                            g.SmoothingMode = SmoothingMode.None;
                                                            using (SolidBrush sBrush = new SolidBrush(Color.FromArgb(198, 198, 198)))
                                                            {
                                                                g.FillRectangle(sBrush, (float)Math.Round(lineX + preW), (float)Math.Round(textY), (float)Math.Round(selW), (float)Math.Round(lineH));
                                                            }
                                                            g.SmoothingMode = prevSmooth;
                                                        }
                                                    }

                                                    DrawTextOrColorSymbols(g, line.Text, fToUse, tBrush, (float)Math.Round(lineX), (float)Math.Round(textY), ZoomLevel);
                                                    textY += lineH;
                                                }
                                            }
                                        }

                                        // 6. Accurate In-Cell Caret Position (cursorX, cursorY, cursorH)
                                        if (CursorPosition >= cellContentGlobalStart && CursorPosition <= cellContentGlobalStart + cellContentGlobalLen)
                                        {
                                            if (cellData != null && cellData.Paragraphs != null && cellData.Paragraphs.Count > 0)
                                            {
                                                int offInCell = Math.Max(0, Math.Min(CursorPosition - cellContentGlobalStart, cellContentGlobalLen));
                                                float curCaretY = cellContentStartY;
                                                int runningCaretChars = 0;
                                                bool placed = false;

                                                for (int pi = 0; pi < cellData.Paragraphs.Count; pi++)
                                                {
                                                    var cp = cellData.Paragraphs[pi];
                                                    if (pi > 0 && cp.SpacingBeforePt > 0)
                                                    {
                                                        curCaretY += cp.SpacingBeforePt * 1.333333f * ZoomLevel;
                                                    }

                                                    string cPShpId, cPShpTp, cPShpImg, cPRemTxt;
                                                    int cPTagW, cPTagH;
                                                    bool cPHasShp = TryParseCellShape(cp.Text, out cPShpId, out cPShpTp, out cPShpImg, out cPTagW, out cPTagH, out cPRemTxt);
                                                    if (cPHasShp && !string.IsNullOrEmpty(cPShpImg))
                                                    {
                                                        float maxW = Math.Max(20f, txtRect.Width);
                                                        float imgW = (cPTagW > 0 ? cPTagW : 240) * ZoomLevel;
                                                        float imgH = (cPTagH > 0 ? cPTagH : 180) * ZoomLevel;
                                                        if (imgW > maxW && imgW > 0)
                                                        {
                                                            float ratio = maxW / imgW;
                                                            imgW = maxW;
                                                            imgH = imgH * ratio;
                                                        }
                                                        curCaretY += imgH + 4.0f * ZoomLevel;
                                                    }

                                                    float pSize = (cp.FontSize > 0 ? cp.FontSize : 11.0f) * ZoomLevel;
                                                    FontStyle pStyle = FontStyle.Regular;
                                                    if (cp.Bold) pStyle |= FontStyle.Bold;
                                                    if (cp.Italic) pStyle |= FontStyle.Italic;
                                                    Font pFont = GetCachedFont(cp.FontName ?? "Times New Roman", pSize, pStyle);

                                                    string pText = cPHasShp ? cPRemTxt : (cp.Text ?? "");
                                                    int pLen = pText.Length;
                                                    var pLines = BreakCellTextIntoLines(g, pText, pFont, txtRect.Width);
                                                    float lineH = pFont.GetHeight(g) * (cp.LineSpacing > 0 ? cp.LineSpacing : 1.15f);
                                                    if (lineH <= 0) lineH = pSize * 1.35f;

                                                    if (!placed && (offInCell <= runningCaretChars + pLen || pi == cellData.Paragraphs.Count - 1))
                                                    {
                                                        int offInPara = Math.Max(0, Math.Min(offInCell - runningCaretChars, pLen));
                                                        int targetLineIdx = Math.Max(0, pLines.Count - 1);
                                                        for (int li = 0; li < pLines.Count; li++)
                                                        {
                                                            var l = pLines[li];
                                                            if (offInPara < l.StartIndex + l.Length || li == pLines.Count - 1)
                                                            {
                                                                targetLineIdx = li;
                                                                break;
                                                            }
                                                        }

                                                        if (targetLineIdx >= 0 && targetLineIdx < pLines.Count)
                                                        {
                                                            var targetLine = pLines[targetLineIdx];
                                                            float lineX = txtRect.X;
                                                            int cpAlign = (cp.Alignment != 0) ? cp.Alignment : (cellData != null ? cellData.Alignment : 0);
                                                            if (cpAlign == 0)
                                                            {
                                                                if (hAlign == StringAlignment.Center) cpAlign = 1;
                                                                else if (hAlign == StringAlignment.Far) cpAlign = 2;
                                                            }
                                                            if (cpAlign == 1)
                                                                lineX = txtRect.X + Math.Max(0, (txtRect.Width - targetLine.Width) / 2.0f);
                                                            else if (cpAlign == 2)
                                                                lineX = txtRect.X + Math.Max(0, txtRect.Width - targetLine.Width);

                                                            float spaceW = 0;
                                                            bool isJustified = (cp.Alignment == 3 && targetLineIdx < pLines.Count - 1);
                                                            if (isJustified)
                                                            {
                                                                string tStr = targetLine.Text.TrimEnd();
                                                                string[] words = tStr.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
                                                                int spaceCount = words.Length - 1;
                                                                if (spaceCount > 0)
                                                                {
                                                                    float wordsTotalW = 0;
                                                                    foreach (var w in words)
                                                                    {
                                                                        wordsTotalW += g.MeasureString(w, pFont, Point.Empty, SafeStringFormat).Width;
                                                                    }
                                                                    float totalSpaceAvail = txtRect.Width - wordsTotalW;
                                                                    float sW = totalSpaceAvail / spaceCount;
                                                                    if (sW > 0 && sW <= 24.0f * ZoomLevel)
                                                                    {
                                                                        spaceW = sW;
                                                                    }
                                                                }
                                                            }

                                                            int offInLine = Math.Max(0, Math.Min(offInPara - targetLine.StartIndex, targetLine.Length));
                                                            float preW = (offInLine > 0) ? MeasureInCellLinePrefixWidth(g, targetLine.Text, offInLine, pFont, spaceW) : 0f;

                                                            cursorX = (int)Math.Round(lineX + preW);
                                                            cursorY = (int)Math.Round(curCaretY + targetLineIdx * lineH + 1.0f * ZoomLevel);
                                                            cursorH = (int)Math.Round(Math.Max(12f * ZoomLevel, lineH - 2.0f * ZoomLevel));
                                                            placed = true;
                                                        }
                                                    }

                                                    curCaretY += pLines.Count * lineH;
                                                    if (cp.SpacingAfterPt > 0)
                                                    {
                                                        curCaretY += cp.SpacingAfterPt * 1.333333f * ZoomLevel;
                                                    }
                                                    runningCaretChars += pLen + 1;
                                                }
                                            }
                                            else
                                            {
                                                string cShpId, cShpTp, cShpImg, cRemTxt;
                                                int cTagW, cTagH;
                                                bool cHasShp = TryParseCellShape(cellTxt, out cShpId, out cShpTp, out cShpImg, out cTagW, out cTagH, out cRemTxt);
                                                float yStart = cellContentStartY;
                                                if (cHasShp && !string.IsNullOrEmpty(cShpImg))
                                                {
                                                    float maxW = Math.Max(20f, txtRect.Width);
                                                    float imgW = (cTagW > 0 ? cTagW : 240) * ZoomLevel;
                                                    float imgH = (cTagH > 0 ? cTagH : 180) * ZoomLevel;
                                                    if (imgW > maxW && imgW > 0)
                                                    {
                                                        float ratio = maxW / imgW;
                                                        imgW = maxW;
                                                        imgH = imgH * ratio;
                                                    }
                                                    yStart += imgH + 4.0f * ZoomLevel;
                                                }
                                                string cTxtToUse = cHasShp ? cRemTxt : cellTxt;

                                                var cellLines = BreakCellTextIntoLines(g, cTxtToUse, fToUse, txtRect.Width);
                                                float lineH = fToUse.GetHeight(g);
                                                if (lineH <= 0) lineH = 16f;

                                                int offInCell = Math.Max(0, Math.Min(CursorPosition - cellContentGlobalStart, cTxtToUse.Length));
                                                int targetLineIdx = Math.Max(0, cellLines.Count - 1);
                                                for (int li = 0; li < cellLines.Count; li++)
                                                {
                                                    var l = cellLines[li];
                                                    if (offInCell <= l.StartIndex + l.Length)
                                                    {
                                                        targetLineIdx = li;
                                                        break;
                                                    }
                                                }

                                                if (targetLineIdx >= 0 && targetLineIdx < cellLines.Count)
                                                {
                                                    var targetLine = cellLines[targetLineIdx];
                                                    float lineX = txtRect.X;
                                                    if (hAlign == StringAlignment.Center)
                                                        lineX = txtRect.X + Math.Max(0, (txtRect.Width - targetLine.Width) / 2f);
                                                    else if (hAlign == StringAlignment.Far)
                                                        lineX = txtRect.X + Math.Max(0, txtRect.Width - targetLine.Width);

                                                    int offInLine = Math.Max(0, Math.Min(offInCell - targetLine.StartIndex, targetLine.Length));
                                                    string preStr = (offInLine > 0 && offInLine <= targetLine.Text.Length) ? targetLine.Text.Substring(0, offInLine) : "";
                                                    float preW = (offInLine > 0) ? g.MeasureString(preStr, fToUse, Point.Empty, SafeStringFormat).Width : 0f;

                                                    cursorX = (int)Math.Round(lineX + preW);
                                                    cursorY = (int)Math.Round(yStart + targetLineIdx * lineH + 1.0f * ZoomLevel);
                                                    cursorH = (int)Math.Round(Math.Max(12f * ZoomLevel, lineH - 2.0f * ZoomLevel));
                                                }
                                            }
                                        }
                                    }
                                }
                            }

                            // Draw Table Layout Options Floating Button (Top-Right) and Resize Handle (Bottom-Right) ONLY when hovered, selected or dragged
                            Rectangle wrapBtnRect = new Rectangle(tableX + tableW + 6, tableY, 22, 22);
                            TableWrapBtnHits.Add(new TableWrapBtnHit { Rect = wrapBtnRect, TableIndex = tblIdx });
                            bool isWrapOpen = (ActiveTableLayoutOptionsIndex == tblIdx);
                            if (isTableHoveredOrActive)
                            {
                                using (SolidBrush btnBg = new SolidBrush(isWrapOpen ? Color.FromArgb(215, 235, 255) : Color.White))
                                using (Pen btnBorder = new Pen(isWrapOpen ? Color.FromArgb(0, 120, 215) : Color.FromArgb(180, 180, 180), 1))
                                {
                                    g.FillRectangle(btnBg, wrapBtnRect);
                                    g.DrawRectangle(btnBorder, wrapBtnRect);
                                }
                                using (Pen archPen = new Pen(Color.FromArgb(0, 102, 204), 2.2f))
                                using (Pen linePen = new Pen(Color.FromArgb(0, 120, 215), 1.4f))
                                {
                                    g.DrawLine(linePen, wrapBtnRect.X + 4, wrapBtnRect.Y + 5, wrapBtnRect.X + 18, wrapBtnRect.Y + 5);
                                    ShapeRenderer.DrawVectorArch(g, archPen, wrapBtnRect.X + 5, wrapBtnRect.Y + 8, 12, 10);
                                    g.DrawLine(linePen, wrapBtnRect.X + 4, wrapBtnRect.Y + 18, wrapBtnRect.X + 18, wrapBtnRect.Y + 18);
                                }

                                // Draw Resize Handle (Bottom-Right)
                                int handleSz = (int)(9.0f * ZoomLevel);
                                Rectangle handleRect = new Rectangle(tableX + tableW - handleSz / 2, tableY + tableH - handleSz / 2, handleSz, handleSz);
                                using (SolidBrush hBrush = new SolidBrush(Color.White))
                                using (Pen handlePen = new Pen(Color.FromArgb(0, 102, 204), 1.5f))
                                {
                                    g.FillRectangle(hBrush, handleRect);
                                    g.DrawRectangle(handlePen, handleRect);
                                }
                            }

                            // Text Flow: In-Line table advances currentY, Wrap Around table lets text flow around it
                            if (tWrap == 0)
                            {
                                currentY = tableY + tableH + (int)(3 * ZoomLevel);
                                // Track gap AFTER this table
                                DocParagraphGaps.Add(new ParagraphGap { ScreenY = (int)Math.Round(currentY), CharIndex = paraStartIndex + tblTotalLen, VirtualEntersNeeded = 0 });
                            }
                            else
                            {
                                // Wrap Around (Floating): text flow continues from inline position before table, wrapping around TableFloatingBounds
                                currentY = inlineYBeforeTable;
                            }
                            paraStartIndex += tblTotalLen;
                            continue;
                        }
                    }

                    var wrappedLines = LayoutParagraphLines(para, paraStartIndex, ref currentY, ref currentPage, startPageY, pageH, marginY, bottomMarginY, textX, maxTextW, g, ribbon);

                    // Render Drop Cap letter if enabled on this paragraph
                    if (ParagraphDropCaps.ContainsKey(paraStartIndex) && wrappedLines.Count > 0 && !string.IsNullOrEmpty(para))
                    {
                        DropCapInfo dcInfo = ParagraphDropCaps[paraStartIndex];
                        if (dcInfo != null && dcInfo.Lines > 1)
                        {
                            char dcChar = para[0];
                            float baseFS = TypingFontSize;
                            if (FormattedRuns != null && FormattedRuns.Count > 0)
                            {
                                for (int ri = 0; ri < FormattedRuns.Count; ri++)
                                {
                                    if (FormattedRuns[ri].StartIndex <= paraStartIndex && FormattedRuns[ri].StartIndex + FormattedRuns[ri].Length >= paraStartIndex)
                                    {
                                        if (FormattedRuns[ri].FontSize > 0) { baseFS = FormattedRuns[ri].FontSize; break; }
                                    }
                                }
                            }
                            float dcFS = baseFS * (dcInfo.Lines - 0.2f) * ZoomLevel;
                            float dcLetterW = (MeasureSubstringWidth(g, dcChar.ToString(), paraStartIndex, 0, 1) * (dcInfo.Lines - 0.2f) + 8f) * ZoomLevel;
                            float dcDrawX = dcInfo.InMargin ? (textX - dcLetterW) : textX;
                            float dcDrawY = wrappedLines[0].LineY;

                            using (Font dcFont = new Font("Segoe UI", Math.Max(18f, dcFS), FontStyle.Bold))
                            using (SolidBrush dcBrush = new SolidBrush(Color.FromArgb(15, 23, 42)))
                            {
                                g.DrawString(dcChar.ToString(), dcFont, dcBrush, dcDrawX, dcDrawY);
                            }
                        }
                    }

                    for (int lIdx = 0; lIdx < wrappedLines.Count; lIdx++)
                    {
                        var line = wrappedLines[lIdx];
                        float dynamicLineHeight = line.LineHeight;
                        float effLineY = (ViewMode == 0) ? (line.LineY - ReadModePageIndex * (pageH + 30)) : line.LineY;
                        bool isLineVisible = (ViewMode == 0)
                            ? (effLineY + dynamicLineHeight >= startPageY - 10 && effLineY <= startPageY + pageH + 10)
                            : (effLineY + dynamicLineHeight >= 155 && effLineY <= height - 26);
                        bool hasCursor = (CursorPosition >= line.StartIndex && CursorPosition <= line.StartIndex + line.Length);

                        docLineNumber++;
                        int linePage = Math.Max(0, (int)((line.LineY - startPageY) / (pageH + 30)));
                        if (linePage != lastLinePage)
                        {
                            lastLinePage = linePage;
                            pageLineNumber = 0;
                        }
                        pageLineNumber++;

                        LineNumberingMode effLineMode = (ribbon != null && ribbon.LineNumberMode != LineNumberingMode.None) ? ribbon.LineNumberMode : LineNumberMode;
                        if (effLineMode != LineNumberingMode.None && isLineVisible)
                        {
                            int displayNum = (effLineMode == LineNumberingMode.RestartEachPage) ? pageLineNumber :
                                             ((effLineMode == LineNumberingMode.RestartEachSection) ? (lIdx + 1) : docLineNumber);
                            float lnFontSize = Math.Max(6.5f, Math.Min(9.0f, line.MaxFontSize * 0.7f)) * ZoomLevel;
                            using (Font lnFont = new Font("Segoe UI", lnFontSize, FontStyle.Regular))
                            using (SolidBrush lnBrush = new SolidBrush(Color.FromArgb(148, 163, 184)))
                            {
                                string numStr = displayNum.ToString();
                                SizeF lnSz = g.MeasureString(numStr, lnFont);
                                float lnX = textX - lnSz.Width - (12.0f * ZoomLevel);
                                g.DrawString(numStr, lnFont, lnBrush, lnX, line.LineY);
                            }
                        }

                        if (!isLineVisible && !hasCursor) continue;

                        float lineStartX = line.StartX;

                        // Calculate Alignment Shift (Left, Center, Right) within available line width
                        float lineW = line.MeasuredWidth > 0 ? line.MeasuredWidth : MeasureSubstringWidth(g, line.Text, line.StartIndex, 0, line.Text.Length);
                        int pAlign = 0;
                        if (ParagraphAlignments.ContainsKey(paraStartIndex))
                        {
                            pAlign = ParagraphAlignments[paraStartIndex];
                        }

                        if (pAlign == 1) // Center
                        {
                            lineStartX = line.StartX + Math.Max(0, (line.Width - lineW) / 2.0f);
                        }
                        else if (pAlign == 2) // Align Right
                        {
                            lineStartX = line.StartX + Math.Max(0, line.Width - lineW);
                        }
                        // Snap to whole pixel to eliminate horizontal GDI jitter on zoom
                        lineStartX = (float)Math.Round(lineStartX);

                        float extraSpaceW = 0;
                        if (pAlign == 3 && !line.IsLastInPara) // Justify
                        {
                            string tStr = line.Text.TrimEnd();
                            int spaceCount = tStr.Split(' ').Length - 1;
                            if (spaceCount > 0 && line.Width > lineW)
                            {
                                float candidate = (line.Width - lineW) / (float)spaceCount;
                                if (candidate <= 16.0f * ZoomLevel && lineW >= line.Width * 0.60f)
                                {
                                    extraSpaceW = candidate;
                                }
                            }
                        }

                        float pLineSpacing = ribbon != null ? ribbon.LineSpacingFactor : 1.15f;
                        if (ParagraphLineSpacings.ContainsKey(paraStartIndex)) pLineSpacing = ParagraphLineSpacings[paraStartIndex];
                        float fontRatio = GetFontLineSpacingRatio(TypingFont);
                        int textLineHeight = (int)(Math.Max(13.5f * ZoomLevel, line.MaxFontSize * 1.333333f * fontRatio * ZoomLevel) * pLineSpacing);
                        
                        float yTextOffset = 0;
                        bool lineHasShape = line.Text.IndexOf("![IMAGE:") >= 0 || line.Text.IndexOf("![SHAPE:") >= 0;
                        if (lineHasShape && dynamicLineHeight > textLineHeight)
                        {
                            yTextOffset = dynamicLineHeight - 4 * ZoomLevel - (line.MaxFontSize * 1.45f * ZoomLevel);
                            if (yTextOffset < 0) yTextOffset = 0;
                        }

                        // Microsoft Word Modern Sleek Neutral Selection Highlight (#C6C6C6)
                        bool lineHasSel = hasSelection && isLineVisible && (
                            (line.Length > 0 && selMax > line.StartIndex && selMin < line.StartIndex + line.Length) ||
                            (line.Length == 0 && selMax > line.StartIndex && selMin <= line.StartIndex)
                        );
                        if (lineHasSel)
                        {
                            int sIdx = (line.Length > 0) ? Math.Max(0, Math.Min(line.Length, selMin - line.StartIndex)) : 0;
                            int eIdx = (line.Length > 0) ? Math.Max(0, Math.Min(line.Length, selMax - line.StartIndex)) : 0;

                            float preW = (sIdx > 0 && line.Length > 0) ? MeasureSubstringWidth(g, line.Text, line.StartIndex, 0, sIdx, extraSpaceW) : 0f;
                            float selW = (eIdx > sIdx && line.Length > 0) ? MeasureSubstringWidth(g, line.Text, line.StartIndex, sIdx, eIdx - sIdx, extraSpaceW) : 0f;

                            // Word-style: Trailing selection extension for newline / paragraph break
                            if (selMax > line.StartIndex + line.Length)
                            {
                                selW += (float)Math.Round(6.0f * ZoomLevel);
                            }

                            if (selW < 4.0f * ZoomLevel && (selMax > line.StartIndex || line.Length == 0))
                            {
                                selW = 4.0f * ZoomLevel;
                            }

                            float selX = (float)Math.Round(lineStartX + preW);
                            float selTop = (float)Math.Round(line.LineY);
                            float selBottom = (float)Math.Round(line.LineY + dynamicLineHeight);

                            // Seamless multi-line paragraph block: extend down through paragraph spacing after if selection crosses into next paragraph
                            float pAfter = (ParagraphSpacingsAfter.ContainsKey(paraStartIndex)) ? ParagraphSpacingsAfter[paraStartIndex] : (ribbon != null ? ribbon.ParagraphSpacingAfter : 0f);
                            if (line.IsLastInPara && selMax > line.StartIndex + line.Length && pAfter > 0)
                            {
                                selBottom += (float)Math.Round(pAfter * ZoomLevel);
                            }

                            float selH = Math.Max(1.0f, selBottom - selTop);

                            SmoothingMode prevSmooth = g.SmoothingMode;
                            g.SmoothingMode = SmoothingMode.None;
                            using (SolidBrush sBrush = new SolidBrush(Color.FromArgb(198, 198, 198)))
                            {
                                g.FillRectangle(sBrush, selX, selTop, (float)Math.Round(selW), selH);
                            }
                            g.SmoothingMode = prevSmooth;
                        }

                        // Navigation Pane Search Highlights in Document Text (Word 365 style: Yellow for matches, Gold for active)
                        if (ShowNavigationPane && !string.IsNullOrEmpty(NavSearchQuery) && NavSearchResults.Count > 0 && isLineVisible)
                        {
                            for (int m = 0; m < NavSearchResults.Count; m++)
                            {
                                var match = NavSearchResults[m];
                                int mStart = match.CharIndex;
                                int mEnd = match.CharIndex + match.Length;
                                if (line.Length > 0 && mEnd > line.StartIndex && mStart < line.StartIndex + line.Length)
                                {
                                    int msIdx = Math.Max(0, Math.Min(line.Length, mStart - line.StartIndex));
                                    int meIdx = Math.Max(0, Math.Min(line.Length, mEnd - line.StartIndex));
                                    if (meIdx > msIdx)
                                    {
                                        float mPreW = msIdx > 0 ? MeasureSubstringWidth(g, line.Text, line.StartIndex, 0, msIdx, extraSpaceW) : 0f;
                                        float mMatchW = MeasureSubstringWidth(g, line.Text, line.StartIndex, msIdx, meIdx - msIdx, extraSpaceW);
                                        float mX = (float)Math.Round(lineStartX + mPreW);
                                        float mTop = (float)Math.Round(line.LineY);
                                        float mH = dynamicLineHeight;

                                        bool isActive = (m == NavSearchResultIndex);
                                        Color hlCol = isActive ? Color.FromArgb(200, 255, 179, 0) : Color.FromArgb(170, 255, 235, 59);
                                        using (SolidBrush hlB = new SolidBrush(hlCol))
                                        {
                                            g.FillRectangle(hlB, mX, mTop, mMatchW, mH);
                                        }
                                    }
                                }
                            }
                        }

                        // IDE Diff: Red background highlight behind deleted text
                        if (PendingAiDiffs != null && PendingAiDiffs.Count > 0 && isLineVisible)
                        {
                            for (int d = 0; d < PendingAiDiffs.Count; d++)
                            {
                                var diff = PendingAiDiffs[d];
                                int dStart = diff.CharIndex;
                                int dEnd = diff.CharIndex + diff.OriginalLength;
                                if (line.Length > 0 && dEnd > line.StartIndex && dStart < line.StartIndex + line.Length)
                                {
                                    int dsIdx = Math.Max(0, Math.Min(line.Length, dStart - line.StartIndex));
                                    int deIdx = Math.Max(0, Math.Min(line.Length, dEnd - line.StartIndex));
                                    if (deIdx > dsIdx)
                                    {
                                        float dPreW = dsIdx > 0 ? MeasureSubstringWidth(g, line.Text, line.StartIndex, 0, dsIdx, extraSpaceW) : 0f;
                                        float dMatchW = MeasureSubstringWidth(g, line.Text, line.StartIndex, dsIdx, deIdx - dsIdx, extraSpaceW);
                                        float dX = (float)Math.Round(lineStartX + dPreW);
                                        float dTop = (float)Math.Round(line.LineY);
                                        float dH = dynamicLineHeight;

                                        using (SolidBrush redBg = new SolidBrush(Color.FromArgb(210, 254, 202, 202))) // Pastel red (#FEE2E2)
                                        {
                                            g.FillRectangle(redBg, dX, dTop, dMatchW, dH);
                                        }
                                        using (Pen redBorder = new Pen(Color.FromArgb(239, 68, 68), 1f)) // Red border (#EF4444)
                                        {
                                            g.DrawRectangle(redBorder, dX, dTop, dMatchW, dH);
                                        }
                                    }
                                }
                            }
                        }

                        // Draw line formatted runs
                        float curX = lineStartX;
                        
                        if (isLineVisible || hasCursor)
                        {
                            int i = 0;
                            while (i < line.Text.Length)
                            {
                            // Intercept Shape/Image tags in text stream
                            if (line.Text[i] == '!' && i + 8 <= line.Text.Length && line.Text[i+1] == '[')
                            {
                                string pfx = line.Text.Substring(i, 8);
                                if (pfx == "![IMAGE:" || pfx == "![SHAPE:")
                                {
                                    int endIdx = line.Text.IndexOf(']', i);
                                    if (endIdx > i)
                                    {
                                        string tag = line.Text.Substring(i, endIdx - i + 1);
                                        string shapeId = "", shapeType = "", imgPath = "";
                                        int tX, tY, tW, tH, tWrap, tPage, tStyle, tYRel;
                                        DocShapeObject.ParseShapeTag(tag, out shapeId, out shapeType, out imgPath, out tX, out tY, out tW, out tH, out tWrap, out tPage, out tStyle, out tYRel);
                                        
                                        DocShapeObject shp = GetOrCreateDocShape(string.IsNullOrEmpty(shapeId) ? "Temp" : shapeId, shapeType);
                                        if (!string.IsNullOrEmpty(imgPath))
                                        {
                                            shp.ImagePath = imgPath;
                                            if (shp.CachedImage == null && !DocShapeObject.MissingImagesCache.Contains(imgPath) && System.IO.File.Exists(imgPath))
                                            {
                                                int reqW = tW > 0 ? tW : shp.BaseWidth;
                                                int reqH = tH > 0 ? tH : shp.BaseHeight;
                                                shp.CachedImage = DocShapeObject.LoadOptimizedImage(imgPath, reqW, reqH);
                                            }
                                        }
                                        int sW = Math.Max((int)(20 * ZoomLevel), (int)((shp.BaseWidth + shp.WidthDelta) * ZoomLevel));
                                        int sH = Math.Max((int)(15 * ZoomLevel), (int)((shp.BaseHeight + shp.HeightDelta) * ZoomLevel));
                                        
                                        if (tW > 0 && (shp != ActiveShape || DragShapeHandleIndex < 0)) sW = (int)(tW * ZoomLevel);
                                        if (tH > 0 && (shp != ActiveShape || DragShapeHandleIndex < 0)) sH = (int)(tH * ZoomLevel);

                                        if (isLineVisible && (tWrap == 0 || shp.WrapMode == 0))
                                        {
                                            int shapeY = (int)(line.LineY + line.LineHeight - sH - 2 * ZoomLevel);
                                            if (shp == ActiveShape && DragShapeHandleIndex >= 0 && !ShapeDragStartBounds.IsEmpty)
                                            {
                                                int finalX = (int)curX;
                                                int finalY = shapeY;

                                                // Left handles (7=W, 0=NW, 6=SW): anchor Right edge at ShapeDragStartBounds.Right
                                                if (DragShapeHandleIndex == 7 || DragShapeHandleIndex == 0 || DragShapeHandleIndex == 6)
                                                {
                                                    finalX = ShapeDragStartBounds.Right - sW;
                                                }
                                                else
                                                {
                                                    finalX = ShapeDragStartBounds.Left;
                                                }

                                                // Top handles (1=N, 0=NW, 2=NE): anchor Bottom edge at ShapeDragStartBounds.Bottom
                                                if (DragShapeHandleIndex == 1 || DragShapeHandleIndex == 0 || DragShapeHandleIndex == 2)
                                                {
                                                    finalY = ShapeDragStartBounds.Bottom - sH;
                                                }
                                                else
                                                {
                                                    finalY = ShapeDragStartBounds.Top;
                                                }

                                                shp.LastBounds = new Rectangle(finalX, finalY, sW, sH);
                                            }
                                            else
                                            {
                                                shp.LastBounds = new Rectangle((int)curX, shapeY, sW, sH);
                                            }
                                            ShapeRenderer.DrawShape(g, shp, shp.LastBounds, ribbon, ZoomLevel);
                                        }

                                        if (CursorPosition >= line.StartIndex + i && CursorPosition <= line.StartIndex + i + tag.Length)
                                        {
                                            int offset = CursorPosition - (line.StartIndex + i);
                                            if (offset == 0) cursorX = (int)curX;
                                            else cursorX = (int)(curX + sW);
                                            float textCaretH = (TypingFontSize * 1.45f * ZoomLevel) + 2.0f * ZoomLevel;
                                            cursorY = (int)Math.Round(line.LineY + yTextOffset);
                                            cursorH = (int)Math.Round(textCaretH);
                                        }

                                        curX += sW;
                                        i += tag.Length;
                                        continue;
                                    }
                                }
                            }

                            FormattedRun fmt = GetFormatAt(line.StartIndex + i);
                            int maxRunLen = Math.Min(line.Text.Length - i, Math.Max(1, (fmt.StartIndex + fmt.Length) - (line.StartIndex + i)));
                            int runLen = 1;
                            while (runLen < maxRunLen)
                            {
                                if (line.Text[i + runLen] == '!' && i + runLen + 8 <= line.Text.Length && line.Text[i + runLen + 1] == '[')
                                {
                                    string pfx = line.Text.Substring(i + runLen, 8);
                                    if (pfx == "![IMAGE:" || pfx == "![SHAPE:") break;
                                }
                                runLen++;
                            }

                            string runStr = line.Text.Substring(i, runLen);

                            FontStyle style = FontStyle.Regular;
                            if (fmt.Bold) style |= FontStyle.Bold;
                            if (fmt.Italic) style |= FontStyle.Italic;
                            if (fmt.Underline) style |= FontStyle.Underline;
                            if (fmt.Strike) style |= FontStyle.Strikeout;

                            float effectiveFontSize = fmt.FontSize;
                            bool isSub = fmt.Subscript;
                            bool isSup = fmt.Superscript;
                            float drawY = line.LineY + yTextOffset;

                            if (isSub)
                            {
                                effectiveFontSize = fmt.FontSize * 0.72f;
                                drawY = line.LineY + (line.MaxFontSize * 0.45f * ZoomLevel);
                            }
                            else if (isSup)
                            {
                                effectiveFontSize = fmt.FontSize * 0.72f;
                                drawY = line.LineY - (line.MaxFontSize * 0.12f * ZoomLevel);
                            }
                            else
                            {
                                // Baseline alignment: căn chỉnh chân chữ (baseline) cho các font chữ khác kích thước cùng hàng
                                if (line.MaxFontSize > effectiveFontSize)
                                {
                                    drawY = line.LineY + (line.MaxFontSize - effectiveFontSize) * ZoomLevel * 0.85f;
                                }
                            }
                            // Snap to whole pixel — prevents GDI subpixel vertical jitter on zoom
                            drawY = (float)Math.Round(drawY);

                            Font runFont = GetCachedFont(fmt.FontName, effectiveFontSize * ZoomLevel, style);
                            SizeF runSize = MeasureStringWithTabs(g, runStr, runFont, ZoomLevel);
                            float runW = runSize.Width;

                            if (isLineVisible)
                            {
                                bool runSelected = hasSelection && (selMax > line.StartIndex + i && selMin < line.StartIndex + i + runLen);
                                if (fmt.Highlight != Color.Transparent && !runSelected)
                                {
                                    using (SolidBrush hlBrush = new SolidBrush(fmt.Highlight))
                                    {
                                        float fullRunW = runW;
                                        if (extraSpaceW > 0) fullRunW += (runStr.Split(' ').Length - 1) * extraSpaceW;
                                        g.FillRectangle(hlBrush, (float)Math.Round(curX), (float)Math.Round(drawY), fullRunW, dynamicLineHeight);
                                    }
                                }

                                using (SolidBrush runBrush = new SolidBrush(fmt.Color))
                                {
                                    if (extraSpaceW > 0 && runStr.Contains(" "))
                                    {
                                        float tmpX = curX;
                                        string[] wordParts = runStr.Split(' ');
                                        float spaceW = MeasureStringWithTabs(g, " ", runFont, ZoomLevel).Width;
                                        for (int wp = 0; wp < wordParts.Length; wp++)
                                        {
                                            if (wp > 0)
                                            {
                                                tmpX += spaceW + extraSpaceW;
                                            }
                                            if (wordParts[wp].Length > 0)
                                            {
                                                DrawStringWithTabs(g, wordParts[wp], runFont, runBrush, tmpX, drawY, ZoomLevel);
                                                float wSzW = MeasureStringWithTabs(g, wordParts[wp], runFont, ZoomLevel).Width;
                                                tmpX += wSzW;
                                            }
                                        }
                                    }
                                    else
                                    {
                                        DrawStringWithTabs(g, runStr, runFont, runBrush, curX, drawY, ZoomLevel);
                                    }
                                }
                            }

                            if (CursorPosition >= line.StartIndex + i && CursorPosition <= line.StartIndex + i + runLen)
                            {
                                int offset = CursorPosition - (line.StartIndex + i);
                                string pre = runStr.Substring(0, Math.Min(offset, runStr.Length));
                                float preSzW = MeasureStringWithTabs(g, pre, runFont, ZoomLevel).Width;
                                if (extraSpaceW > 0)
                                {
                                    preSzW += (pre.Split(' ').Length - 1) * extraSpaceW;
                                }
                                cursorX = (int)Math.Round(curX + preSzW);
                                cursorY = (int)(drawY - 1.0f * ZoomLevel);
                                cursorH = (int)((effectiveFontSize * 1.45f * ZoomLevel) + 2.0f * ZoomLevel);
                            }

                            if (extraSpaceW > 0)
                            {
                                runW += (runStr.Split(' ').Length - 1) * extraSpaceW;
                            }
                            curX += runW;
                            i += runLen;
                        }

                            if (CursorPosition == line.StartIndex + line.Length)
                            {
                                cursorX = (int)Math.Round(curX);
                                cursorY = (int)Math.Round(line.LineY + yTextOffset);
                                cursorH = (int)((line.MaxFontSize * 1.45f * ZoomLevel) + 2.0f * ZoomLevel);
                            }

                            if (ShowFormattingMarks && isLineVisible && line.IsLastInPara)
                            {
                                using (Font pilcrowFont = new Font("Segoe UI", Math.Max(8.0f, line.MaxFontSize * 0.9f * ZoomLevel), FontStyle.Regular))
                                using (SolidBrush pilcrowBrush = new SolidBrush(Color.FromArgb(120, 140, 165)))
                                {
                                    g.DrawString("¶", pilcrowFont, pilcrowBrush, curX + 2.0f * ZoomLevel, line.LineY, SafeStringFormat);
                                }
                            }
                        }

                        // Draw Text Borders (Character-level borders for selected text)
                        if (isLineVisible && TextBorders != null && TextBorders.Count > 0)
                        {
                            for (int tbIdx = 0; tbIdx < TextBorders.Count; tbIdx++)
                            {
                                var tb = TextBorders[tbIdx];
                                if (tb == null || !tb.HasAnyBorder) continue;
                                int tbEnd = tb.StartIndex + tb.Length;
                                if (tbEnd <= line.StartIndex || tb.StartIndex >= line.StartIndex + line.Length) continue;

                                int sIdx = Math.Max(line.StartIndex, tb.StartIndex) - line.StartIndex;
                                int eIdx = Math.Min(line.StartIndex + line.Length, tbEnd) - line.StartIndex;
                                if (eIdx <= sIdx) continue;

                                float preW = MeasureSubstringWidth(g, line.Text, line.StartIndex, 0, sIdx, extraSpaceW);
                                float tbW = MeasureSubstringWidth(g, line.Text, line.StartIndex, sIdx, eIdx - sIdx, extraSpaceW);

                                float textH = (line.MaxFontSize * 1.45f * ZoomLevel) + 2.0f * ZoomLevel;
                                float tbY = line.LineY + yTextOffset - 1.0f * ZoomLevel;
                                float tbX = lineStartX + preW;

                                float padX = 1.5f * ZoomLevel;
                                float padY = 0.5f * ZoomLevel;
                                float rx = (float)Math.Round(tbX - padX);
                                float ry = (float)Math.Round(tbY - padY);
                                float rw = (float)Math.Round(tbW + padX * 2);
                                float rh = (float)Math.Round(textH + padY * 2);

                                float penThickness = Math.Max(1.0f, tb.SizePt * ZoomLevel);
                                using (Pen bPen = new Pen(tb.Color, penThickness))
                                {
                                    if (tb.Top && tb.Bottom && tb.Left && tb.Right)
                                    {
                                        g.DrawRectangle(bPen, rx, ry, rw, rh);
                                    }
                                    else
                                    {
                                        if (tb.Top) g.DrawLine(bPen, rx, ry, rx + rw, ry);
                                        if (tb.Bottom) g.DrawLine(bPen, rx, ry + rh, rx + rw, ry + rh);
                                        if (tb.Left) g.DrawLine(bPen, rx, ry, rx, ry + rh);
                                        if (tb.Right) g.DrawLine(bPen, rx + rw, ry, rx + rw, ry + rh);
                                    }
                                }
                            }
                        }

                        // IDE Diff: Red Strikethrough line and Green Addition Callout Badge
                        if (PendingAiDiffs != null && PendingAiDiffs.Count > 0 && isLineVisible)
                        {
                            for (int d = 0; d < PendingAiDiffs.Count; d++)
                            {
                                var diff = PendingAiDiffs[d];
                                int dStart = diff.CharIndex;
                                int dEnd = diff.CharIndex + diff.OriginalLength;
                                if (line.Length > 0 && dEnd > line.StartIndex && dStart < line.StartIndex + line.Length)
                                {
                                    int dsIdx = Math.Max(0, Math.Min(line.Length, dStart - line.StartIndex));
                                    int deIdx = Math.Max(0, Math.Min(line.Length, dEnd - line.StartIndex));
                                    if (deIdx > dsIdx)
                                    {
                                        float dPreW = dsIdx > 0 ? MeasureSubstringWidth(g, line.Text, line.StartIndex, 0, dsIdx, extraSpaceW) : 0f;
                                        float dMatchW = MeasureSubstringWidth(g, line.Text, line.StartIndex, dsIdx, deIdx - dsIdx, extraSpaceW);
                                        float dX = (float)Math.Round(lineStartX + dPreW);
                                        float dTop = (float)Math.Round(line.LineY);
                                        float dH = dynamicLineHeight;

                                        // Draw strikethrough line across deleted text
                                        using (Pen strikePen = new Pen(Color.FromArgb(220, 38, 38), Math.Max(1.5f, 1.6f * ZoomLevel)))
                                        {
                                            float strikeY = dTop + dH * 0.55f;
                                            g.DrawLine(strikePen, dX, strikeY, dX + dMatchW, strikeY);
                                        }

                                        // If this line contains the end of the diff or is last in paragraph, draw Green Replacement Callout
                                        if (dEnd <= line.StartIndex + line.Length || line.IsLastInPara)
                                        {
                                            float badgeX = dX + dMatchW + 6.0f * ZoomLevel;
                                            float badgeY = dTop;
                                            float badgeH = Math.Max(22.0f * ZoomLevel, dH);

                                            string greenText = "+ " + (string.IsNullOrEmpty(diff.ReplacementText) ? "(xoá)" : diff.ReplacementText);
                                            if (greenText.Length > 40) greenText = greenText.Substring(0, 37) + "...";

                                            using (Font badgeFont = new Font("Segoe UI", Math.Max(8.0f, 9.5f * ZoomLevel), FontStyle.Bold))
                                            {
                                                SizeF txtSz = g.MeasureString(greenText, badgeFont);
                                                float btnW = 58.0f * ZoomLevel;
                                                float badgeW = txtSz.Width + 14.0f * ZoomLevel + (btnW * 2) + 8.0f * ZoomLevel;

                                                if (badgeX + badgeW > pageX + pageW - rightMarginX)
                                                {
                                                    badgeX = (float)Math.Round(lineStartX);
                                                    badgeY = dTop + dH + 2.0f * ZoomLevel;
                                                }

                                                RectangleF badgeRect = new RectangleF(badgeX, badgeY, badgeW, badgeH);
                                                diff.BadgeBounds = badgeRect;

                                                // Soft green pastel background (#DCFCE7)
                                                using (SolidBrush gBg = new SolidBrush(Color.FromArgb(245, 220, 252, 231)))
                                                using (Pen gBorder = new Pen(Color.FromArgb(34, 197, 94), 1.2f))
                                                {
                                                    g.FillRectangle(gBg, badgeRect);
                                                    g.DrawRectangle(gBorder, badgeRect.X, badgeRect.Y, badgeRect.Width, badgeRect.Height);
                                                }

                                                // Green text (#15803D)
                                                using (SolidBrush gTxt = new SolidBrush(Color.FromArgb(21, 128, 61)))
                                                {
                                                    float tY = badgeY + (badgeH - txtSz.Height) / 2;
                                                    g.DrawString(greenText, badgeFont, gTxt, badgeX + 6.0f * ZoomLevel, tY);
                                                }

                                                // Mini inline Accept button [✓ Đồng ý]
                                                float btn1X = badgeX + txtSz.Width + 12.0f * ZoomLevel;
                                                float btnY = badgeY + 2.0f * ZoomLevel;
                                                float btnH = badgeH - 4.0f * ZoomLevel;
                                                RectangleF btnAccept = new RectangleF(btn1X, btnY, btnW, btnH);
                                                diff.AcceptButtonBounds = btnAccept;

                                                using (SolidBrush bAcceptBg = new SolidBrush(Color.FromArgb(22, 163, 74)))
                                                using (Font btnFont = new Font("Segoe UI", Math.Max(7.5f, 8.2f * ZoomLevel), FontStyle.Bold))
                                                using (SolidBrush bWhite = new SolidBrush(Color.White))
                                                {
                                                    g.FillRectangle(bAcceptBg, btnAccept);
                                                    StringFormat sf = new StringFormat { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center };
                                                    g.DrawString("✓ Đồng ý", btnFont, bWhite, btnAccept, sf);
                                                }

                                                // Mini inline Reject button [✕ Hủy]
                                                float btn2X = btn1X + btnW + 4.0f * ZoomLevel;
                                                RectangleF btnReject = new RectangleF(btn2X, btnY, btnW - 10.0f * ZoomLevel, btnH);
                                                diff.RejectButtonBounds = btnReject;

                                                using (SolidBrush bRejectBg = new SolidBrush(Color.FromArgb(239, 68, 68)))
                                                using (Font btnFont = new Font("Segoe UI", Math.Max(7.5f, 8.2f * ZoomLevel), FontStyle.Bold))
                                                using (SolidBrush bWhite = new SolidBrush(Color.White))
                                                {
                                                    g.FillRectangle(bRejectBg, btnReject);
                                                    StringFormat sf = new StringFormat { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center };
                                                    g.DrawString("✕ Hủy", btnFont, bWhite, btnReject, sf);
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        RenderedLines.Add(new RenderedLineInfo {
                            StartCharIndex = line.StartIndex,
                            Length = line.Length,
                            ScreenY = (int)Math.Round(line.LineY),
                            ScreenH = (int)Math.Round(dynamicLineHeight),
                            ScreenX = (int)lineStartX,
                            ExtraSpaceW = extraSpaceW
                        });
                    }

                    // Draw Paragraph Borders (Top, Bottom, Left, Right / Box / Horizontal Line)
                    if (ParagraphBorders != null && ParagraphBorders.ContainsKey(paraStartIndex) && wrappedLines.Count > 0)
                    {
                        ParagraphBorderInfo bdr = ParagraphBorders[paraStartIndex];
                        if (bdr != null && bdr.HasAnyBorder)
                        {
                            int paraTopY = (int)Math.Round(wrappedLines[0].LineY);
                            int paraBottomY = (int)Math.Round(wrappedLines[wrappedLines.Count - 1].LineY + wrappedLines[wrappedLines.Count - 1].LineHeight);
                            float penThickness = Math.Max(1.2f, bdr.SizePt * 1.2f * ZoomLevel);
                            using (Pen bPen = new Pen(bdr.Color, penThickness))
                            {
                                float pLeftIndent = ParagraphLeftIndents.ContainsKey(paraStartIndex) ? ParagraphLeftIndents[paraStartIndex] : 0f;
                                float pRightIndent = ParagraphRightIndents.ContainsKey(paraStartIndex) ? ParagraphRightIndents[paraStartIndex] : 0f;
                                int bStartX = textX + (int)Math.Round(pLeftIndent * ZoomLevel);
                                int bEndX = textX + maxTextW - (int)Math.Round(pRightIndent * ZoomLevel);
                                if (bEndX <= bStartX) bEndX = textX + maxTextW;

                                if (bdr.IsHorizontalLine)
                                {
                                    int hLineY = paraBottomY + (int)(2 * ZoomLevel);
                                    g.DrawLine(bPen, bStartX, hLineY, bEndX, hLineY);
                                }
                                else
                                {
                                    int padY = (int)(2 * ZoomLevel);
                                    int topY = paraTopY - padY;
                                    int botY = paraBottomY + padY;

                                    if (bdr.Top) g.DrawLine(bPen, bStartX, topY, bEndX, topY);
                                    if (bdr.Bottom) g.DrawLine(bPen, bStartX, botY, bEndX, botY);
                                    if (bdr.Left) g.DrawLine(bPen, bStartX, topY, bStartX, botY);
                                    if (bdr.Right) g.DrawLine(bPen, bEndX, topY, bEndX, botY);
                                }
                            }
                        }
                    }
                    else if (ParagraphBottomBorders != null && ParagraphBottomBorders.ContainsKey(paraStartIndex))
                    {
                        Color borderCol = ParagraphBottomBorders[paraStartIndex];
                        int bdrY = (int)Math.Round(currentY + 3 * ZoomLevel);
                        float pLeftIndent = ParagraphLeftIndents.ContainsKey(paraStartIndex) ? ParagraphLeftIndents[paraStartIndex] : 0f;
                        float pRightIndent = ParagraphRightIndents.ContainsKey(paraStartIndex) ? ParagraphRightIndents[paraStartIndex] : 0f;
                        int bStartX = textX + (int)Math.Round(pLeftIndent * ZoomLevel);
                        int bEndX = textX + maxTextW - (int)Math.Round(pRightIndent * ZoomLevel);
                        if (bEndX <= bStartX) bEndX = textX + maxTextW;
                        using (Pen bPen = new Pen(borderCol, Math.Max(1.5f, 1.5f * ZoomLevel)))
                        {
                            g.DrawLine(bPen, bStartX, bdrY, bEndX, bdrY);
                        }
                        currentY += (int)(10 * ZoomLevel);
                    }

                    paraStartIndex += para.Length + 1;
                    DocParagraphGaps.Add(new ParagraphGap { ScreenY = (int)Math.Round(currentY), CharIndex = paraStartIndex, VirtualEntersNeeded = 0 });
                }
            }

            // Generate virtual gaps for empty space below document content & next page
            int defaultLineH = (int)(Math.Max(26.0f * ZoomLevel, 11.0f * 1.4f * ZoomLevel) * ribbon.LineSpacingFactor);
            if (defaultLineH < 15) defaultLineH = 20;

            int fillY = (int)Math.Round(currentY) + defaultLineH;
            int fillPage = currentPage;
            int vEnters = 1;

            // Fill empty space on current page and 1 extra page below
            while (fillPage <= currentPage + 1)
            {
                int pageMaxY = startPageY + fillPage * (pageH + 30) + pageH - marginY;
                if (fillY + defaultLineH > pageMaxY)
                {
                    fillPage++;
                    fillY = startPageY + fillPage * (pageH + 30) + marginY;
                }

                DocParagraphGaps.Add(new ParagraphGap
                {
                    ScreenY = fillY,
                    CharIndex = PieceTable.Length,
                    VirtualEntersNeeded = vEnters
                });

                fillY += defaultLineH;
                vEnters++;
            }

            int endEstimatedPage = Math.Max(0, ((int)Math.Round(currentY) - startPageY) / (pageH + 30));
            int finalPages = Math.Max(1, Math.Max(currentPage + 1, endEstimatedPage + 1));
            foreach (var sh in DocumentShapes)
            {
                if (sh.PageNumber + 1 > finalPages) finalPages = sh.PageNumber + 1;
            }
            foreach (var ch in DocumentCharts)
            {
                if (ch.PageNumber + 1 > finalPages) finalPages = ch.PageNumber + 1;
            }
            CalculatedPageCount = finalPages;
            TotalPageCount = finalPages;
            if (ViewMode == 0)
            {
                ReadModePageIndex = Math.Max(0, Math.Min(finalPages - 1, ReadModePageIndex));
                CurrentActivePage = ReadModePageIndex + 1;
            }
            else
            {
                CurrentActivePage = Math.Max(1, Math.Min(finalPages, (int)((ScrollY + (height / 2)) / (pageH + 30)) + 1));
            }

            // Draw End of Document Marker in Read Mode (ViewMode == 0)
            if (ViewMode == 0 && ReadModePageIndex == finalPages - 1)
            {
                using (Font endFont = new Font("Segoe UI", 9.0f, FontStyle.Regular))
                using (SolidBrush sqBrush = new SolidBrush(Color.FromArgb(0, 120, 212)))
                {
                    g.DrawString("End of document ", endFont, Brushes.Gray, textX, currentY + 25);
                    g.FillRectangle(sqBrush, textX + 105, currentY + 30, 8, 8);
                }
            }

            // PASS 2: Render Floating Shapes & Charts that wrap text (Square, Tight, Through, Top/Bottom)
            foreach (var sh in DocumentShapes)
            {
                if (sh.Visible && sh.WrapMode != 0 && sh.WrapMode != 5 && sh.WrapMode != 6 && !sh.LastBounds.IsEmpty)
                {
                    bool isShapeVis = (ViewMode == 0) ? (sh.PageNumber == ReadModePageIndex) : (sh.LastBounds.Bottom >= 150 && sh.LastBounds.Top <= height);
                    if (isShapeVis)
                        ShapeRenderer.DrawShape(g, sh, sh.LastBounds, ribbon, ZoomLevel);
                }
            }
            foreach (var ch in DocumentCharts)
            {
                if (ch.Visible && ch.WrapMode != 0 && ch.WrapMode != 5 && ch.WrapMode != 6 && !ch.LastBounds.IsEmpty)
                {
                    bool isChartVis = (ViewMode == 0) ? (ch.PageNumber == ReadModePageIndex) : (ch.LastBounds.Bottom >= 150 && ch.LastBounds.Top <= height);
                    if (isChartVis)
                        DrawDocumentChart(g, ch, ch.LastBounds.X, ch.LastBounds.Y, ch.LastBounds.Width, ch.LastBounds.Height, ribbon);
                }
            }

            // PASS 3: Render In-Front-Of-Text Shapes & Charts (WrapMode == 6) over the text
            foreach (var sh in DocumentShapes)
            {
                if (sh.Visible && sh.WrapMode == 6 && !sh.LastBounds.IsEmpty)
                {
                    bool isShapeVis = (ViewMode == 0) ? (sh.PageNumber == ReadModePageIndex) : (sh.LastBounds.Bottom >= 150 && sh.LastBounds.Top <= height);
                    if (isShapeVis)
                        ShapeRenderer.DrawShape(g, sh, sh.LastBounds, ribbon, ZoomLevel);
                }
            }
            foreach (var ch in DocumentCharts)
            {
                if (ch.Visible && ch.WrapMode == 6 && !ch.LastBounds.IsEmpty)
                {
                    bool isChartVis = (ViewMode == 0) ? (ch.PageNumber == ReadModePageIndex) : (ch.LastBounds.Bottom >= 150 && ch.LastBounds.Top <= height);
                    if (isChartVis)
                        DrawDocumentChart(g, ch, ch.LastBounds.X, ch.LastBounds.Y, ch.LastBounds.Width, ch.LastBounds.Height, ribbon);
                }
            }

            // PASS 3b: Render Regular Freehand Ink Strokes (Tab Vẽ - Bút thường) ON TOP of Text & Tables
            if (DocumentInkStrokes != null && DocumentInkStrokes.Count > 0)
            {
                SmoothingMode prevSmoothInk = g.SmoothingMode;
                g.SmoothingMode = SmoothingMode.AntiAlias;
                for (int si = 0; si < DocumentInkStrokes.Count; si++)
                {
                    var stroke = DocumentInkStrokes[si];
                    if (stroke != null && !stroke.IsHighlighter && stroke.Points != null && stroke.Points.Count > 0)
                    {
                        int sPageY = startPageY + stroke.PageIndex * (pageH + 30);
                        if (sPageY + pageH >= 150 && sPageY <= height)
                        {
                            DrawInkStroke(g, stroke, pageX, sPageY, ZoomLevel);
                        }
                    }
                }
                g.SmoothingMode = prevSmoothInk;
            }
            if (_currentInkStroke != null && !_currentInkStroke.IsHighlighter && _currentInkStroke.Points != null && _currentInkStroke.Points.Count > 0)
            {
                SmoothingMode prevSmoothInk = g.SmoothingMode;
                g.SmoothingMode = SmoothingMode.AntiAlias;
                int sPageY = startPageY + _currentInkStroke.PageIndex * (pageH + 30);
                DrawInkStroke(g, _currentInkStroke, pageX, sPageY, ZoomLevel);
                g.SmoothingMode = prevSmoothInk;
            }

            // 5. Draw Blinking Caret Bar — Microsoft Word Elegant 1px Pure Black Flat Caret
            CurrentCaretScreenX = cursorX;
            CurrentCaretScreenY = cursorY;
            CurrentCaretScreenH = cursorH;
            if (CursorVisible && ActiveShape == null && ActiveChart == null && !hasSelection && ViewMode != 0)
            {
                float cursorW = (ZoomLevel >= 1.5f) ? 1.5f : 1.0f;
                SmoothingMode prevSmooth = g.SmoothingMode;
                g.SmoothingMode = SmoothingMode.None;
                using (Pen cursorPen = new Pen(Color.Black, cursorW))
                {
                    cursorPen.StartCap = LineCap.Flat;
                    cursorPen.EndCap = LineCap.Flat;
                    g.DrawLine(cursorPen, cursorX, cursorY, cursorX, cursorY + cursorH);
                }
                g.SmoothingMode = prevSmooth;
            }

            // 5b. Inline image drag cursor indicator — Word-style blue vertical bar
            if (IsDraggingShape && ActiveShape != null && ActiveShape.WrapMode == 0 && InlineDragDropCursorX >= 0)
            {
                float iCursorW = Math.Max(2.0f, 2.0f * ZoomLevel);
                using (Pen inlineCursorPen = new Pen(Color.FromArgb(0, 102, 204), iCursorW))
                {
                    inlineCursorPen.StartCap = LineCap.Round;
                    inlineCursorPen.EndCap = LineCap.Round;
                    int cH = Math.Max((int)(22 * ZoomLevel), InlineDragDropCursorH);
                    g.DrawLine(inlineCursorPen, InlineDragDropCursorX, InlineDragDropCursorY, InlineDragDropCursorX, InlineDragDropCursorY + cH);
                    // Small downward triangle at top to show insert position
                    Point[] tri = new Point[]
                    {
                        new Point(InlineDragDropCursorX - (int)(4*ZoomLevel), InlineDragDropCursorY),
                        new Point(InlineDragDropCursorX + (int)(4*ZoomLevel), InlineDragDropCursorY),
                        new Point(InlineDragDropCursorX, InlineDragDropCursorY + (int)(7*ZoomLevel))
                    };
                    using (SolidBrush triBrush = new SolidBrush(Color.FromArgb(0, 102, 204)))
                        g.FillPolygon(triBrush, tri);
                }
            }

            // 5c. Word 365 Track Changes Change Bars (Vertical revision indicator in left margin)
            if (Revisions != null && Revisions.Count > 0 && DisplayMarkupMode != MarkupDisplayMode.NoMarkup && RenderedLines.Count > 0)
            {
                using (Pen changeBarPen = new Pen(Color.FromArgb(192, 0, 0), Math.Max(2.0f, 2.0f * ZoomLevel)))
                {
                    int barMarginX = textX - (int)(14 * ZoomLevel);
                    for (int li = 0; li < RenderedLines.Count; li++)
                    {
                        var rLine = RenderedLines[li];
                        if (rLine.ScreenY + rLine.ScreenH < 150 || rLine.ScreenY > height) continue;

                        int lStart = rLine.StartCharIndex;
                        int lEnd = lStart + rLine.Length;
                        bool hasRev = false;
                        for (int ri = 0; ri < Revisions.Count; ri++)
                        {
                            var rev = Revisions[ri];
                            int revEnd = rev.StartIndex + rev.Length;
                            if (lStart < revEnd && lEnd > rev.StartIndex)
                            {
                                hasRev = true;
                                break;
                            }
                        }
                        if (hasRev)
                        {
                            g.DrawLine(changeBarPen, barMarginX, rLine.ScreenY, barMarginX, rLine.ScreenY + rLine.ScreenH);
                        }
                    }
                }
            }



            // 6.5. IN FRONT OF TEXT: Draw Banner On Top of Document Text (Che phủ hoàn toàn văn bản bên dưới)
            if (IsEditingHeaderFooter && CurrentHeaderPreset == HeaderFooterPreset.Banded && HeaderWrapMode == 6)
            {
                DrawBandedHeaderBanner(g, pageX, startPageY, pageW, pageH, ribbon);
            }

            // 7. TOPMOST OVERLAY: Render Layout Options Popup Dialog if opened (Đảm bảo nằm trên mọi lớp chữ và canvas)
            if (IsEditingHeaderFooter && CurrentHeaderPreset == HeaderFooterPreset.Banded && ShowHeaderLayoutOptions)
            {
                int leftM_pop = (int)(ribbon.GetEffectiveLeftMarginInches() * 54.0f * ZoomLevel);
                int rightM_pop = (int)(ribbon.GetEffectiveRightMarginInches() * 54.0f * ZoomLevel);
                int bX_pop = pageX + leftM_pop + (int)(HeaderBannerXOffset * ZoomLevel);
                int bW_pop = Math.Max((int)(50 * ZoomLevel), pageW - leftM_pop - rightM_pop + (int)(HeaderBannerWidthDelta * ZoomLevel));
                int bY_pop = startPageY + (int)(10 * ZoomLevel) + (int)(HeaderBannerYOffset * ZoomLevel);

                Rectangle wrapBtnRect = new Rectangle(bX_pop + bW_pop + 4, bY_pop, 22, 22);

                int popW = 185;
                int popH = 250;
                int popX = wrapBtnRect.Right + 8;
                int popY = wrapBtnRect.Top - 5;

                g.FillRectangle(Brushes.White, popX, popY, popW, popH);
                using (Pen popBorder = new Pen(Color.FromArgb(0, 120, 215), 1.2f))
                {
                    g.DrawRectangle(popBorder, popX, popY, popW, popH);

                    // Left pointer notch triangle pointing to wrap button
                    Point[] pointerPts = new Point[]
                    {
                        new Point(popX, popY + 12),
                        new Point(popX - 6, popY + 18),
                        new Point(popX, popY + 24)
                    };
                    g.FillPolygon(Brushes.White, pointerPts);
                    g.DrawLine(popBorder, popX, popY + 12, popX - 6, popY + 18);
                    g.DrawLine(popBorder, popX - 6, popY + 18, popX, popY + 24);
                }

                using (Font headerFont = new Font("Segoe UI", 9.5f, FontStyle.Bold))
                using (Font sectionFont = new Font("Segoe UI", 8.0f, FontStyle.Bold))
                using (Font itemFont = new Font("Segoe UI", 8.5f, FontStyle.Regular))
                {
                    // Title & Close Button
                    g.DrawString("Tùy chọn bố trí", headerFont, new SolidBrush(Color.FromArgb(0, 95, 184)), popX + 12, popY + 10);
                    using (Pen closePen = new Pen(Color.FromArgb(100, 100, 100), 1.5f))
                    {
                        g.DrawLine(closePen, popX + popW - 20, popY + 12, popX + popW - 10, popY + 22);
                        g.DrawLine(closePen, popX + popW - 10, popY + 12, popX + popW - 20, popY + 22);
                    }

                    // Section 1: Cùng dòng với văn bản (In Line with Text)
                    Rectangle sec1Bar = new Rectangle(popX + 10, popY + 36, popW - 20, 18);
                    using (SolidBrush secBarBrush = new SolidBrush(Color.FromArgb(236, 238, 241)))
                    {
                        g.FillRectangle(secBarBrush, sec1Bar);
                    }
                    g.DrawString("Cùng dòng với văn bản", sectionFont, new SolidBrush(Color.FromArgb(85, 90, 95)), sec1Bar.X + 6, sec1Bar.Y + 2);

                    Rectangle inlineCard = new Rectangle(popX + 14, popY + 58, 42, 34);
                    DrawVectorWrapCard(g, 0, inlineCard, HeaderWrapMode == 0);

                    // Section 2: Ngắt dòng văn bản (With Text Wrapping)
                    Rectangle sec2Bar = new Rectangle(popX + 10, popY + 98, popW - 20, 18);
                    using (SolidBrush secBarBrush = new SolidBrush(Color.FromArgb(236, 238, 241)))
                    {
                        g.FillRectangle(secBarBrush, sec2Bar);
                    }
                    g.DrawString("Ngắt dòng văn bản", sectionFont, new SolidBrush(Color.FromArgb(85, 90, 95)), sec2Bar.X + 6, sec2Bar.Y + 2);

                    // 6 Vector Wrapping Cards (3 cols x 2 rows)
                    for (int r = 0; r < 2; r++)
                    {
                        for (int c = 0; c < 3; c++)
                        {
                            int wIdx = r == 0 ? (1 + c) : (4 + c);
                            Rectangle cardBox = new Rectangle(popX + 14 + c * 52, popY + 120 + r * 38, 42, 34);
                            DrawVectorWrapCard(g, wIdx, cardBox, HeaderWrapMode == wIdx);
                        }
                    }

                    // Vector Radio 1: Di chuyển cùng văn bản
                    int r1Y = popY + 204;
                    DrawVectorRadioButton(g, popX + 14, r1Y, !HeaderFixPosition, "Di chuyển cùng văn bản", itemFont);
                    DrawVectorInfoIcon(g, popX + popW - 26, r1Y + 2);

                    // Vector Radio 2: Cố định vị trí trên trang
                    int r2Y = popY + 228;
                    DrawVectorRadioButton(g, popX + 14, r2Y, HeaderFixPosition, "Cố định vị trí trên trang", itemFont);
                    DrawVectorInfoIcon(g, popX + popW - 26, r2Y + 2);
                }
            }

            // 7.5. TOPMOST OVERLAYS: Render Shape & Chart Popup Dialogs on top of all text and pages
            if (ActiveShape != null && ActiveShape.ShowLayoutOptions && !ActiveShape.LastBounds.IsEmpty)
            {
                ShapeRenderer.DrawLayoutOptionsPopup(g, ActiveShape, ActiveShape.LastBounds, ZoomLevel);
            }

            if (ActiveChart != null)
            {
                if (ActiveChart.ShowLayoutOptions) DrawChartWrapMenu(g, ActiveChart);
                if (ActiveChart.ShowElementsMenu) DrawChartElementsMenu(g, ActiveChart);
                if (ActiveChart.ShowStylesMenu) DrawChartStylesMenu(g, ActiveChart);
            }

            // 7.8. TABLE LAYOUT OPTIONS POPUP (Tùy chọn bố trí Wrap Text cho Bảng)
            if (ActiveTableLayoutOptionsIndex >= 0 && ActiveTableLayoutOptionsIndex < MoveHandleRects.Count)
            {
                DrawTableLayoutOptionsPopup(g, ActiveTableLayoutOptionsIndex, width, ZoomLevel);
            }

            // 7.85. TABLE DRAG & DROP INSERTION INDICATOR (MS Word Snap-to-gap)
            if (IsDraggingMove && DragTableIndex >= 0)
            {
                int tWrap = TableWrapModes.ContainsKey(DragTableIndex) ? TableWrapModes[DragTableIndex] : 0;
                if (tWrap == 0 && DragPreviewGapIndex >= 0 && DragPreviewGapIndex < DocParagraphGaps.Count)
                {
                    int gapY = DocParagraphGaps[DragPreviewGapIndex].ScreenY;
                    int lineLeft = pageX + marginX;
                    int lineRight = pageX + pageW - rightMarginX;

                    // 1. Draw horizontal insertion line
                    using (Pen insertPen = new Pen(Color.FromArgb(0, 120, 215), 3.0f))
                    {
                        g.DrawLine(insertPen, lineLeft, gapY, lineRight, gapY);
                    }

                    // 2. Draw left and right caret triangles (▶ and ◀)
                    using (SolidBrush arrowBrush = new SolidBrush(Color.FromArgb(0, 120, 215)))
                    {
                        Point[] leftArrow = new Point[]
                        {
                            new Point(lineLeft - 8, gapY - 6),
                            new Point(lineLeft + 1, gapY),
                            new Point(lineLeft - 8, gapY + 6)
                        };
                        Point[] rightArrow = new Point[]
                        {
                            new Point(lineRight + 8, gapY - 6),
                            new Point(lineRight - 1, gapY),
                            new Point(lineRight + 8, gapY + 6)
                        };
                        g.FillPolygon(arrowBrush, leftArrow);
                        g.FillPolygon(arrowBrush, rightArrow);
                    }

                    // 3. Draw semi-transparent ghost preview box showing table drop bounds
                    int prevW = (DragPreviewTableW > 0) ? DragPreviewTableW : (lineRight - lineLeft);
                    int prevH = (DragPreviewTableH > 0) ? DragPreviewTableH : (int)(50 * ZoomLevel);
                    Rectangle prevRect = new Rectangle(lineLeft, gapY + 3, prevW, prevH);
                    using (SolidBrush ghostBg = new SolidBrush(Color.FromArgb(28, 0, 120, 215)))
                    using (Pen ghostPen = new Pen(Color.FromArgb(160, 0, 120, 215), 1.5f))
                    {
                        ghostPen.DashStyle = DashStyle.Dash;
                        g.FillRectangle(ghostBg, prevRect);
                        g.DrawRectangle(ghostPen, prevRect);
                    }
                }
            }

            // 7.9. RENDER DOCUMENT COMMENTS & RIGHT MARGIN MARKUP CALLOUTS
            DrawDocumentComments(g, pageX, pageW, startPageY, pageH, finalPages, ribbon);

            if (readModeState != null)
            {
                g.Restore(readModeState);
                readModeState = null;
            }

            g.Restore(docClipState);

            // 8. MS WORD NAVIGATION PANE (Tìm kiếm & Điều hướng)
            if (ShowNavigationPane)
            {
                DrawNavigationPane(g, width, height, ribbon);
            }

            // 9. MS WORD SELECTION PANE (Ngăn Lựa Chọn)
            if (ShowSelectionPane)
            {
                DrawSelectionPane(g, width, height, ribbon);
            }

            // 10. INTERACTIVE RULERS (Cố định ở đỉnh & cạnh trái, luôn vẽ đè lên trên trang khi cuộn)
            if (ribbon != null && ribbon.ShowRuler)
            {
                DrawInteractiveRuler(g, pageX, pageW, marginX, rightMarginX, width, height, ribbon);
                DrawVerticalRuler(g, pageX, pageW, pageH, marginY, bottomMarginY, width, height, ribbon);
            }

            // 11. MODERN WORD-STYLE SCROLLBARS (Thanh cuộn dọc và ngang phong cách Word)
            DrawWordScrollBar(g, width, height, ribbon);
            DrawWordHScrollBar(g, width, height, ribbon);
        }

        private void DrawInkStroke(D2DGraphics g, DocInkStroke stroke, int pageX, int pageY, float zoom)
        {
            if (stroke == null || stroke.Points == null || stroke.Points.Count == 0) return;
            if (stroke.Points.Count == 1)
            {
                float sx = pageX + stroke.Points[0].X * zoom;
                float sy = pageY + stroke.Points[0].Y * zoom;
                float r = Math.Max(1.5f, stroke.StrokeWidth * zoom * 0.5f);
                Color c = stroke.IsHighlighter ? Color.FromArgb(115, stroke.Color) : stroke.Color;
                using (SolidBrush b = new SolidBrush(c))
                {
                    g.FillEllipse(b, sx - r, sy - r, 2 * r, 2 * r);
                }
                return;
            }

            Color penColor = stroke.IsHighlighter ? Color.FromArgb(115, stroke.Color) : stroke.Color;
            float w = Math.Max(1.2f, stroke.StrokeWidth * zoom);
            using (GraphicsPath path = new GraphicsPath())
            {
                PointF[] pts = new PointF[stroke.Points.Count];
                for (int i = 0; i < stroke.Points.Count; i++)
                {
                    pts[i] = new PointF(pageX + stroke.Points[i].X * zoom, pageY + stroke.Points[i].Y * zoom);
                }
                path.AddLines(pts);
                using (Pen p = new Pen(penColor, w))
                {
                    p.StartCap = LineCap.Round;
                    p.EndCap = LineCap.Round;
                    p.LineJoin = LineJoin.Round;
                    g.DrawPath(p, path);
                }
            }
        }

        private void TryStraightenStroke(DocInkStroke stroke)
        {
            if (stroke == null || stroke.Points == null || stroke.Points.Count < 3) return;

            PointF pStart = stroke.Points[0];
            PointF pEnd = stroke.Points[stroke.Points.Count - 1];

            float dx = pEnd.X - pStart.X;
            float dy = pEnd.Y - pStart.Y;
            float chordLen = (float)Math.Sqrt(dx * dx + dy * dy);

            // Ignore tiny strokes (< 16 px in document units)
            if (chordLen < 16f) return;

            // Compute total arc/path length
            float pathLen = 0f;
            for (int i = 1; i < stroke.Points.Count; i++)
            {
                float segDx = stroke.Points[i].X - stroke.Points[i - 1].X;
                float segDy = stroke.Points[i].Y - stroke.Points[i - 1].Y;
                pathLen += (float)Math.Sqrt(segDx * segDx + segDy * segDy);
            }

            // If the path deviates too much from chord length (e.g., circle, loop, letter), do not straighten
            if (pathLen > chordLen * 1.35f) return;

            // Check maximum perpendicular distance from intermediate points to chord line
            float maxDist = 0f;
            for (int i = 1; i < stroke.Points.Count - 1; i++)
            {
                PointF p = stroke.Points[i];
                float dist = Math.Abs(dy * p.X - dx * p.Y + pEnd.X * pStart.Y - pEnd.Y * pStart.X) / chordLen;
                if (dist > maxDist) maxDist = dist;
            }

            // Allow moderate hand wobble (max perpendicular distance <= 24% of chordLen or <= 28 px)
            if (maxDist > chordLen * 0.24f || maxDist > 28f) return;

            // Determine snap direction
            float absDx = Math.Abs(dx);
            float absDy = Math.Abs(dy);

            PointF finalStart = pStart;
            PointF finalEnd = pEnd;

            if (absDy <= chordLen * 0.16f)
            {
                // Near horizontal (e.g. highlighting a line of text, underlining) -> Snap to exact horizontal line!
                float avgY = (pStart.Y + pEnd.Y) / 2.0f;
                finalStart = new PointF(pStart.X, avgY);
                finalEnd = new PointF(pEnd.X, avgY);
            }
            else if (absDx <= chordLen * 0.16f)
            {
                // Near vertical -> Snap to exact vertical line!
                float avgX = (pStart.X + pEnd.X) / 2.0f;
                finalStart = new PointF(avgX, pStart.Y);
                finalEnd = new PointF(avgX, pEnd.Y);
            }

            // Reconstruct points along the straightened line segment (8 evenly spaced points for smooth eraser hit test)
            stroke.Points.Clear();
            int numSteps = 8;
            for (int s = 0; s <= numSteps; s++)
            {
                float t = (float)s / numSteps;
                float sx = finalStart.X + (finalEnd.X - finalStart.X) * t;
                float sy = finalStart.Y + (finalEnd.Y - finalStart.Y) * t;
                stroke.Points.Add(new PointF(sx, sy));
            }
        }

        private void DrawDocumentComments(D2DGraphics g, int pageX, int pageW, int startPageY, int pageH, int pageCount, RibbonBar ribbon)
        {
            if (Comments == null || Comments.Count == 0) return;

            CommentBadgeHitRects.Clear();
            CommentReplyBtnRects.Clear();
            CommentResolveBtnRects.Clear();
            CommentAnchorTextRects.Clear();

            // Right markup separator line
            int markupSepX = pageX + pageW - 135;
            using (Pen sepPen = new Pen(Color.FromArgb(226, 232, 240), 1.0f))
            {
                g.DrawLine(sepPen, markupSepX, startPageY + 10, markupSepX, startPageY + pageCount * (pageH + 30) - 10);
            }

            int calloutX = markupSepX + 12;

            for (int ci = 0; ci < Comments.Count; ci++)
            {
                DocumentComment c = Comments[ci];
                if (c == null) continue;

                // Match line position from RenderedLines
                int lineY = startPageY + 40;
                int lineH = (int)(22 * ZoomLevel);
                int lineX = pageX + (int)(ribbon.GetEffectiveLeftMarginInches() * 72 * ZoomLevel);
                int charOffset = 0;

                for (int rl = 0; rl < RenderedLines.Count; rl++)
                {
                    RenderedLineInfo rLine = RenderedLines[rl];
                    if (c.RangeStart >= rLine.StartCharIndex && c.RangeStart <= rLine.StartCharIndex + rLine.Length)
                    {
                        lineY = rLine.ScreenY;
                        lineH = rLine.ScreenH;
                        lineX = rLine.ScreenX;
                        charOffset = Math.Max(0, c.RangeStart - rLine.StartCharIndex);
                        break;
                    }
                }

                int anchorX = lineX + (int)(charOffset * 7.2f * ZoomLevel);
                int anchorW = Math.Max((int)(35 * ZoomLevel), (int)(c.RangeLength * 7.5f * ZoomLevel));
                Rectangle anchorBox = new Rectangle(anchorX, lineY, anchorW, lineH);
                CommentAnchorTextRects[c.Id] = anchorBox;

                int calloutY = lineY - 2;
                bool isHovered = (HoveredCommentId == c.Id || ActiveCommentId == c.Id || EditingReplyCommentId == c.Id);

                string authorInitial = !string.IsNullOrEmpty(c.Author) ? c.Author.Substring(0, 1).ToUpper() : "D";
                string authorName = !string.IsNullOrEmpty(c.Author) ? c.Author : "Danh";

                // Calculate relative time string
                TimeSpan elapsed = DateTime.Now - c.CreatedTime;
                string timeStr = "A few seconds ago";
                if (elapsed.TotalMinutes >= 60) timeStr = ((int)elapsed.TotalHours).ToString() + " hours ago";
                else if (elapsed.TotalMinutes >= 1) timeStr = ((int)elapsed.TotalMinutes).ToString() + " minutes ago";

                if (isHovered)
                {
                    // ================= 2. EXPANDED / HOVERED STATE (Image 2) =================
                    // A. Highlight and red border on text
                    using (SolidBrush pinkBrush = new SolidBrush(Color.FromArgb(254, 226, 226)))
                    using (Pen redPen = new Pen(Color.FromArgb(220, 38, 38), 1.2f))
                    {
                        g.FillRectangle(pinkBrush, anchorBox);
                        g.DrawRectangle(redPen, anchorBox);

                        // Red leader connecting line from text box to comment card
                        g.DrawLine(redPen, anchorBox.Right, anchorBox.Top + 1, calloutX, calloutY);
                    }

                    // Calculate dynamic card height
                    int replyCount = (c.Replies != null) ? c.Replies.Count : 0;
                    bool isReplying = (EditingReplyCommentId == c.Id);
                    int cardH = 78 + (replyCount * 32) + (isReplying ? 42 : 0);

                    // B. Expanded Comment Card
                    Rectangle cardBox = new Rectangle(calloutX, calloutY, 230, cardH);
                    g.FillRectangle(Brushes.White, cardBox);
                    using (Pen pCard = new Pen(Color.FromArgb(220, 38, 38), 1.2f))
                    {
                        g.DrawRectangle(pCard, cardBox);
                    }

                    int curCardY = calloutY + 6;

                    // Main Comment Header
                    Rectangle avaRect = new Rectangle(calloutX + 8, curCardY + 2, 20, 20);
                    using (SolidBrush avaBg = new SolidBrush(Color.FromArgb(220, 38, 38)))
                    using (Font avaFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
                    {
                        g.FillEllipse(avaBg, avaRect);
                        using (StringFormat sf = new StringFormat { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center })
                        {
                            g.DrawString(authorInitial, avaFont, Brushes.White, new RectangleF(avaRect.X, avaRect.Y - 1, avaRect.Width, avaRect.Height), sf);
                        }
                    }

                    using (Font authFont = new Font("Segoe UI", 9.0f, FontStyle.Bold))
                    using (Font timeFont = new Font("Segoe UI", 8.0f, FontStyle.Regular))
                    {
                        g.DrawString(authorName, authFont, new SolidBrush(Color.FromArgb(15, 23, 42)), calloutX + 32, curCardY);
                        SizeF aSz = g.MeasureString(authorName, authFont);
                        g.DrawString(timeStr, timeFont, new SolidBrush(Color.FromArgb(100, 116, 139)), calloutX + 34 + (int)aSz.Width, curCardY + 1);
                    }

                    curCardY += 20;

                    // Main Comment Content
                    using (Font contentFont = new Font("Segoe UI", 8.5f, FontStyle.Regular))
                    {
                        string cText = string.IsNullOrEmpty(c.Content) ? "(Không có nội dung)" : c.Content;
                        if (cText.Length > 45) cText = cText.Substring(0, 42) + "...";
                        g.DrawString(cText, contentFont, new SolidBrush(Color.FromArgb(51, 65, 85)), calloutX + 32, curCardY);
                    }

                    curCardY += 22;

                    // Render Existing Replies (nếu có)
                    if (c.Replies != null && c.Replies.Count > 0)
                    {
                        for (int ri = 0; ri < c.Replies.Count; ri++)
                        {
                            using (Pen pSubDiv = new Pen(Color.FromArgb(241, 245, 249), 1f))
                            {
                                g.DrawLine(pSubDiv, calloutX + 16, curCardY, calloutX + 224, curCardY);
                            }
                            curCardY += 4;

                            Rectangle rAvaRect = new Rectangle(calloutX + 18, curCardY + 2, 16, 16);
                            using (SolidBrush rAvaBg = new SolidBrush(Color.FromArgb(37, 99, 235)))
                            using (Font rAvaFont = new Font("Segoe UI", 7.0f, FontStyle.Bold))
                            {
                                g.FillEllipse(rAvaBg, rAvaRect);
                                using (StringFormat sf = new StringFormat { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center })
                                {
                                    g.DrawString("U", rAvaFont, Brushes.White, new RectangleF(rAvaRect.X, rAvaRect.Y - 1, rAvaRect.Width, rAvaRect.Height), sf);
                                }
                            }

                            using (Font repFont = new Font("Segoe UI", 8.0f, FontStyle.Regular))
                            {
                                string repTxt = c.Replies[ri];
                                if (repTxt.Length > 38) repTxt = repTxt.Substring(0, 35) + "...";
                                g.DrawString(repTxt, repFont, new SolidBrush(Color.FromArgb(30, 41, 59)), calloutX + 38, curCardY + 2);
                            }
                            curCardY += 24;
                        }
                    }

                    // Render Inline Reply Box (khi đang gõ phản hồi)
                    if (isReplying)
                    {
                        using (Pen pSubDiv = new Pen(Color.FromArgb(241, 245, 249), 1f))
                        {
                            g.DrawLine(pSubDiv, calloutX + 8, curCardY, calloutX + 222, curCardY);
                        }
                        curCardY += 4;

                        Rectangle rAvaRect = new Rectangle(calloutX + 10, curCardY + 2, 18, 18);
                        using (SolidBrush rAvaBg = new SolidBrush(Color.FromArgb(220, 38, 38)))
                        using (Font rAvaFont = new Font("Segoe UI", 8.0f, FontStyle.Bold))
                        {
                            g.FillEllipse(rAvaBg, rAvaRect);
                            using (StringFormat sf = new StringFormat { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center })
                            {
                                g.DrawString(authorInitial, rAvaFont, Brushes.White, new RectangleF(rAvaRect.X, rAvaRect.Y - 1, rAvaRect.Width, rAvaRect.Height), sf);
                            }
                        }

                        using (Font authFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
                        using (Font timeFont = new Font("Segoe UI", 7.8f, FontStyle.Regular))
                        {
                            g.DrawString(authorName, authFont, new SolidBrush(Color.FromArgb(15, 23, 42)), calloutX + 32, curCardY);
                            SizeF aSz = g.MeasureString(authorName, authFont);
                            g.DrawString("A few seconds ago", timeFont, new SolidBrush(Color.FromArgb(100, 116, 139)), calloutX + 34 + (int)aSz.Width, curCardY + 1);
                        }

                        curCardY += 18;

                        using (Font inFont = new Font("Segoe UI", 8.5f, FontStyle.Regular))
                        {
                            string draft = ReplyDraftText + "|";
                            g.DrawString(draft, inFont, new SolidBrush(Color.FromArgb(30, 41, 59)), calloutX + 32, curCardY);
                        }

                        curCardY += 20;
                    }

                    // Divider line before bottom actions
                    using (Pen pDiv = new Pen(Color.FromArgb(241, 245, 249), 1f))
                    {
                        g.DrawLine(pDiv, calloutX + 4, cardBox.Bottom - 26, calloutX + 226, cardBox.Bottom - 26);
                    }

                    // Bottom Action buttons: Reply & Resolve / Reopen
                    Rectangle replyRect = new Rectangle(calloutX + 102, cardBox.Bottom - 24, 58, 22);
                    Rectangle resolveRect = new Rectangle(calloutX + 162, cardBox.Bottom - 24, 64, 22);
                    CommentReplyBtnRects[c.Id] = replyRect;
                    CommentResolveBtnRects[c.Id] = resolveRect;

                    using (Font actFont = new Font("Segoe UI", 8.2f, FontStyle.Regular))
                    {
                        // Purple 💬↩ Reply
                        DrawReplyVectorIcon(g, replyRect.X + 2, replyRect.Y + 3, Color.FromArgb(124, 58, 237));
                        g.DrawString("Reply", actFont, new SolidBrush(Color.FromArgb(30, 64, 175)), replyRect.X + 18, replyRect.Y + 2);

                        // Green 💬✔ Resolve / Reopen
                        string resLabel = c.IsResolved ? "Reopen" : "Resolve";
                        DrawResolveVectorIcon(g, resolveRect.X + 2, resolveRect.Y + 3, Color.FromArgb(22, 163, 74));
                        g.DrawString(resLabel, actFont, new SolidBrush(Color.FromArgb(30, 64, 175)), resolveRect.X + 18, resolveRect.Y + 2);
                    }

                    CommentBadgeHitRects[c.Id] = cardBox;
                }
                else
                {
                    // ================= 1. NORMAL / COLLAPSED STATE (Image 1) =================
                    Rectangle avaRect = new Rectangle(calloutX, calloutY, 20, 20);
                    using (SolidBrush avaBg = new SolidBrush(Color.FromArgb(220, 38, 38)))
                    using (Font avaFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
                    {
                        g.FillEllipse(avaBg, avaRect);
                        using (StringFormat sf = new StringFormat { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center })
                        {
                            g.DrawString(authorInitial, avaFont, Brushes.White, new RectangleF(avaRect.X, avaRect.Y - 1, avaRect.Width, avaRect.Height), sf);
                        }
                    }

                    using (Font authFont = new Font("Segoe UI", 9.0f, FontStyle.Bold))
                    {
                        g.DrawString(authorName, authFont, new SolidBrush(Color.FromArgb(15, 23, 42)), calloutX + 26, calloutY + 1);
                    }

                    CommentBadgeHitRects[c.Id] = new Rectangle(calloutX, calloutY, 120, 24);
                }
            }
        }

        private void DrawReplyVectorIcon(D2DGraphics g, int x, int y, Color col)
        {
            using (Pen pBubble = new Pen(Color.FromArgb(100, 116, 139), 1.1f))
            using (Pen pArrow = new Pen(col, 1.4f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
            {
                PointF[] bub = new PointF[] {
                    new PointF(x, y),
                    new PointF(x + 13, y),
                    new PointF(x + 13, y + 9),
                    new PointF(x + 6, y + 9),
                    new PointF(x + 3, y + 13),
                    new PointF(x + 3, y + 9),
                    new PointF(x, y + 9)
                };
                g.DrawPolygon(pBubble, bub);
                g.DrawArc(pArrow, x + 4, y + 2, 5, 5, 270, 180);
                g.DrawLine(pArrow, x + 5, y + 2, x + 3, y + 4.5f);
                g.DrawLine(pArrow, x + 3, y + 4.5f, x + 5, y + 7);
            }
        }

        private void DrawResolveVectorIcon(D2DGraphics g, int x, int y, Color col)
        {
            using (Pen pBubble = new Pen(Color.FromArgb(100, 116, 139), 1.1f))
            using (Pen pCheck = new Pen(col, 1.5f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
            {
                PointF[] bub = new PointF[] {
                    new PointF(x, y),
                    new PointF(x + 13, y),
                    new PointF(x + 13, y + 9),
                    new PointF(x + 6, y + 9),
                    new PointF(x + 3, y + 13),
                    new PointF(x + 3, y + 9),
                    new PointF(x, y + 9)
                };
                g.DrawPolygon(pBubble, bub);
                g.DrawLine(pCheck, x + 3, y + 5, x + 6, y + 8);
                g.DrawLine(pCheck, x + 6, y + 8, x + 11, y + 2.5f);
            }
        }

        private void DrawPageCanvas(D2DGraphics g, int x, int y, int w, int h, RibbonBar ribbon, int pageNumber = 1, int totalPages = 1)
        {
            bool isEvenPage = (pageNumber % 2 == 0);

            Color pageBg = (ribbon != null) ? ribbon.PageBgColor : Color.White;
            using (SolidBrush bgBrush = new SolidBrush(pageBg))
            {
                g.FillRectangle(bgBrush, x, y, w, h);
            }
            using (Pen pageBorder = new Pen(Color.FromArgb(203, 213, 225), 1f))
            {
                g.DrawRectangle(pageBorder, x, y, w, h);
            }

            // Real Header & Footer Presets Rendering (Blank, Three Columns, Austin, Banded)
            if (CurrentHeaderPreset != HeaderFooterPreset.None || IsEditingHeaderFooter || !string.IsNullOrEmpty(HeaderText))
            {
                if (IsEditingHeaderFooter)
                {
                    // Dashed boundary line & Tag box [ Đầu trang ] ONLY WHEN EDITING!
                    int dashY = y + (int)(45 * ZoomLevel);
                    using (Pen dashPen = new Pen(Color.FromArgb(160, 160, 160), 1.0f))
                    {
                        dashPen.DashStyle = DashStyle.Dash;
                        g.DrawLine(dashPen, x, dashY, x + w, dashY);
                    }

                    Rectangle tagRect = new Rectangle(x + (int)(5 * ZoomLevel), dashY - (int)(13 * ZoomLevel), (int)(70 * ZoomLevel), (int)(18 * ZoomLevel));
                    g.FillRectangle(Brushes.White, tagRect);
                    g.DrawRectangle(Pens.LightGray, tagRect);
                    using (Font tagFont = new Font("Segoe UI", 8.0f))
                    {
                        g.DrawString("Đầu trang", tagFont, Brushes.DimGray, tagRect.X + 6, tagRect.Y + 1);
                    }
                }

                // Unified Header Text resolution across all presets
                string effHeaderPattern = HeaderText;
                int effHeaderAlign = HeaderAlignment;
                if (DifferentOddEvenPages && isEvenPage)
                {
                    effHeaderAlign = HeaderEvenAlignment;
                    if (!string.IsNullOrEmpty(HeaderEvenText)) effHeaderPattern = HeaderEvenText;
                }
                string hActiveStr = !string.IsNullOrEmpty(HeaderTitleText) ? HeaderTitleText : effHeaderPattern;

                int leftM = (int)Math.Round((ribbon != null ? ribbon.GetEffectiveLeftMarginInches() : 1.0f) * 96.0f * ZoomLevel);
                int rightM = (int)Math.Round((ribbon != null ? ribbon.GetEffectiveRightMarginInches() : 1.0f) * 96.0f * ZoomLevel);

                if (CurrentHeaderPreset == HeaderFooterPreset.Banded)
                {
                    if (HeaderWrapMode != 6)
                    {
                        DrawBandedHeaderBanner(g, x, y, w, h, ribbon);
                    }
                }
                else if (CurrentHeaderPreset == HeaderFooterPreset.Austin)
                {
                    string aStr = string.IsNullOrEmpty(hActiveStr) ? "[Tiêu đề tài liệu]" : hActiveStr;
                    using (Font aFont = new Font("Segoe UI", 9.5f * ZoomLevel, FontStyle.Bold))
                    {
                        SizeF sz = g.MeasureString(aStr, aFont);
                        float txtX = x + leftM;
                        float txtY = y + (int)(18 * ZoomLevel);

                        if (IsEditingHeaderFooter)
                        {
                            // Text box container frame
                            Rectangle textFrame = new Rectangle((int)txtX - 4, (int)txtY - 2, (int)Math.Max(150 * ZoomLevel, sz.Width + 12), (int)sz.Height + 4);
                            using (Pen dashPen = new Pen(Color.SteelBlue) { DashStyle = System.Drawing.Drawing2D.DashStyle.Dash })
                            {
                                g.DrawRectangle(dashPen, textFrame);
                            }

                            // Quét khối / Bôi đen background highlight
                            if (IsEditingHeaderMode && IsHeaderTextSelected)
                            {
                                using (SolidBrush selBrush = new SolidBrush(Color.FromArgb(197, 217, 241)))
                                {
                                    g.FillRectangle(selBrush, txtX, txtY, sz.Width, sz.Height);
                                }
                            }
                        }

                        g.DrawString(aStr, aFont, Brushes.DarkBlue, txtX, txtY);
                        g.DrawLine(Pens.LightGray, x + leftM, y + (int)(36 * ZoomLevel), x + w - rightM, y + (int)(36 * ZoomLevel));

                        if (IsEditingHeaderFooter && IsEditingHeaderMode && !IsHeaderTextSelected && CursorVisible)
                        {
                            float caretX = txtX + sz.Width + 2;
                            float caretY = txtY;
                            using (Pen blackCaret = new Pen(Color.Black, 1.0f) { StartCap = System.Drawing.Drawing2D.LineCap.Flat, EndCap = System.Drawing.Drawing2D.LineCap.Flat })
                            {
                                g.DrawLine(blackCaret, caretX, caretY, caretX, caretY + (int)(16 * ZoomLevel));
                            }
                        }
                    }
                }
                else if (CurrentHeaderPreset == HeaderFooterPreset.ThreeColumns)
                {
                    string cStr1 = string.IsNullOrEmpty(ThreeColHeaderLeft) ? "[Nhập tại đây]" : ThreeColHeaderLeft;
                    string cStr2 = string.IsNullOrEmpty(ThreeColHeaderCenter) ? "[Nhập tại đây]" : ThreeColHeaderCenter;
                    string cStr3 = string.IsNullOrEmpty(ThreeColHeaderRight) ? "[Nhập tại đây]" : ThreeColHeaderRight;

                    using (Font tFont = new Font("Segoe UI", 9.0f * ZoomLevel, FontStyle.Regular))
                    {
                        SizeF sz1 = g.MeasureString(cStr1, tFont);
                        SizeF sz2 = g.MeasureString(cStr2, tFont);
                        SizeF sz3 = g.MeasureString(cStr3, tFont);

                        float x1 = x + leftM;
                        float x2 = x + (w - sz2.Width) / 2;
                        float x3 = x + w - rightM - sz3.Width;
                        float txtY = y + (int)(20 * ZoomLevel);

                        if (IsEditingHeaderFooter)
                        {
                            using (Pen dashPen = new Pen(Color.LightGray) { DashStyle = System.Drawing.Drawing2D.DashStyle.Dash })
                            {
                                g.DrawRectangle(dashPen, (int)x1 - 4, (int)txtY - 2, (int)Math.Max(90 * ZoomLevel, sz1.Width + 8), (int)sz1.Height + 4);
                                g.DrawRectangle(dashPen, (int)x2 - 4, (int)txtY - 2, (int)Math.Max(90 * ZoomLevel, sz2.Width + 8), (int)sz2.Height + 4);
                                g.DrawRectangle(dashPen, (int)x3 - 4, (int)txtY - 2, (int)Math.Max(90 * ZoomLevel, sz3.Width + 8), (int)sz3.Height + 4);
                            }

                            if (IsEditingHeaderMode && IsHeaderTextSelected)
                            {
                                using (SolidBrush selBrush = new SolidBrush(Color.FromArgb(198, 198, 198)))
                                {
                                    if (ActiveThreeColIndex == 0) g.FillRectangle(selBrush, x1, txtY, sz1.Width, sz1.Height);
                                    else if (ActiveThreeColIndex == 1) g.FillRectangle(selBrush, x2, txtY, sz2.Width, sz2.Height);
                                    else if (ActiveThreeColIndex == 2) g.FillRectangle(selBrush, x3, txtY, sz3.Width, sz3.Height);
                                }
                            }
                        }

                        g.DrawString(cStr1, tFont, ActiveThreeColIndex == 0 && IsEditingHeaderFooter ? Brushes.Navy : Brushes.DimGray, x1, txtY);
                        g.DrawString(cStr2, tFont, ActiveThreeColIndex == 1 && IsEditingHeaderFooter ? Brushes.Navy : Brushes.DimGray, x2, txtY);
                        g.DrawString(cStr3, tFont, ActiveThreeColIndex == 2 && IsEditingHeaderFooter ? Brushes.Navy : Brushes.DimGray, x3, txtY);

                        if (IsEditingHeaderFooter && IsEditingHeaderMode && !IsHeaderTextSelected && CursorVisible)
                        {
                            float caretX = 0;
                            if (ActiveThreeColIndex == 0) caretX = x1 + sz1.Width + 2;
                            else if (ActiveThreeColIndex == 1) caretX = x2 + sz2.Width + 2;
                            else if (ActiveThreeColIndex == 2) caretX = x3 + sz3.Width + 2;

                            using (Pen blackCaret = new Pen(Color.Black, 1.0f) { StartCap = System.Drawing.Drawing2D.LineCap.Flat, EndCap = System.Drawing.Drawing2D.LineCap.Flat })
                            {
                                g.DrawLine(blackCaret, caretX, txtY, caretX, txtY + (int)(16 * ZoomLevel));
                            }
                        }
                    }
                }
                else if (CurrentHeaderPreset == HeaderFooterPreset.Blank || !string.IsNullOrEmpty(hActiveStr))
                {
                    string hStr = string.IsNullOrEmpty(hActiveStr) ? "[Nhập tại đây]" : hActiveStr;
                    string hFontName = !string.IsNullOrEmpty(HeaderFontName) ? HeaderFontName : "Times New Roman";
                    float hFontSize = (HeaderFontSize > 0 ? HeaderFontSize : 9.0f) * ZoomLevel;
                    FontStyle hStyle = FontStyle.Regular;
                    if (HeaderBold) hStyle |= FontStyle.Bold;
                    if (HeaderItalic) hStyle |= FontStyle.Italic;
                    Color hCol = (HeaderColor != Color.Empty && HeaderColor.A > 0) ? HeaderColor : Color.FromArgb(71, 85, 105);

                    using (Font hFont = new Font(hFontName, Math.Max(6.0f, hFontSize), hStyle))
                    using (SolidBrush hBrush = new SolidBrush(hCol))
                    {
                        SizeF sz = g.MeasureString(hStr, hFont);
                        float txtX = x + leftM;
                        if (effHeaderAlign == 1) txtX = x + (w - sz.Width) / 2.0f;
                        else if (effHeaderAlign == 2) txtX = x + w - rightM - sz.Width;

                        float txtY = y + (int)(18 * ZoomLevel);

                        if (IsEditingHeaderFooter)
                        {
                            using (Pen dashPen = new Pen(Color.LightGray) { DashStyle = System.Drawing.Drawing2D.DashStyle.Dash })
                            {
                                g.DrawRectangle(dashPen, (int)txtX - 4, (int)txtY - 2, (int)Math.Max(120 * ZoomLevel, sz.Width + 8), (int)sz.Height + 4);
                            }

                            if (IsEditingHeaderMode && IsHeaderTextSelected)
                            {
                                using (SolidBrush selBrush = new SolidBrush(Color.FromArgb(198, 198, 198)))
                                {
                                    g.FillRectangle(selBrush, txtX, txtY, sz.Width, sz.Height);
                                }
                            }
                        }

                        g.DrawString(hStr, hFont, hBrush, txtX, txtY);

                        if (IsEditingHeaderFooter && IsEditingHeaderMode && !IsHeaderTextSelected && CursorVisible)
                        {
                            float caretX = txtX + sz.Width + 2;
                            using (Pen blackCaret = new Pen(Color.Black, 1.0f) { StartCap = System.Drawing.Drawing2D.LineCap.Flat, EndCap = System.Drawing.Drawing2D.LineCap.Flat })
                            {
                                g.DrawLine(blackCaret, caretX, txtY, caretX, txtY + (int)(16 * ZoomLevel));
                            }
                        }
                    }
                }
            }

            // Render Footnotes for this page
            if (DetailedFootnotes != null && DetailedFootnotes.Count > 0)
            {
                List<FootnoteItem> pageFootnotes = new List<FootnoteItem>();
                foreach (var fn in DetailedFootnotes)
                {
                    if (!fn.IsEndnote && fn.PageNumber == pageNumber)
                    {
                        pageFootnotes.Add(fn);
                    }
                }

                if (pageFootnotes.Count > 0)
                {
                    int fnBottomY = y + h - (int)(55 * ZoomLevel);
                    int fnLineY = fnBottomY - (int)(pageFootnotes.Count * 18 * ZoomLevel) - (int)(8 * ZoomLevel);
                    int leftMargin = (int)((ribbon != null ? ribbon.GetEffectiveLeftMarginInches() : 1.0f) * 54.0f * ZoomLevel);
                    int fnX = x + Math.Max(20, leftMargin);

                    // 1. Footnote Separator Line (~5cm / 150px)
                    using (Pen fnSepPen = new Pen(Color.FromArgb(160, 174, 192), 1.2f))
                    {
                        g.DrawLine(fnSepPen, fnX, fnLineY, fnX + (int)(150 * ZoomLevel), fnLineY);
                    }

                    // 2. Footnote list items
                    int curFnY = fnLineY + (int)(6 * ZoomLevel);
                    using (Font fnFont = new Font("Segoe UI", 8.5f * ZoomLevel, FontStyle.Regular))
                    using (SolidBrush fnBrush = new SolidBrush(Color.FromArgb(51, 65, 85)))
                    {
                        foreach (var pfn in pageFootnotes)
                        {
                            string fnStr = string.Format("{0} {1}", pfn.Marker, pfn.Text);
                            g.DrawString(fnStr, fnFont, fnBrush, fnX, curFnY);
                            curFnY += (int)(18 * ZoomLevel);
                        }
                    }
                }

                // Render Endnotes on the last page of document
                if (pageNumber == totalPages)
                {
                    List<FootnoteItem> endnotes = new List<FootnoteItem>();
                    foreach (var fn in DetailedFootnotes)
                    {
                        if (fn.IsEndnote)
                        {
                            endnotes.Add(fn);
                        }
                    }

                    if (endnotes.Count > 0)
                    {
                        int leftMargin = (int)((ribbon != null ? ribbon.GetEffectiveLeftMarginInches() : 1.0f) * 54.0f * ZoomLevel);
                        int rightMargin = (int)((ribbon != null ? ribbon.GetEffectiveRightMarginInches() : 1.0f) * 54.0f * ZoomLevel);
                        int enX = x + Math.Max(20, leftMargin);
                        int enBottomY = y + h - (int)(58 * ZoomLevel);
                        int enLineY = enBottomY - (int)(endnotes.Count * 18 * ZoomLevel) - (int)(20 * ZoomLevel);

                        // Endnotes Section Separator Line
                        using (Pen enSepPen = new Pen(Color.FromArgb(99, 102, 241), 1.5f))
                        {
                            g.DrawLine(enSepPen, enX, enLineY, x + w - Math.Max(20, rightMargin), enLineY);
                        }

                        using (Font hdrFont = new Font("Segoe UI", 7.5f * ZoomLevel, FontStyle.Bold))
                        using (SolidBrush hdrBrush = new SolidBrush(Color.FromArgb(99, 102, 241)))
                        {
                            g.DrawString("CHÚ THÍCH CUỐI TÀI LIỆU (ENDNOTES)", hdrFont, hdrBrush, enX, enLineY - (int)(14 * ZoomLevel));
                        }

                        int curEnY = enLineY + (int)(6 * ZoomLevel);
                        using (Font enFont = new Font("Segoe UI", 8.5f * ZoomLevel, FontStyle.Regular))
                        using (SolidBrush enBrush = new SolidBrush(Color.FromArgb(51, 65, 85)))
                        {
                            foreach (var pen in endnotes)
                            {
                                string enStr = string.Format("{0} {1}", pen.Marker, pen.Text);
                                g.DrawString(enStr, enFont, enBrush, enX, curEnY);
                                curEnY += (int)(18 * ZoomLevel);
                            }
                        }
                    }
                }
            }

            // Real Footer rendering
            if (CurrentFooterPreset != HeaderFooterPreset.None || ShowPageNumbers || !string.IsNullOrEmpty(FooterText))
            {
                if (IsEditingHeaderFooter)
                {
                    // Dashed boundary line & Tag box [ Chân trang ] ONLY WHEN EDITING!
                    using (Pen dashPen = new Pen(Color.FromArgb(160, 160, 160), 1))
                    {
                        dashPen.DashStyle = DashStyle.Dash;
                        g.DrawLine(dashPen, x, y + h - 45, x + w, y + h - 45);
                    }

                    Rectangle fTagRect = new Rectangle(x + 5, y + h - 45, 70, 18);
                    g.FillRectangle(Brushes.White, fTagRect);
                    g.DrawRectangle(Pens.LightGray, fTagRect);
                    using (Font tagFont = new Font("Segoe UI", 8.0f))
                    {
                        g.DrawString("Chân trang", tagFont, Brushes.DimGray, fTagRect.X + 6, fTagRect.Y + 1);
                    }
                }

                if (CurrentFooterPreset == HeaderFooterPreset.Banded)
                {
                    int effBandedAlign = FooterAlignment;
                    if (DifferentOddEvenPages || effBandedAlign == 3)
                    {
                        effBandedAlign = isEvenPage ? 0 : 2; // "2 bên": Even on left, Odd on right
                    }
                    int leftM = (int)Math.Round((ribbon != null ? ribbon.GetEffectiveLeftMarginInches() : 1.0f) * 96.0f * ZoomLevel);
                    int rightM = (int)Math.Round((ribbon != null ? ribbon.GetEffectiveRightMarginInches() : 1.0f) * 96.0f * ZoomLevel);
                    string pgStr = FormatPageNumber(pageNumber, PageNumberFormat, PageNumberStart);
                    using (Font fFont = new Font("Segoe UI", 9.0f * ZoomLevel, FontStyle.Bold))
                    {
                        SizeF sz = g.MeasureString(pgStr, fFont);
                        float bX = x + (w - sz.Width) / 2.0f;
                        if (effBandedAlign == 0) bX = x + leftM;
                        else if (effBandedAlign == 2) bX = x + w - rightM - sz.Width;
                        g.DrawString(pgStr, fFont, Brushes.DarkBlue, bX, y + h - 30);
                    }
                }
                else if (CurrentFooterPreset == HeaderFooterPreset.Austin)
                {
                    string pgStr = FormatPageNumber(pageNumber, PageNumberFormat, PageNumberStart);
                    using (Font fFont = new Font("Segoe UI", 9.0f * ZoomLevel, FontStyle.Bold))
                    {
                        g.DrawString("PAGE " + pgStr, fFont, Brushes.DarkBlue, x + 40, y + h - 30);
                    }
                }
                else if (CurrentFooterPreset == HeaderFooterPreset.ThreeColumns)
                {
                    using (Font tFont = new Font("Segoe UI", 9.0f * ZoomLevel, FontStyle.Regular))
                    {
                        g.DrawString("[Type here]", tFont, Brushes.DimGray, x + 40, y + h - 30);
                        g.DrawString("[Type here]", tFont, Brushes.DimGray, x + w / 2 - 30, y + h - 30);
                        g.DrawString("[Type here]", tFont, Brushes.DimGray, x + w - 100, y + h - 30);
                    }
                }
                else if (CurrentFooterPreset == HeaderFooterPreset.Blank || !string.IsNullOrEmpty(FooterText) || !string.IsNullOrEmpty(FooterEvenText) || ShowPageNumbers)
                {
                    int effFooterAlign = FooterAlignment;
                    string effFooterPattern = FooterText;
                    if (DifferentOddEvenPages)
                    {
                        if (isEvenPage)
                        {
                            effFooterAlign = FooterEvenAlignment; // default 0 (Left)
                            if (!string.IsNullOrEmpty(FooterEvenText)) effFooterPattern = FooterEvenText;
                        }
                        else
                        {
                            effFooterAlign = (FooterAlignment == 1 || FooterAlignment == 3) ? 2 : FooterAlignment; // default 2 (Right)
                        }
                    }
                    else if (effFooterAlign == 3) // 3 = "Hai bên / 2 bên"
                    {
                        effFooterAlign = isEvenPage ? 0 : 2;
                    }

                    string formattedPage = FormatPageNumber(pageNumber, PageNumberFormat, PageNumberStart);
                    string fStr;
                    if (!string.IsNullOrEmpty(effFooterPattern))
                    {
                        if (effFooterPattern.Contains("{PAGE}") || effFooterPattern.Contains("{NUMPAGES}"))
                        {
                            fStr = effFooterPattern.Replace("{PAGE}", formattedPage).Replace("{NUMPAGES}", totalPages.ToString());
                        }
                        else if (ShowPageNumbers)
                        {
                            fStr = effFooterPattern + "  " + formattedPage;
                        }
                        else
                        {
                            fStr = effFooterPattern;
                        }
                    }
                    else if (ShowPageNumbers)
                    {
                        fStr = formattedPage;
                    }
                    else
                    {
                        fStr = "[Nhập tại đây]";
                    }

                    string fFontFamily = !string.IsNullOrEmpty(FooterFontName) ? FooterFontName : "Times New Roman";
                    float fFontSize = (FooterFontSize > 0 ? FooterFontSize : 9.0f) * ZoomLevel;
                    FontStyle fStyle = FontStyle.Regular;
                    if (FooterBold) fStyle |= FontStyle.Bold;
                    if (FooterItalic) fStyle |= FontStyle.Italic;
                    Color fCol = (FooterColor != Color.Empty && FooterColor.A > 0) ? FooterColor : Color.FromArgb(71, 85, 105);

                    using (Font fFont = new Font(fFontFamily, Math.Max(6.0f, fFontSize), fStyle))
                    using (SolidBrush fBrush = new SolidBrush(fCol))
                    {
                        int leftM = (int)Math.Round((ribbon != null ? ribbon.GetEffectiveLeftMarginInches() : 1.0f) * 96.0f * ZoomLevel);
                        int rightM = (int)Math.Round((ribbon != null ? ribbon.GetEffectiveRightMarginInches() : 1.0f) * 96.0f * ZoomLevel);
                        SizeF sz = g.MeasureString(fStr, fFont);
                        float txtX = x + leftM;
                        if (effFooterAlign == 1) txtX = x + (w - sz.Width) / 2.0f;
                        else if (effFooterAlign == 2) txtX = x + w - rightM - sz.Width;

                        float txtY = y + h - (int)(32 * ZoomLevel);
                        g.DrawString(fStr, fFont, fBrush, txtX, txtY);
                    }
                }
            }

            if (ribbon != null && ribbon.HasPageBorder)
            {
                using (Pen borderPen = new Pen(ribbon.PageBorderColor, Math.Max(1.0f, ribbon.PageBorderWidth * ZoomLevel)))
                {
                    if (ribbon.PageBorderStyleType == 2) // Shadow
                    {
                        using (SolidBrush shB = new SolidBrush(Color.FromArgb(100, 120, 120, 120)))
                        {
                            g.FillRectangle(shB, x + 16, y + h - 10, w - 20, 5);
                            g.FillRectangle(shB, x + w - 10, y + 16, 5, h - 20);
                        }
                    }
                    g.DrawRectangle(borderPen, x + 8, y + 8, w - 16, h - 16);
                    if (ribbon.PageBorderStyleType == 3 || ribbon.PageBorderStyleType == 4) // 3-D / Double
                    {
                        g.DrawRectangle(borderPen, x + 12, y + 12, w - 24, h - 24);
                    }
                }
            }

            // Document Gridlines (Lưới căn chỉnh ô vuông trang giấy chuẩn Word)
            bool effGrid = ShowDocumentGridlines || (ribbon != null && ribbon.ShowGridlines);
            if (effGrid)
            {
                int leftM = (int)Math.Round((ribbon != null ? ribbon.GetEffectiveLeftMarginInches() : 1.0f) * 96.0f * ZoomLevel);
                int rightM = (int)Math.Round((ribbon != null ? ribbon.GetEffectiveRightMarginInches() : 1.0f) * 96.0f * ZoomLevel);
                int topM = (int)Math.Round((ribbon != null ? ribbon.GetEffectiveTopMarginInches() : 1.0f) * 96.0f * ZoomLevel);
                int botM = (int)Math.Round((ribbon != null ? ribbon.GetEffectiveBottomMarginInches() : 1.0f) * 96.0f * ZoomLevel);

                int gridX1 = x + leftM;
                int gridX2 = x + w - rightM;
                int gridY1 = y + topM;
                int gridY2 = y + h - botM;

                if (gridX2 > gridX1 && gridY2 > gridY1)
                {
                    float cellSize = 18.0f * ZoomLevel;
                    using (Pen gridPen = new Pen(Color.FromArgb(226, 232, 240), 1.0f) { DashStyle = DashStyle.Dot })
                    {
                        for (float gx = gridX1; gx <= gridX2; gx += cellSize)
                        {
                            g.DrawLine(gridPen, gx, gridY1, gx, gridY2);
                        }
                        for (float gy = gridY1; gy <= gridY2; gy += cellSize)
                        {
                            g.DrawLine(gridPen, gridX1, gy, gridX2, gy);
                        }
                    }
                }
            }

            Image effWmImg = WatermarkImage ?? (ribbon != null ? ribbon.WatermarkImage : null);
            if (effWmImg != null)
            {
                GraphicsState state = g.Save();
                g.SetClip(new Rectangle(x, y, w, h));

                float scale = (WatermarkImageScale > 0) ? WatermarkImageScale : (ribbon != null && ribbon.WatermarkImageScale > 0 ? ribbon.WatermarkImageScale : 0f);
                bool washout = (ribbon != null) ? ribbon.WatermarkWashout : WatermarkWashout;

                float imgW, imgH;
                if (scale > 0)
                {
                    imgW = effWmImg.Width * scale * ZoomLevel;
                    imgH = effWmImg.Height * scale * ZoomLevel;
                }
                else
                {
                    float maxW = w * 0.70f;
                    float maxH = h * 0.70f;
                    float ratio = Math.Min(maxW / Math.Max(1, effWmImg.Width), maxH / Math.Max(1, effWmImg.Height));
                    imgW = effWmImg.Width * ratio;
                    imgH = effWmImg.Height * ratio;
                }

                float drawX = x + (w - imgW) / 2f;
                float drawY = y + (h - imgH) / 2f;

                float alpha = washout ? 0.22f : 0.85f;
                using (System.Drawing.Imaging.ImageAttributes ia = new System.Drawing.Imaging.ImageAttributes())
                {
                    System.Drawing.Imaging.ColorMatrix cm = new System.Drawing.Imaging.ColorMatrix();
                    cm.Matrix33 = alpha;
                    if (washout)
                    {
                        cm.Matrix00 = 0.8f; cm.Matrix11 = 0.8f; cm.Matrix22 = 0.8f;
                        cm.Matrix40 = 0.2f; cm.Matrix41 = 0.2f; cm.Matrix42 = 0.2f;
                    }
                    ia.SetColorMatrix(cm, System.Drawing.Imaging.ColorMatrixFlag.Default, System.Drawing.Imaging.ColorAdjustType.Bitmap);
                    g.DrawImage(effWmImg, new Rectangle((int)drawX, (int)drawY, (int)imgW, (int)imgH), 0, 0, effWmImg.Width, effWmImg.Height, GraphicsUnit.Pixel, ia);
                }
                g.Restore(state);
            }

            if (ribbon != null && !string.IsNullOrEmpty(ribbon.WatermarkText))
            {
                GraphicsState state = g.Save();
                g.SetClip(new Rectangle(x, y, w, h));

                float baseFontSize = (ribbon.WatermarkIsDiagonal ? 50.0f : 44.0f) * ZoomLevel;
                float maxAvailableW = ribbon.WatermarkIsDiagonal ? (float)Math.Sqrt(w * w + h * h) * 0.72f : (w * 0.82f);

                using (Font testFont = new Font("Arial", baseFontSize, FontStyle.Bold))
                {
                    SizeF measuredSz = g.MeasureString(ribbon.WatermarkText, testFont);
                    float finalFontSize = baseFontSize;
                    if (measuredSz.Width > maxAvailableW && measuredSz.Width > 0)
                    {
                        finalFontSize = Math.Max(12.0f * ZoomLevel, baseFontSize * (maxAvailableW / measuredSz.Width));
                    }

                    using (Font wmFont = new Font("Arial", finalFontSize, FontStyle.Bold))
                    using (SolidBrush wmBrush = new SolidBrush(Color.FromArgb(38, 120, 120, 120)))
                    {
                        g.TranslateTransform(x + w / 2f, y + h / 2f);
                        if (ribbon.WatermarkIsDiagonal)
                        {
                            g.RotateTransform(-45f);
                        }
                        SizeF sz = g.MeasureString(ribbon.WatermarkText, wmFont);
                        g.DrawString(ribbon.WatermarkText, wmFont, wmBrush, -sz.Width / 2f, -sz.Height / 2f);
                    }
                }
                g.Restore(state);
            }

            // Live Ghost Table Insert Preview Overlay
            if (TablePreviewCols > 0 && TablePreviewRows > 0)
            {
                int cols = TablePreviewCols;
                int rows = TablePreviewRows;

                int leftM = (int)(ribbon.GetEffectiveLeftMarginInches() * 72.0f * ZoomLevel);
                int rightM = (int)(ribbon.GetEffectiveRightMarginInches() * 72.0f * ZoomLevel);
                int topM = (int)(ribbon.GetEffectiveTopMarginInches() * 72.0f * ZoomLevel);

                float tw = w - leftM - rightM;
                float th = Math.Min(h * 0.40f, rows * (28f * ZoomLevel));
                float tx = x + leftM;
                float ty = y + topM + (int)(90 * ZoomLevel);

                float cellW = tw / cols;
                float cellH = th / rows;

                using (SolidBrush headerTopBrush = new SolidBrush(Color.FromArgb(170, 37, 99, 235)))
                using (SolidBrush rowOddBrush = new SolidBrush(Color.FromArgb(120, 219, 234, 254)))
                using (SolidBrush rowEvenBrush = new SolidBrush(Color.FromArgb(90, 255, 255, 255)))
                using (Pen gridPen = new Pen(Color.FromArgb(200, 37, 99, 235), 1.2f))
                using (Pen outerPen = new Pen(Color.FromArgb(240, 29, 78, 216), 2.0f))
                {
                    g.FillRectangle(headerTopBrush, tx, ty, tw, cellH);
                    for (int r = 1; r < rows; r++)
                    {
                        SolidBrush b = (r % 2 == 1) ? rowOddBrush : rowEvenBrush;
                        g.FillRectangle(b, tx, ty + r * cellH, tw, cellH);
                    }
                    for (int r = 0; r <= rows; r++)
                    {
                        g.DrawLine(gridPen, tx, ty + r * cellH, tx + tw, ty + r * cellH);
                    }
                    for (int c = 0; c <= cols; c++)
                    {
                        g.DrawLine(gridPen, tx + c * cellW, ty, tx + c * cellW, ty + th);
                    }
                    g.DrawRectangle(outerPen, tx, ty, tw, th);
                }
            }
        }

        private void DrawBandedHeaderBanner(D2DGraphics g, int x, int y, int w, int h, RibbonBar ribbon)
        {
            int leftM = (int)(ribbon.GetEffectiveLeftMarginInches() * 54.0f * ZoomLevel);
            int rightM = (int)(ribbon.GetEffectiveRightMarginInches() * 54.0f * ZoomLevel);
            int bX = x + leftM + (int)(HeaderBannerXOffset * ZoomLevel);
            int bW = Math.Max((int)(50 * ZoomLevel), w - leftM - rightM + (int)(HeaderBannerWidthDelta * ZoomLevel));
            int bH = Math.Max((int)(16 * ZoomLevel), (int)(28 * ZoomLevel) + (int)(HeaderBannerHeightDelta * ZoomLevel));
            int bY = y + (int)(10 * ZoomLevel) + (int)(HeaderBannerYOffset * ZoomLevel);
            Rectangle bannerRect = new Rectangle(bX, bY, bW, bH);

            // 100% Solid Opaque Blue Banner (Màu đặc nguyên bản, phẳng và không shadow)
            using (SolidBrush bannerBrush = new SolidBrush(Color.FromArgb(67, 120, 195)))
            {
                g.FillRectangle(bannerBrush, bannerRect);
            }

            string hActiveStr = !string.IsNullOrEmpty(HeaderTitleText) ? HeaderTitleText : HeaderText;
            string tStr = string.IsNullOrEmpty(hActiveStr) ? "TIÊU ĐỀ ĐẦU TRANG" : hActiveStr;
            using (Font titleFont = new Font("Segoe UI", 10.0f * ZoomLevel, FontStyle.Bold))
            {
                SizeF sz = g.MeasureString(tStr, titleFont);
                float txtX = bannerRect.X + (bannerRect.Width - sz.Width) / 2;
                float txtY = bannerRect.Y + (bannerRect.Height - sz.Height) / 2;

                if (IsEditingHeaderFooter)
                {
                    // Draw Text Box Container Frame around text inside banner
                    Rectangle textFrame = new Rectangle((int)txtX - 6, (int)txtY - 2, (int)sz.Width + 12, (int)sz.Height + 4);
                    using (Pen dashPen = new Pen(Color.FromArgb(200, 255, 255, 255)) { DashStyle = System.Drawing.Drawing2D.DashStyle.Dash })
                    {
                        g.DrawRectangle(dashPen, textFrame);
                    }

                    // Quét khối / bôi đen text selection background if selected
                    if (IsEditingHeaderMode && IsHeaderTextSelected)
                    {
                        using (SolidBrush selBrush = new SolidBrush(Color.FromArgb(140, 0, 45, 125)))
                        {
                            g.FillRectangle(selBrush, txtX, txtY, sz.Width, sz.Height);
                        }
                    }
                }

                g.DrawString(tStr, titleFont, Brushes.White, txtX, txtY);

                // Blinking Caret Indicator in Header Banner (only when not auto-selected)
                if (IsEditingHeaderFooter && IsEditingHeaderMode && !IsHeaderTextSelected && CursorVisible)
                {
                    float caretX = txtX + sz.Width + 2;
                    using (Pen whiteCaret = new Pen(Color.White, 1.0f) { StartCap = System.Drawing.Drawing2D.LineCap.Flat, EndCap = System.Drawing.Drawing2D.LineCap.Flat })
                    {
                        g.DrawLine(whiteCaret, caretX, txtY, caretX, txtY + sz.Height);
                    }
                }
            }

            // Selection handle dots & Title tag & Layout button
            if (IsEditingHeaderFooter)
            {
                g.DrawRectangle(Pens.White, bannerRect);
                Rectangle handleTag = new Rectangle(bannerRect.X + bannerRect.Width / 2 - 30, bannerRect.Y - 14, 60, 14);
                g.FillRectangle(Brushes.White, handleTag);
                g.DrawRectangle(Pens.Gray, handleTag);
                using (Font hfTagFont = new Font("Segoe UI", 7.5f))
                {
                    g.DrawString(":: Tiêu đề", hfTagFont, Brushes.DimGray, handleTag.X + 4, handleTag.Y);
                }

                // 8 White Circular Selection Handles around banner
                Point[] handlePts = new Point[]
                {
                    new Point(bannerRect.Left, bannerRect.Top),
                    new Point(bannerRect.Left + bannerRect.Width / 2, bannerRect.Top),
                    new Point(bannerRect.Right, bannerRect.Top),
                    new Point(bannerRect.Left, bannerRect.Top + bannerRect.Height / 2),
                    new Point(bannerRect.Right, bannerRect.Top + bannerRect.Height / 2),
                    new Point(bannerRect.Left, bannerRect.Bottom),
                    new Point(bannerRect.Left + bannerRect.Width / 2, bannerRect.Bottom),
                    new Point(bannerRect.Right, bannerRect.Bottom)
                };
                for (int hIdx = 0; hIdx < 8; hIdx++)
                {
                    Rectangle handleCircle = new Rectangle(handlePts[hIdx].X - 4, handlePts[hIdx].Y - 4, 8, 8);
                    g.FillEllipse(Brushes.White, handleCircle);
                    g.DrawEllipse(Pens.RoyalBlue, handleCircle);
                }

                // Top rotation handle circular icon 🔄
                Rectangle rotateHandle = new Rectangle(bannerRect.Left + bannerRect.Width / 2 - 8, bannerRect.Top - 26, 16, 16);
                g.FillEllipse(Brushes.White, rotateHandle);
                g.DrawEllipse(Pens.DimGray, rotateHandle);
                using (Font rFont = new Font("Segoe UI Symbol", 8f))
                {
                    g.DrawString("🔄", rFont, Brushes.DarkSlateGray, rotateHandle.X + 1, rotateHandle.Y + 1);
                }

                // Layout Options Button [ ⌒ ] (Top-Right)
                Rectangle wrapBtnRect = new Rectangle(bannerRect.Right + 4, bannerRect.Top, 22, 22);
                using (SolidBrush wBtnBg = new SolidBrush(Color.FromArgb(245, 247, 250)))
                using (Pen wBtnPen = new Pen(Color.FromArgb(180, 195, 210), 1.0f))
                {
                    g.FillRectangle(wBtnBg, wrapBtnRect);
                    g.DrawRectangle(wBtnPen, wrapBtnRect);
                    g.DrawLine(Pens.DimGray, wrapBtnRect.X + 3, wrapBtnRect.Y + 4, wrapBtnRect.X + 19, wrapBtnRect.Y + 4);
                    g.DrawArc(new Pen(Color.SteelBlue, 1.5f), wrapBtnRect.X + 5, wrapBtnRect.Y + 6, 12, 10, 180, 180);
                    g.DrawLine(Pens.DimGray, wrapBtnRect.X + 3, wrapBtnRect.Y + 17, wrapBtnRect.X + 19, wrapBtnRect.Y + 17);
                }

                // Smart Alignment Green Guide Lines (Đường gióng căn chỉnh màu xanh lá cây chuẩn MS Word)
                if (IsDraggingHeaderBanner || IsResizingHeaderBanner)
                {
                    using (Pen greenGuidePen = new Pen(Color.FromArgb(34, 197, 94), 1.2f))
                    {
                        int leftMarginLineX = x + leftM;
                        int rightMarginLineX = x + w - rightM;
                        int pageCenterX = x + w / 2;
                        int topGuidelineY = y + (int)(45 * ZoomLevel);

                        // Left margin guide line
                        if (Math.Abs(bannerRect.Left - leftMarginLineX) <= 3)
                        {
                            g.DrawLine(greenGuidePen, leftMarginLineX, y, leftMarginLineX, y + h);
                        }

                        // Center alignment guide line
                        if (Math.Abs((bannerRect.Left + bannerRect.Right) / 2 - pageCenterX) <= 3)
                        {
                            g.DrawLine(greenGuidePen, pageCenterX, y, pageCenterX, y + h);
                        }

                        // Right margin guide line
                        if (Math.Abs(bannerRect.Right - rightMarginLineX) <= 3)
                        {
                            g.DrawLine(greenGuidePen, rightMarginLineX, y, rightMarginLineX, y + h);
                        }

                        // Top header boundary guide line
                        if (Math.Abs(bannerRect.Top - (y + (int)(10 * ZoomLevel))) <= 3 || Math.Abs(bannerRect.Bottom - topGuidelineY) <= 3)
                        {
                            g.DrawLine(greenGuidePen, x, topGuidelineY, x + w, topGuidelineY);
                        }
                    }
                }
            }
        }

        private void DrawVectorArch(D2DGraphics g, Pen archPen, float x, float y, float w, float h)
        {
            if (g == null || archPen == null) return;
            g.DrawArc(archPen, x, y, w, h, 180, 180);
            g.DrawLine(archPen, x, y + h / 2, x + w, y + h / 2);
        }

        private void DrawVectorWrapCard(D2DGraphics g, int wrapMode, Rectangle box, bool isSelected)
        {
            if (isSelected)
            {
                using (SolidBrush selBg = new SolidBrush(Color.FromArgb(215, 220, 225)))
                {
                    g.FillRectangle(selBg, box);
                }
                using (Pen selBorder = new Pen(Color.FromArgb(120, 125, 130), 1.2f))
                {
                    g.DrawRectangle(selBorder, box);
                }
            }
            else
            {
                using (Pen borderPen = new Pen(Color.FromArgb(218, 224, 230), 1.0f))
                {
                    g.DrawRectangle(borderPen, box);
                }
            }

            using (Pen bluePen = new Pen(Color.FromArgb(0, 120, 215), 1.6f))
            using (Pen darkArchPen = new Pen(Color.FromArgb(40, 40, 40), 3.0f))
            using (Pen ghostArchPen = new Pen(Color.FromArgb(180, 185, 192), 3.0f))
            {
                float archX = box.X + (box.Width - 14) / 2.0f;
                float archY = box.Y + (box.Height - 12) / 2.0f + 1;

                if (wrapMode == 0) // In Line With Text
                {
                    float ax = box.X + 6;
                    float ay = box.Y + 12;
                    g.DrawLine(bluePen, box.X + 5, box.Y + 7, box.X + 22, box.Y + 7);
                    DrawVectorArch(g, darkArchPen, ax, ay, 13, 12);
                    g.DrawLine(bluePen, box.X + 22, box.Y + 17, box.X + 36, box.Y + 17);
                    g.DrawLine(bluePen, box.X + 5, box.Y + 26, box.X + 36, box.Y + 26);
                }
                else if (wrapMode == 1) // Square (Vuông)
                {
                    g.DrawLine(bluePen, box.X + 5, box.Y + 6, box.X + 37, box.Y + 6);
                    g.DrawLine(bluePen, box.X + 5, box.Y + 13, box.X + 11, box.Y + 13);
                    g.DrawLine(bluePen, box.X + 31, box.Y + 13, box.X + 37, box.Y + 13);
                    g.DrawLine(bluePen, box.X + 5, box.Y + 20, box.X + 11, box.Y + 20);
                    g.DrawLine(bluePen, box.X + 31, box.Y + 20, box.X + 37, box.Y + 20);
                    g.DrawLine(bluePen, box.X + 5, box.Y + 27, box.X + 37, box.Y + 27);
                    DrawVectorArch(g, darkArchPen, archX, archY, 13, 12);
                }
                else if (wrapMode == 2) // Tight (Chặt)
                {
                    g.DrawLine(bluePen, box.X + 5, box.Y + 6, box.X + 37, box.Y + 6);
                    g.DrawLine(bluePen, box.X + 5, box.Y + 13, box.X + 12, box.Y + 13);
                    g.DrawLine(bluePen, box.X + 30, box.Y + 13, box.X + 37, box.Y + 13);
                    g.DrawLine(bluePen, box.X + 5, box.Y + 20, box.X + 11, box.Y + 20);
                    g.DrawLine(bluePen, box.X + 31, box.Y + 20, box.X + 37, box.Y + 20);
                    g.DrawLine(bluePen, box.X + 5, box.Y + 27, box.X + 37, box.Y + 27);
                    DrawVectorArch(g, darkArchPen, archX, archY, 13, 12);
                }
                else if (wrapMode == 3) // Through (Xuyên qua)
                {
                    g.DrawLine(bluePen, box.X + 5, box.Y + 6, box.X + 37, box.Y + 6);
                    g.DrawLine(bluePen, box.X + 5, box.Y + 13, box.X + 13, box.Y + 13);
                    g.DrawLine(bluePen, box.X + 29, box.Y + 13, box.X + 37, box.Y + 13);
                    g.DrawLine(bluePen, box.X + 5, box.Y + 20, box.X + 11, box.Y + 20);
                    g.DrawLine(bluePen, box.X + 31, box.Y + 20, box.X + 37, box.Y + 20);
                    g.DrawLine(bluePen, box.X + 5, box.Y + 27, box.X + 37, box.Y + 27);
                    DrawVectorArch(g, darkArchPen, archX, archY, 13, 12);
                }
                else if (wrapMode == 4) // Top and Bottom (Trên và Dưới)
                {
                    g.DrawLine(bluePen, box.X + 5, box.Y + 6, box.X + 37, box.Y + 6);
                    g.DrawLine(bluePen, box.X + 5, box.Y + 27, box.X + 37, box.Y + 27);
                    DrawVectorArch(g, darkArchPen, archX, archY, 13, 12);
                }
                else if (wrapMode == 5) // Behind Text (Dưới văn bản)
                {
                    DrawVectorArch(g, ghostArchPen, archX, archY, 13, 12);
                    g.DrawLine(bluePen, box.X + 5, box.Y + 6, box.X + 37, box.Y + 6);
                    g.DrawLine(bluePen, box.X + 5, box.Y + 13, box.X + 37, box.Y + 13);
                    g.DrawLine(bluePen, box.X + 5, box.Y + 20, box.X + 37, box.Y + 20);
                    g.DrawLine(bluePen, box.X + 5, box.Y + 27, box.X + 37, box.Y + 27);
                }
                else if (wrapMode == 6) // In Front of Text (Trước văn bản)
                {
                    g.DrawLine(bluePen, box.X + 5, box.Y + 6, box.X + 37, box.Y + 6);
                    g.DrawLine(bluePen, box.X + 5, box.Y + 13, box.X + 37, box.Y + 13);
                    g.DrawLine(bluePen, box.X + 5, box.Y + 20, box.X + 37, box.Y + 20);
                    g.DrawLine(bluePen, box.X + 5, box.Y + 27, box.X + 37, box.Y + 27);
                    DrawVectorArch(g, darkArchPen, archX, archY, 13, 12);
                }
            }
        }

        private void DrawVectorRadioButton(D2DGraphics g, int x, int y, bool isChecked, string label, Font font)
        {
            Rectangle rCircle = new Rectangle(x, y + 2, 12, 12);
            using (Pen rPen = new Pen(isChecked ? Color.FromArgb(0, 120, 215) : Color.FromArgb(140, 145, 150), 1.2f))
            {
                g.DrawEllipse(rPen, rCircle);
                if (isChecked)
                {
                    using (SolidBrush dotBrush = new SolidBrush(Color.FromArgb(0, 120, 215)))
                    {
                        g.FillEllipse(dotBrush, x + 3, y + 5, 6, 6);
                    }
                }
            }
            g.DrawString(label, font, isChecked ? new SolidBrush(Color.FromArgb(20, 20, 20)) : new SolidBrush(Color.FromArgb(70, 70, 70)), x + 16, y);
        }

        private void DrawVectorInfoIcon(D2DGraphics g, int x, int y)
        {
            Rectangle infoCircle = new Rectangle(x, y, 11, 11);
            using (Pen infoPen = new Pen(Color.FromArgb(0, 120, 215), 1.0f))
            using (Font iFont = new Font("Segoe UI", 6.5f, FontStyle.Bold))
            {
                g.DrawEllipse(infoPen, infoCircle);
                g.DrawString("i", iFont, new SolidBrush(Color.FromArgb(0, 120, 215)), x + 2.5f, y - 0.5f);
            }
        }

        public void DrawDocumentChart(D2DGraphics g, DocChartObject chart, int chartX, int chartY, int chartW, int chartH, RibbonBar ribbon)
        {
            chart.LastBounds = new Rectangle(chartX, chartY, chartW, chartH);
            ActiveChartLastBounds = chart.LastBounds;

            Color bgColor = Color.White;
            Color borderColor = Color.FromArgb(218, 224, 233);
            Color textCol = Color.FromArgb(40, 40, 40);
            Color gridCol = Color.FromArgb(235, 238, 242);

            if (chart.StyleThemeIndex == 1) // Dark Slate Theme
            {
                bgColor = Color.FromArgb(30, 41, 59);
                borderColor = Color.FromArgb(51, 65, 85);
                textCol = Color.White;
                gridCol = Color.FromArgb(51, 65, 85);
            }
            else if (chart.StyleThemeIndex == 2) // Soft Modern Gray
            {
                bgColor = Color.FromArgb(248, 250, 252);
                borderColor = Color.FromArgb(203, 213, 225);
                textCol = Color.FromArgb(30, 41, 59);
                gridCol = Color.FromArgb(226, 232, 240);
            }

            using (SolidBrush bgB = new SolidBrush(bgColor))
            using (Pen borderP = new Pen(borderColor, 1.2f))
            {
                g.FillRectangle(bgB, chartX, chartY, chartW, chartH);
                g.DrawRectangle(borderP, chartX, chartY, chartW, chartH);
            }

            // Title Box
            int titleH = 0;
            if (chart.ShowTitle && !string.IsNullOrEmpty(chart.Data.Title))
            {
                using (Font tFont = new Font("Segoe UI", 10.5f * ZoomLevel, FontStyle.Bold))
                using (SolidBrush tBrush = new SolidBrush(textCol))
                {
                    SizeF tSz = g.MeasureString(chart.Data.Title, tFont);
                    float tx = chartX + (chartW - tSz.Width) / 2;
                    float ty = chartY + (int)(8 * ZoomLevel);
                    g.DrawString(chart.Data.Title, tFont, tBrush, tx, ty);
                    titleH = (int)(tSz.Height + 10 * ZoomLevel);

                    if (chart.IsSelected)
                    {
                        Rectangle tBox = new Rectangle((int)tx - 4, (int)ty - 2, (int)tSz.Width + 8, (int)tSz.Height + 4);
                        using (Pen dashPen = new Pen(Color.FromArgb(120, 180, 240)) { DashStyle = DashStyle.Dash })
                        {
                            g.DrawRectangle(dashPen, tBox);
                        }
                    }
                }
            }
            else
            {
                titleH = (int)(12 * ZoomLevel);
            }

            // Color Palettes
            Color[][] palettes = new Color[][]
            {
                new Color[] { Color.FromArgb(68, 114, 196), Color.FromArgb(237, 125, 49), Color.FromArgb(165, 165, 165), Color.FromArgb(255, 192, 0), Color.FromArgb(112, 173, 71), Color.FromArgb(91, 155, 213) },
                new Color[] { Color.FromArgb(112, 48, 160), Color.FromArgb(0, 176, 240), Color.FromArgb(0, 176, 80), Color.FromArgb(255, 192, 0), Color.FromArgb(192, 0, 0), Color.FromArgb(237, 125, 49) },
                new Color[] { Color.FromArgb(31, 78, 120), Color.FromArgb(47, 85, 151), Color.FromArgb(65, 113, 156), Color.FromArgb(142, 169, 219), Color.FromArgb(180, 198, 231), Color.FromArgb(217, 226, 243) }
            };
            Color[] activePalette = palettes[Math.Min(palettes.Length - 1, Math.Max(0, chart.ColorPaletteIndex))];

            // Determine Data Min / Max
            double maxVal = 1.0;
            if (chart.Data.Values != null && chart.Data.Values.Count > 0)
            {
                foreach (var row in chart.Data.Values)
                {
                    if (row == null) continue;
                    foreach (var v in row) { if (v > maxVal) maxVal = v; }
                }
            }
            if (maxVal <= 5.0) maxVal = 5.0;
            else if (maxVal <= 10.0) maxVal = 10.0;
            else if (maxVal <= 25.0) maxVal = 25.0;
            else if (maxVal <= 50.0) maxVal = 50.0;
            else if (maxVal <= 100.0) maxVal = 100.0;
            else maxVal = Math.Ceiling(maxVal / 50.0) * 50.0;

            int legendH = chart.ShowLegend ? (int)(28 * ZoomLevel) : (int)(10 * ZoomLevel);
            int plotX = chartX + (int)(42 * ZoomLevel);
            int plotY = chartY + titleH;
            int plotW = chartW - (int)(60 * ZoomLevel);
            int plotH = chartH - titleH - legendH - (int)(18 * ZoomLevel);

            if (plotW > 50 && plotH > 30)
            {
                if (chart.Data.ChartType == "Pie" || chart.Data.ChartType == "Doughnut")
                {
                    int pieSize = Math.Min(plotW, plotH);
                    Rectangle pieRect = new Rectangle(plotX + (plotW - pieSize) / 2, plotY + (plotH - pieSize) / 2, pieSize, pieSize);

                    double totalPie = 0;
                    if (chart.Data.Values != null)
                    {
                        foreach (var row in chart.Data.Values)
                        {
                            if (row != null && row.Count > 0) totalPie += Math.Max(0, row[0]);
                        }
                    }
                    if (totalPie <= 0) totalPie = 1.0;

                    float startAngle = 0f;
                    int numSlices = chart.Data.Categories != null ? chart.Data.Categories.Count : 0;
                    for (int k = 0; k < numSlices; k++)
                    {
                        double val = (chart.Data.Values != null && k < chart.Data.Values.Count && chart.Data.Values[k].Count > 0) ? Math.Max(0, chart.Data.Values[k][0]) : 1.0;
                        float sweep = (float)(val / totalPie * 360.0);
                        if (sweep > 0)
                        {
                            Color sliceCol = activePalette[k % activePalette.Length];
                            using (SolidBrush sBrush = new SolidBrush(sliceCol))
                            using (Pen whiteBorder = new Pen(bgColor, 1.5f))
                            {
                                g.FillPie(sBrush, pieRect, startAngle, sweep);
                                g.DrawPie(whiteBorder, pieRect, startAngle, sweep);
                            }
                            startAngle += sweep;
                        }
                    }

                    if (chart.Data.ChartType == "Doughnut")
                    {
                        int holeSize = (int)(pieSize * 0.48f);
                        Rectangle holeRect = new Rectangle(pieRect.X + (pieSize - holeSize) / 2, pieRect.Y + (pieSize - holeSize) / 2, holeSize, holeSize);
                        using (SolidBrush holeB = new SolidBrush(bgColor))
                        using (Pen hPen = new Pen(borderColor, 1f))
                        {
                            g.FillEllipse(holeB, holeRect);
                            g.DrawEllipse(hPen, holeRect);
                        }
                    }
                }
                else // Cartesian Charts
                {
                    using (Pen gridP = new Pen(gridCol, 1f))
                    using (Font axFont = new Font("Segoe UI", 7.5f * ZoomLevel, FontStyle.Regular))
                    using (SolidBrush axBrush = new SolidBrush(textCol))
                    {
                        for (int gr = 0; gr <= 5; gr++)
                        {
                            int gy = plotY + (int)(gr * (plotH / 5.0f));
                            if (chart.ShowGridlines)
                            {
                                g.DrawLine(gridP, plotX, gy, plotX + plotW, gy);
                            }
                            double yVal = maxVal * (5 - gr) / 5.0;
                            string yStr = yVal >= 10 ? yVal.ToString("0") : yVal.ToString("0.#");
                            SizeF ySz = g.MeasureString(yStr, axFont);
                            g.DrawString(yStr, axFont, axBrush, plotX - ySz.Width - 4, gy - ySz.Height / 2);
                        }

                        using (Pen axLinePen = new Pen(Color.FromArgb(160, 160, 160), 1f))
                        {
                            g.DrawLine(axLinePen, plotX, plotY + plotH, plotX + plotW, plotY + plotH);
                            g.DrawLine(axLinePen, plotX, plotY, plotX, plotY + plotH);
                        }
                    }

                    int numCats = chart.Data.Categories != null ? chart.Data.Categories.Count : 0;
                    int numSeries = chart.Data.SeriesNames != null ? chart.Data.SeriesNames.Count : 0;

                    if (numCats > 0 && numSeries > 0)
                    {
                        float catW = (float)plotW / numCats;

                        if (chart.Data.ChartType == "Line")
                        {
                            for (int s = 0; s < numSeries; s++)
                            {
                                Color serCol = activePalette[s % activePalette.Length];
                                List<PointF> pts = new List<PointF>();
                                for (int c = 0; c < numCats; c++)
                                {
                                    double val = (c < chart.Data.Values.Count && s < chart.Data.Values[c].Count) ? chart.Data.Values[c][s] : 0;
                                    float px = plotX + c * catW + catW / 2.0f;
                                    float py = plotY + plotH - (float)(val / maxVal * plotH);
                                    pts.Add(new PointF(px, py));
                                }

                                if (pts.Count > 1)
                                {
                                    using (Pen linePen = new Pen(serCol, 2.5f * ZoomLevel))
                                    {
                                        g.DrawLines(linePen, pts.ToArray());
                                    }
                                }
                                foreach (var pt in pts)
                                {
                                    using (SolidBrush dotBrush = new SolidBrush(serCol))
                                    {
                                        g.FillEllipse(dotBrush, pt.X - 4 * ZoomLevel, pt.Y - 4 * ZoomLevel, 8 * ZoomLevel, 8 * ZoomLevel);
                                        g.FillEllipse(Brushes.White, pt.X - 2 * ZoomLevel, pt.Y - 2 * ZoomLevel, 4 * ZoomLevel, 4 * ZoomLevel);
                                    }
                                }
                            }
                        }
                        else if (chart.Data.ChartType == "Area")
                        {
                            for (int s = 0; s < numSeries; s++)
                            {
                                Color serCol = activePalette[s % activePalette.Length];
                                List<PointF> pts = new List<PointF>();
                                pts.Add(new PointF(plotX, plotY + plotH));
                                for (int c = 0; c < numCats; c++)
                                {
                                    double val = (c < chart.Data.Values.Count && s < chart.Data.Values[c].Count) ? chart.Data.Values[c][s] : 0;
                                    float px = plotX + c * catW + catW / 2.0f;
                                    float py = plotY + plotH - (float)(val / maxVal * plotH);
                                    pts.Add(new PointF(px, py));
                                }
                                pts.Add(new PointF(plotX + plotW, plotY + plotH));

                                using (SolidBrush areaB = new SolidBrush(Color.FromArgb(120, serCol.R, serCol.G, serCol.B)))
                                using (Pen areaP = new Pen(serCol, 2.0f * ZoomLevel))
                                {
                                    g.FillPolygon(areaB, pts.ToArray());
                                    if (pts.Count > 2)
                                    {
                                        PointF[] linePts = new PointF[numCats];
                                        for (int k = 0; k < numCats; k++) linePts[k] = pts[k + 1];
                                        g.DrawLines(areaP, linePts);
                                    }
                                }
                            }
                        }
                        else // Column Charts (Clustered / Stacked / 100%)
                        {
                            float totalBarGroupW = catW * 0.75f;
                            float barW = totalBarGroupW / numSeries;

                            for (int c = 0; c < numCats; c++)
                            {
                                float groupStartX = plotX + c * catW + (catW - totalBarGroupW) / 2.0f;

                                for (int s = 0; s < numSeries; s++)
                                {
                                    double val = (c < chart.Data.Values.Count && s < chart.Data.Values[c].Count) ? chart.Data.Values[c][s] : 0;
                                    float bH = (float)(val / maxVal * plotH);
                                    float bx = groupStartX + s * barW;
                                    float by = plotY + plotH - bH;

                                    Color serCol = activePalette[s % activePalette.Length];
                                    using (SolidBrush barB = new SolidBrush(serCol))
                                    using (Pen whiteBorder = new Pen(Color.FromArgb(240, 240, 240), 1f))
                                    {
                                        g.FillRectangle(barB, bx, by, Math.Max(2, barW - 1), bH);
                                        g.DrawRectangle(whiteBorder, bx, by, Math.Max(2, barW - 1), bH);
                                    }

                                    if (chart.ShowDataLabels && bH > 14)
                                    {
                                        using (Font dlFont = new Font("Segoe UI", 7.0f * ZoomLevel, FontStyle.Bold))
                                        using (SolidBrush dlBrush = new SolidBrush(textCol))
                                        {
                                            string dStr = val >= 10 ? val.ToString("0") : val.ToString("0.#");
                                            SizeF dSz = g.MeasureString(dStr, dlFont);
                                            g.DrawString(dStr, dlFont, dlBrush, bx + (barW - dSz.Width) / 2, by - dSz.Height - 1);
                                        }
                                    }
                                }
                            }
                        }

                        using (Font catFont = new Font("Segoe UI", 8.0f * ZoomLevel, FontStyle.Regular))
                        using (SolidBrush catBrush = new SolidBrush(textCol))
                        {
                            for (int c = 0; c < numCats; c++)
                            {
                                string cName = chart.Data.Categories[c];
                                SizeF cSz = g.MeasureString(cName, catFont);
                                float cx = plotX + c * catW + (catW - cSz.Width) / 2.0f;
                                float cy = plotY + plotH + (int)(5 * ZoomLevel);
                                g.DrawString(cName, catFont, catBrush, cx, cy);
                            }
                        }
                    }
                }
            }

            // Legend at Bottom
            if (chart.ShowLegend && chart.Data.SeriesNames != null && chart.Data.SeriesNames.Count > 0)
            {
                using (Font lFont = new Font("Segoe UI", 8.5f * ZoomLevel, FontStyle.Regular))
                using (SolidBrush lBrush = new SolidBrush(textCol))
                {
                    int legY = chartY + chartH - (int)(22 * ZoomLevel);
                    float lx = chartX + (int)(20 * ZoomLevel);

                    int numLegs = (chart.Data.ChartType == "Pie" || chart.Data.ChartType == "Doughnut") ? (chart.Data.Categories != null ? chart.Data.Categories.Count : 0) : chart.Data.SeriesNames.Count;

                    for (int s = 0; s < numLegs; s++)
                    {
                        string sName = (chart.Data.ChartType == "Pie" || chart.Data.ChartType == "Doughnut") ? chart.Data.Categories[s] : chart.Data.SeriesNames[s];
                        Color col = activePalette[s % activePalette.Length];
                        using (SolidBrush cb = new SolidBrush(col))
                        {
                            g.FillRectangle(cb, lx, legY + (int)(2 * ZoomLevel), (int)(10 * ZoomLevel), (int)(10 * ZoomLevel));
                        }
                        g.DrawString(sName, lFont, lBrush, lx + (int)(14 * ZoomLevel), legY);
                        SizeF lSz = g.MeasureString(sName, lFont);
                        lx += lSz.Width + (int)(22 * ZoomLevel);
                        if (lx > chartX + chartW - (int)(30 * ZoomLevel)) break;
                    }
                }
            }

            // Selection Frame & 8 Handles & 4 Floating Action Buttons
            if (chart.IsSelected)
            {
                using (Pen selPen = new Pen(Color.FromArgb(0, 120, 215), 1.5f))
                {
                    g.DrawRectangle(selPen, chartX - 1, chartY - 1, chartW + 2, chartH + 2);
                }

                int hs = (int)(7 * ZoomLevel);
                Point[] handlePts = new Point[]
                {
                    new Point(chartX - hs/2, chartY - hs/2),
                    new Point(chartX + chartW/2 - hs/2, chartY - hs/2),
                    new Point(chartX + chartW - hs/2, chartY - hs/2),
                    new Point(chartX + chartW - hs/2, chartY + chartH/2 - hs/2),
                    new Point(chartX + chartW - hs/2, chartY + chartH - hs/2),
                    new Point(chartX + chartW/2 - hs/2, chartY + chartH - hs/2),
                    new Point(chartX - hs/2, chartY + chartH - hs/2),
                    new Point(chartX - hs/2, chartY + chartH/2 - hs/2)
                };

                using (SolidBrush hBrush = new SolidBrush(Color.White))
                using (Pen hPen = new Pen(Color.FromArgb(0, 120, 215), 1.2f))
                {
                    foreach (var hp in handlePts)
                    {
                        g.FillRectangle(hBrush, hp.X, hp.Y, hs, hs);
                        g.DrawRectangle(hPen, hp.X, hp.Y, hs, hs);
                    }
                }

                DrawChartFloatingButtons(g, chart, new Rectangle(chartX, chartY, chartW, chartH));
            }
        }

        private void DrawChartFloatingButtons(D2DGraphics g, DocChartObject chart, Rectangle chartRect)
        {
            int btnSize = 22;
            int btnX = chartRect.Right + 6;
            int startBtnY = chartRect.Top + 2;

            LayoutBtnChartRect = new Rectangle(btnX, startBtnY, btnSize, btnSize);
            PlusBtnChartRect = new Rectangle(btnX, startBtnY + 28, btnSize, btnSize);
            StyleBtnChartRect = new Rectangle(btnX, startBtnY + 56, btnSize, btnSize);
            FilterBtnChartRect = new Rectangle(btnX, startBtnY + 84, btnSize, btnSize);

            using (Pen borderPen = new Pen(Color.FromArgb(180, 200, 220), 1.2f))
            {
                // 1. [ ⌒ ] Layout Options
                g.FillRectangle(chart.ShowLayoutOptions ? new SolidBrush(Color.FromArgb(215, 235, 255)) : Brushes.White, LayoutBtnChartRect);
                g.DrawRectangle(borderPen, LayoutBtnChartRect);
                using (Pen archP = new Pen(Color.FromArgb(0, 120, 215), 1.5f))
                {
                    DrawVectorArch(g, archP, LayoutBtnChartRect.X + 4, LayoutBtnChartRect.Y + 5, 14, 11);
                }

                // 2. [ + ] Chart Elements
                g.FillRectangle(chart.ShowElementsMenu ? new SolidBrush(Color.FromArgb(215, 235, 255)) : Brushes.White, PlusBtnChartRect);
                g.DrawRectangle(borderPen, PlusBtnChartRect);
                using (Pen plusP = new Pen(Color.FromArgb(16, 124, 65), 2f))
                {
                    g.DrawLine(plusP, PlusBtnChartRect.X + 6, PlusBtnChartRect.Y + 11, PlusBtnChartRect.X + 16, PlusBtnChartRect.Y + 11);
                    g.DrawLine(plusP, PlusBtnChartRect.X + 11, PlusBtnChartRect.Y + 6, PlusBtnChartRect.X + 11, PlusBtnChartRect.Y + 16);
                }

                // 3. [ 🖌 ] Chart Styles
                g.FillRectangle(chart.ShowStylesMenu ? new SolidBrush(Color.FromArgb(215, 235, 255)) : Brushes.White, StyleBtnChartRect);
                g.DrawRectangle(borderPen, StyleBtnChartRect);
                using (SolidBrush bB = new SolidBrush(Color.FromArgb(0, 120, 215)))
                {
                    g.FillRectangle(bB, StyleBtnChartRect.X + 6, StyleBtnChartRect.Y + 5, 10, 6);
                    g.FillPolygon(bB, new Point[] { new Point(StyleBtnChartRect.X + 8, StyleBtnChartRect.Y + 11), new Point(StyleBtnChartRect.X + 14, StyleBtnChartRect.Y + 11), new Point(StyleBtnChartRect.X + 11, StyleBtnChartRect.Y + 16) });
                }

                // 4. [ ⏚ ] Values Filter
                g.FillRectangle(chart.ShowFilterMenu ? new SolidBrush(Color.FromArgb(215, 235, 255)) : Brushes.White, FilterBtnChartRect);
                g.DrawRectangle(borderPen, FilterBtnChartRect);
                using (Pen fPen = new Pen(Color.FromArgb(80, 80, 80), 1.5f))
                {
                    g.DrawLine(fPen, FilterBtnChartRect.X + 5, FilterBtnChartRect.Y + 6, FilterBtnChartRect.X + 17, FilterBtnChartRect.Y + 6);
                    g.DrawLine(fPen, FilterBtnChartRect.X + 7, FilterBtnChartRect.Y + 10, FilterBtnChartRect.X + 15, FilterBtnChartRect.Y + 10);
                    g.DrawLine(fPen, FilterBtnChartRect.X + 9, FilterBtnChartRect.Y + 14, FilterBtnChartRect.X + 13, FilterBtnChartRect.Y + 14);
                }
            }
        }

